const campaign={edits:[
 {field:'premise',find:`Corvane is a world that was once rung like a great cathedral.`,replace:`Corvane is a land far out in the Trackless Sea of the Forgotten Realms, a world of its own that was once rung like a great cathedral.`},
 {field:'premise',find:`They trade memories for coin. They have forgotten what the bells sounded like.`,replace:`They trade memories as money, and lately for gold. They have forgotten what the bells sounded like.

For four centuries a wall of storm at sea hid Corvane from the rest of the world. Thirty years ago a passage opened, and ships from Faerûn's Sword Coast began to arrive. They anchor at Pellmoor, on the still waters of the Mute Mere, now the busiest port in Corvane.`},
 {field:'arc',find:`> "The fog lifts off the Mute Mere in long grey ribbons, and the village of Pellmoor comes into sight: reed roofs, leaning docks, nets like the sails of drowned ships. The chapel bell is silent. A girl stands on the ferry-dock, staring at the water with her hands folded tight. She does not look up when you arrive. She says, without turning: *'Are you here for the tongue, or for the bell?'*"`,replace:s1Opening.replace},
]};
const planner={locked:[{find:`Source canon: Part 3.3 wins conflicts within the manuscript.`,replace:`Source canon: the v6 pages (CORVANE IN THE REALMS, MEMORY AS MONEY, PELLMOOR LANDING) and then Part 3.3 win conflicts within the manuscript. Corvane is part of the Forgotten Realms; the Seam opened in 382 SS (1462 DR); Pellmoor is a busy port; memory is money alongside gold; rules are D&D 2024.`}]};
// Revision 7.2 retires the IsoForge map kits (DM's decision, 2026-11-01: not ready yet): the kit section at the end of each Act I plan,
// the three "Maps and visual prep" wiki pages and the three IsoForge saved cards. Waypoint lists each removal for review.
const remove={sections:[{heading:'## IsoForge scene kit',until:'Prepared visual staging only. No events or outcomes are implied.'}],pages:['sb-isoforge-kit-1','sb-isoforge-kit-2','sb-isoforge-kit-3'],cards:['sb-isoforge-session-1','sb-isoforge-session-2','sb-isoforge-session-3'],note:'The IsoForge map kits are retired for now.'};
// Revision 7.12: every named NPC gets a first look to read aloud and things to say (npc-voices.cjs), before the page's
// Voice and Wants lines. The pack's own pages carry them in their text; the book's pages take them as edits.
const said=t=>'"'+t.replace(/"/g,"'")+'"';
const voiceEdits=v=>[
 {find:'- **Voice:**',unless:'- **First look (read aloud):**',replace:'- **First look (read aloud):** '+said(v.look)+'\n- **Voice:**'},
 {find:'- **Wants:**',unless:'- **Things to say:**',replace:'- **Things to say:**\n'+v.lines.map(([k,t])=>'  - *'+k+':* '+said(t)).join('\n')+'\n- **Wants:**'}];
for(const v of require('./npc-voices.cjs')){
 const edits=voiceEdits(v),page=pages.find(p=>p.id===v.id),at=pageEdits.find(x=>x.id===v.id);
 if(page)page.body=edits.reduce((b,e)=>b.includes(e.unless)?b:b.replace(e.find,()=>e.replace),page.body);
 else if(at)at.edits.push(...edits);
 else pageEdits.push({id:v.id,edits});
}
// Revision 7.16: the book's copy of each session in the wiki takes the same plan fixes; the Sexton's and Maudrin's pages
// give their Combat stat blocks; the old Encounter Lists page is rebuilt from the fight cards, so it matches the Combat tab.
const addPageEdits=(id,edits)=>{const at=pageEdits.find(x=>x.id===id);if(at)at.edits.push(...edits);else pageEdits.push({id,edits});};
for(const [id,fixes] of [[S5,[s5Lock]],[S6,[s6Tessa]],[S9,[s9Theft,s9Dawn]],[S10,[s10Cold]],[S11,[s11Ambush]],[S13,[s13Sexton]],[S15,[s15Escort]],
 [S16A,[s16aGolems]],[S16B,[s16bCount,s16bNight]],[S17A,[s17aYenna]],[S17B,[s17bCount,s17bDream]],[S18A,[s18aConcord,s18aPrice,s18aHounds]],
 [S18B,[s18bStair,s18bCorin]],[S23,[s23Force,s23Strike]],[S24,[s24Seal,s24Maudrin]],[S25,[s25Stair]],['sb-33f69fa6e5d53e5d',[s16bNight]]]) addPageEdits(id,fixes);
addPageEdits('sb-bb93b0c927c2b0dc',[{find:'- **Stat-lite:** Glass Sexton (CR 5). See Appendix A.',
 replace:'- **2024 stat block:** The Glass Sexton (Imber Vesk), CR 7, in the Combat tab. Session 13 runs his two phases.'}]);
addPageEdits('sb-24aea1701bba67cd',[{find:'- **Stat-lite:** Campaign caster prototype (provisional CR 6). Casts *Silence* and *Counterspell*. Hushmen guard her.',
 replace:'- **2024 stat block:** Chancellor Maudrin Vesk (CR 8) up to the Strike (Session 23); Maudrin Vesk, Keeper of the Seventh (CR 12) from the Summit (Session 24). Both are in the Combat tab. She casts *Silence* and *Counterspell*, and Hushmen guard her.'}]);
const firstSentence=t=>((t||'').match(/^.*?[.!?](?=\s|$)/)||[t||''])[0];
const fights=fs.readdirSync(__dirname).filter(f=>/^act.*\.json$/.test(f)).sort()
 .flatMap(f=>JSON.parse(fs.readFileSync(path.join(__dirname,f),'utf8')).encounters||[])
 .map((e,i)=>{const m=e.id.match(/^enc-s(\d+)([ab]?)-/);return {e,i,n:+m[1],x:m[2]};})
 .sort((a,b)=>a.n-b.n||a.x.localeCompare(b.x)||a.i-b.i);
const encounterBody=`*This list is built from the campaign's fight cards, so it matches the Combat tab, where each card opens with its stat blocks. The level is the one the fight is written for; each card's scale note says how to grow or shrink it for your table. Prepare a way out, a talk, or a goal other than killing for every fight: each card says how it ends.*

`+fights.map(({e,n,x})=>'- **Session '+n+x.toUpperCase()+', '+e.title+':** '+e.creatures.map(c=>c.count>1?c.name+' ×'+c.count:c.name).join(', ')+'. *'+firstSentence(e.scale)+'* Ends: '+firstSentence(e.exit)).join('\n')+'\n\n---';
addPageEdits('sb-45e7ac6f16c59fd8',[{find:'__WHOLE__',replace:encounterBody,unless:"This list is built from the campaign's fight cards"}]);
// Revision 7.16: pop-outs. A name in a plan opens a page only when exactly one page goes by it, so the three people who shared a
// place's name with its page give it back, the book's place and faction pages take the names the plans use, and the bells, the
// campaign's own words and the people the guides name session after session get pages of their own.
for (const [id,drop] of [['v6-npc-brannagh',"Pilots' Hall"],['v6-npc-sela','Reckoning House'],['v6-npc-venn','Vennmark Coster']]){
 const p=pages.find(x=>x.id===id);p.aliases=p.aliases.split(/,\s*/).filter(a=>a!==drop).join(', ');}
const addAliases=(id,to)=>{const at=pageEdits.find(x=>x.id===id);if(at)at.aliases={from:'',to};else pageEdits.push({id,edits:[],aliases:{from:'',to}});};
for (const [id,to] of [['sb-efcdea29187495d0','Hallowmere, Grey City'],['sb-462b2b0d93fd03c2','Pellmoor'],['sb-74c9bfaa3dfbf94e','Shuttered Bell'],
 ['sb-30af780baa82038c','Tithe-Ledger, Tithe-Ledger Room'],['sb-f7d5d89f237775c9','Bone Archive, Sealed Stacks'],['sb-f04ad09a8410cbb6','Sleeping Hall'],
 ['sb-a642c9ff7f79bce3','Hush Shrine'],['sb-72c0b21c8d4cfbdb','Frost Spire'],['sb-655447336897e411','Heart-Hall, Ironhorn Steppe, Ironhorn camp'],
 ['sb-9183922a9ac8e591','Memory Shore'],['sb-426b1a753733a92d','Ossa Belfry, drowned town'],['sb-fd617b364bd1b149','Bellwright, Bellwrights'],
 ['sb-a97db13025803821','Ironhorn, Ironhorn Compact'],['sb-bb6db9d171c44c8e','ferry-folk, Old Shore'],['sb-4bdfcc6a023f3b01','Dawn Order']]) addAliases(id,to);
const lorePage=(id,title,aliases,body,kind='Lore')=>pages.push({id,title,kind,status:'Confirmed',visibility:'DM only',aliases,body});
const weight='Heavy if no bell or one bell has rung before it, Grievous after two or three, Ruinous after four or five. Name the kind and the weight, never the memory, and wait for a yes.';
for (const [id,title,aliases,lines] of [
 ['v7-bell-vaer','VAER, THE BELL OF DAWN',"Vaer, Vaer's Heart",[
  '**Vaer is the bell of dawn, law and beginnings.** It hangs in Vaer\'s Belfry in Hallowmere, a prison and watchtower, in chains of silence-stone above the Dawn Order\'s barracks.',
  '- **While it is silent:** the Long Dusk. The dawn never fully comes to Hallowmere.',
  '- **Its Heart:** Vaer\'s Heart, in the Dawn Order armory. Ser Haldric Mose holds it.',
  '- **The Toll:** a memory of a beginning. '+weight,
  '- **When it can ring:** Session 9.',
  '- **What ringing does:** one whole day of real sun, then a real dawn every morning for a year. The Court issues a Silence Warrant for the Ringer; the Dawn Order enforces it only if Captain Rook lost the oath-duel in Session 6.']],
 ['v7-bell-ossa','OSSA, THE BELL OF MEMORY',"Ossa, Ossa's Heart",[
  '**Ossa is the bell of memory, ancestors and rest.** It hangs in the Ossa Belfry in Old Pellmoor, the drowned town under the Mute Mere.',
  '- **While it is silent:** the dead cannot rest. The Drowned Choir sings grief in Ondra Sallow\'s voice and hunts the Mere.',
  '- **Its Heart:** Ossa\'s Heart. Tam Harrow stole it in 392 SS and hid it in an oilskin in the reeds; Ila Harrow has it in Act I.',
  '- **The Toll:** a memory of someone who has died. '+weight,
  '- **When it can ring:** Session 2 (if they bring the Heart down that night), Session 3, or on a Pellmoor detour in Session 9.',
  '- **What ringing does:** the dead of the Mere are free to rest, and the Choir falls silent and stops hunting. Only the verse releases the Cantor: she sings her own name, then goes quiet. Mother Sallow remembers her husband.']],
 ['v7-bell-hieme','HIEME, THE BELL OF WINTER',"Hieme, Hieme's Heart, Frost Heart",[
  '**Hieme is the bell of winter and endurance.** It hangs in the Frost Spire in Glassreach.',
  '- **While it is silent:** winter is frozen in place. Glassreach froze in a single night in 2 SS, and the Stilled stand in it still.',
  '- **Its Heart:** the Frost Heart, set in the Glass Sexton\'s crown. He can give it in Session 13.',
  '- **The Toll:** a memory, any memory. '+weight+' If nobody will pay, it does not ring.',
  '- **When it can ring:** Session 14.',
  '- **What ringing does:** a thaw. The Stilled wake over several weeks (Session 15). If the Sexton is alive, he weeps. The Court sends Lady Isolde Drave to recover the bell.']],
 ['v7-bell-calla','CALLA, THE BELL OF HARVEST',"Calla, Calla's Heart, Old Granary",[
  '**Calla is the bell of harvest, grace and generosity.** It hangs in the Old Granary at Kell\'s Crossing.',
  '- **While it is silent:** crops fail. Bet Ostrow rang it once, at nine, in 340 SS, and was Tithed for it.',
  '- **Its Heart:** Calla\'s Heart, in the Tithe-Ledger Room of the Court\'s vault, on a shelf marked "Harvest, Withheld". Maudrin Vesk controls it.',
  '- **The Toll:** a gift, given to someone in need, and never returned. '+weight,
  '- **When it can ring:** Session 9, at Kell\'s Crossing.',
  '- **What ringing does:** one harvest season. The ash fields bloom and there is bread for everyone. Court Tithe-men raid the Crossing for the rest of the season, and collectors try to take the Ringer.']],
 ['v7-bell-thrane','THRANE, THE BELL OF STORMS',"Thrane, Thrane's Heart, Lightning Shafts",[
  '**Thrane is the bell of storm, courage and war.** It hangs in the Lightning Shafts at Brassfall.',
  '- **While it is silent:** no storm has crossed the mountains since the Quiet Night. The storms went out to sea instead, and became the Stormwall.',
  '- **Its Heart:** Thrane\'s Heart, in the Heart-Hall of the Ironhorn camp. Thane Oru Kessa holds it, and its dead lightning is killing her.',
  '- **The Toll:** a sense. '+weight,
  '- **When it can ring:** Session 19A, or as the second bell in Session 21.',
  '- **What ringing does:** storms return, storm-stones blaze and metal hums. The Stormwall loosens. Kessa\'s sickness eases and the Ironhorn celebrate. The Court sends a strike force, and Maudrin moves.']],
 ['v7-bell-mirel','MIREL, THE BELL OF DREAMS',"Mirel, Mirel's Heart",[
  '**Mirel is the bell of dreams and hope.** It hangs in the Sleeping Hall at Vael Tor.',
  '- **While it is silent:** nightmares walk. The Sleepless come out of Vael Tor in the shape of a sleeper\'s worst fear.',
  '- **Its Heart:** Mirel\'s Heart, in the Sealed Stacks of the Bone Archive. The Librarian of the Sealed Book keeps it.',
  '- **The Toll:** a fear, which the bell gives the Ringer. '+weight,
  '- **When it can ring:** Session 16B (as soon as they reach it), Session 19B, or as the second bell in Session 21.',
  '- **What ringing does:** the Sleepless dissolve and the sleepers dream gently. The Hush\'s lullaby changes key. Hushmen come to the Tor.']],
 ['v7-bell-ysh','YSH, THE SEVENTH BELL','Ysh, the Seventh, Seventh Bell',[
  '**Ysh is the bell of sleep, peace and rest, and it is silent on purpose.** It hangs in the Hush Shrine, deep under Vael Tor. Its silence holds Oum, the Dreamer, asleep.',
  '- **Its Heart:** the Tuning Key. Maudrin Vesk keeps it in her palace vault in Hallowmere until she leaves the city (Session 22), then carries it in a silence-stone case.',
  '- **The Toll, if it is struck:** all six kinds at once, each Ruinous.',
  '- **Never struck:** in the Concord the Key is seated in the Seventh and never struck, and the Ringer pays the Great Toll instead.',
  '- **Struck:** the Hush opens and Oum begins to wake (Hush Unbound: Remake or Unmake).',
  '- **Where it is decided:** Sessions 26 and 27.']],
]) lorePage(id,title,aliases,lines.join('\n'));
for (const [id,title,aliases,lines,kind] of [
 ['v7-term-ringer','THE RINGER','Ringer, Ringers',[
  '**The Ringer is whoever rings a bell, and the one who pays its Toll.**',
  '- **Who may ring:** any willing adult who is there. Children never ring; Ila may stand beside the Ringer. A character whose player is absent never pays a Toll, and the dead pay nothing.',
  '- **Before it rings:** say the kind of Toll and its weight, never the exact memory, and wait for a yes. If nobody says yes, the bell does not ring and nothing is taken.',
  '- **The weight:** Heavy if no bell or one bell has rung before, Grievous after two or three, Ruinous after four or five. Ysh takes all six kinds at once, each Ruinous.',
  '- **After it rings:** you choose what was taken, within the kind, and it goes on the Toll tracker.',
  '- **Afterwards:** once Vaer rings, the Court issues a Silence Warrant for the Ringer.']],
 ['v7-term-concord','THE CONCORD','Concord',[
  '**The Concord is the ending in which the world is mended.** It is the first of the four paths.',
  '- **What it needs:** all six bells rung (Vaer, Ossa, Hieme, Calla, Thrane and Mirel), Ysh still unstruck, and the Tuning Key in the party\'s hands.',
  '- **The rite:** a willing Ringer seats the Key in the Seventh, never striking it, and pays the Great Toll, giving up their whole name. Session 27 runs it.',
  '- **What it makes:** a restored world, not a perfect one.',
  '- **How the party learns of it:** Edda Thorne\'s diary gives the first hint (Session 5). Corin Aldeth shows them Edda Thorne\'s Notes, which describe it in full (Session 18A).',
  '- **The other paths:** Hush Unbound (Ysh is struck: Remake or Unmake), the Empty Choir (the Court secures the Key and the Long Dusk goes on) and the Second Dawn (the party seals the Key away unstruck, and the world is partly restored).']],
 ['v7-term-tithe','THE TITHE OF MEMORY','Tithe, Tithes, Tithe of Memory, Tithe Clock',[
  '**The Tithe of Memory is the Quiet Court\'s tax in memories.** Since 1 SS, people have given up memories in exchange for protection and tax relief. It pays for the silence-stones and the Court\'s grip on Tonework.',
  '- **Where:** memories are taken and recorded at the Hall of Tithes. The master ledger is in the Tithe-Ledger Room.',
  '- **What it does to people:** those who give too much become Blanks.',
  '- **The Tithe Clock:** each night the party spends inside a Court-controlled city adds one tick, from 0. At 6, the Hushmen sweep the city with a checkpoint on every road. At 12, the Court puts silence-stones in every street. The clock resets after a week away from Court cities; checkpoints and stones already placed stay.']],
 ['v7-term-blanks','BLANKS','Blanks',[
  '**A Blank is someone who has given away so many memories that they no longer know their own family.** They are common in Hallowmere.',
  '- Jonah Bray\'s mother, Mara Bray, is a Blank: she was Tithed of him.',
  '- In Session 7, hundreds of them surround the Hall of Tithes, asking who they were.']],
 ['v7-term-quiet-night','THE QUIET NIGHT','Quiet Night',[
  '**The Quiet Night is the night of 0 SS, when all seven bells fell silent in one breath.** Years are counted from it: SS is years since, BS years before.',
  '- **What happened:** High Sexton Imber Vesk took the Tuning Key from the Bellwright Tower\'s reliquary and tuned the bells into one long, gentle spring, against Edda Thorne\'s warning. The Key sang against the bells, and the Choir went silent. Brassfall\'s storms stopped the same night.',
  '- **What people believe:** that the bells caused it. The Ninefold Church became the Quiet Court on that belief. Within the Court\'s leaders, only Maudrin Vesk knows that the Key did it.',
  '- **The Key afterwards:** it passed to Imber\'s daughter, Cassia Vesk, and stayed in the Vesk reliquary until Maudrin took it in 374 SS.',
  '- **Where the truth comes out:** Edda Thorne\'s diary (Session 5), the Glass Sexton\'s story (Session 13) and the truth of the Key (Session 22).']],
 ['v7-term-warrant','THE SILENCE WARRANT','Silence Warrant',[
  '**A Silence Warrant is a Court order that lets any Hushman arrest the Ringer on sight in a Court city.** The Court issues it after Vaer rings (Session 9).',
  '- The Dawn Order enforces it only if Captain Rook lost the oath-duel (Session 6).',
  '- While it stands, a bluff about the Ringer is 2 harder.']],
 ['v7-term-key','THE TUNING KEY','Tuning Key',[
  '**The Tuning Key is the Heart of Ysh, the Seventh Bell, and the most important object in the campaign.**',
  '- **Its history:** Imber Vesk used it on the Quiet Night. It passed to his daughter, Cassia Vesk, and stayed in the Vesk reliquary until Maudrin Vesk took it in 374 SS, at twenty.',
  '- **Where it is:** Maudrin\'s palace vault in Hallowmere until she leaves the city (Session 22). After that she carries it in a silence-stone case.',
  '- **What it decides:** seated in Ysh and never struck, it makes the Concord. Struck, it opens the Hush. Sealed away unstruck, it gives the Second Dawn. Kept by the Court, it means the Empty Choir.']],
 ['v7-term-oum','OUM, THE DREAMER','Oum, the Dreamer',[
  '**Oum, the Dreamer, is the god dreaming the world.** Nobody has ever seen Oum.',
  '- The seven bells were cast to keep the dream steady. Ysh keeps Oum asleep; the other six keep the world in shape while the dream lasts.',
  '- Some believe Oum is dying. Others believe Oum is waking.',
  '- If Ysh is struck, the Hush opens and Oum begins to wake.']],
 ['v7-term-silence-stone','SILENCE-STONE','silence-stone, silence-stones',[
  '**Silence-stone is a grey stone that drinks sound.** The Court uses it to hold down Tonework.',
  '- Hushmen wear silence-stone gloves. Vaer hangs in chains of it. Maudrin carries the Tuning Key in a silence-stone case once she leaves Hallowmere.',
  '- At 12 on the Tithe Clock, the Court puts silence-stones in every street of the city.']],
 ['v7-term-long-dusk','THE LONG DUSK','Long Dusk',[
  '**The Long Dusk is the grey, endless twilight over Hallowmere since 1 SS.** The dawn has not come since Vaer fell silent.',
  '- Ringing Vaer brings one day of real sun, then a real dawn every morning for a year.',
  '- If the Court secures the Tuning Key (the Empty Choir), the Long Dusk goes on.']],
 ['v7-place-brass-road','THE BRASS ROAD','Brass Road',[
  '**The Brass Road is the old trade road from Brassfall to the steppe,** partly collapsed since the Long Unraveling: bronze carts, ruts, and a sky that flickers with no clouds in it.',
  '- Session 16A opens on it. Corin Aldeth\'s workshop is under a tavern on it (Session 18A), and the Court\'s strike force comes up it (Session 19A).',
  '- Thane Oru Kessa took Thrane\'s Heart from it, and the Heart has been eating her hands since.'],'Location'],
 ['v7-place-hall-of-tithes','THE HALL OF TITHES','Hall of Tithes',[
  '**The Hall of Tithes is where Hallowmere\'s memories are taken and recorded.**',
  '- Court pensions are paid there (Session 4). Hushmen don\'t chase past it.',
  '- **The clerks\' dormitory** (Session 6): one corridor, three doors, a stair-head with an alarm bell, and a kitchen at the bottom. Tessa Caddock is held there.',
  '- **Session 7:** hundreds of Blanks surround it, asking who they were, and Sergeant Orla Gaunt\'s Hushmen form a line on its steps.'],'Location'],
]) lorePage(id,title,aliases,lines.join('\n'),kind);
// People the guides name in more than one scene: each page is built from the guides' two people tables, session by session.
const guideRows=fs.readdirSync(__dirname).filter(f=>/^guide-s\d+[ab]?\.md$/.test(f)).flatMap(f=>{
 const m=f.match(/^guide-s(\d+)([ab]?)\.md$/),n=+m[1],x=m[2],label=n===28?'28 to 30':n+x.toUpperCase(),rows=[];let kind=null;
 for (const line of read(f).split('\n')){
  if (/^\| Who \| What they are \|/.test(line)) kind='who';
  else if (/^\| Who \| Voice and habit \|/.test(line)) kind='voice';
  else if (!line.startsWith('|')) kind=null;
  else if (kind && !/^\|[-| ]+\|$/.test(line)) rows.push({n,x,label,kind,cells:line.split('|').slice(1,-1).map(c=>c.trim())});
 }
 return rows;}).sort((a,b)=>a.n-b.n||a.x.localeCompare(b.x));
const whoName=c=>c.replace(/\*\*/g,'').replace(/\s*\([^)]*\)\s*/g,' ').trim(),whoNote=c=>(c.match(/\(([^)]*)\)/)||[])[1];
// What the characters see on first meeting each of them, and things they say, as on the book's NPC pages. The lines are the
// guides' own where the guides give them.
const guideVoices={
 31:{look:`A woman of about thirty in a shawl stands in the glass, half turned, one hand held out behind her as if somebody small was meant to take it. Around the worn bench at her feet lie a hundred years of candle stubs.`,
  lines:[['Once she is woken',`I've been told. I should like to hear it from you. What year is it?`],['About the other Stilled',`We don't want to be a wonder. We want to be neighbours.`],
   ['Asked what they will do',`We'll walk. Slowly. Tell us which road.`],['About the Sexton',`He asked me to forgive him. I said I'd think about it. I've had practice thinking.`]]},
 32:{look:`An old woman by the fire, with a trapper's hands, a weaver's patience and a basket of candles at her feet. She has been watching you since you arrived, and she doesn't pretend otherwise.`,
  lines:[['Greeting',`You came. I told her you'd come. I tell her everything.`],['About the vigil',`My mother sat with her, and hers. I haven't got a daughter. So it's me, and then it's nobody.`],
   ['About the glass',`Don't use a hammer. Whatever you do. Please.`],['If the players are stuck',`My family has sat with her four hundred years. The voice in the chapel is the first thing that ever answered us.`]]},
 33:{look:`A weather-beaten trapper, out of breath, holds a letter sealed in blue wax well away from himself, as if it might bite. He looks at the fire before he looks at you.`,
  lines:[['About the letter',`Don't ask me to read it. I don't read.`],['Asked who sent him',`An old woman paid me. She talks to the glass.`],
   ['Worried',`There were grey coats on the road behind me. Is that bad?`],['If the players are stuck',`Her hut's by Yara's camp, at the edge of the glass. I'll take you to the first tree. Not one step past it.`]]},
 34:{look:`Among the Stilled at the edge of the clearing stands a man in a sea-coat cut four hundred years out of fashion, with a brass badge on his breast: a ship under three stars. When the glass lets him go, the first thing he does is look at the sky.`,
  lines:[['Greeting',`What year is it? Is it still ten hundred and eighty-two?`],['About the ship',`The Brightwater was moored at a river mouth, west of here, under a sky full of weather. Where did the weather go?`],
   ['About the crew',`There were thirty-one of us. I counted. A bosun always counts.`],['Asked why they came',`We only came ashore for water.`],['About home',`Who won? There was a war on, at home. There's always a war on.`]]},
 35:{look:`On the end of a narrow cot in the clerks' dormitory sits Wren's daughter, knees drawn up, watching the door. She has her mother's face exactly. (At a table that keeps children out of danger, she is Wren's grown sister, with the same face.)`,
  lines:[['Greeting',`Are you from Mam? Don't lie. Everyone here lies, nicely.`],['Asked why she is here',`They keep me so Mam keeps working. She knows it. I know it. We don't say it.`],
   ['On the way out',`Don't let go of my hand till we're outside. Not even on the stairs.`],['Afterwards',`Is Mam all right? Is she in trouble now, because of me?`]]},
 36:{look:`A Hushman sergeant in grey stands by the gate-house door with his arms folded, one hand in a glove of silence-stone. He looks bored, and he misses nothing: who's nervous, who's armed, whose writ is new.`,
  lines:[['Greeting',`Hands where I can see them.`],['At the counter',`Writ.`],['If they refuse the courtesy memory',`Refusing is your right. So is a night in the Belfry.`],
   ['At the north gate, Session 9',`I remember you. You were polite at my gate. Don't make me sorry.`]]},
 37:{look:`Behind the Hushman line on the steps of the Hall of Tithes stands a sergeant with a whistle on a cord and a hand crossbow held low. She is watching the crowd, not you, and counting: her people, their sticks, the ways out.`,
  lines:[['To the crowd',`Clear the steps.`],['To Ilam Bray',`Bray! Back in line!`],
   ['If the party talks to her',`I've got orders, and I've got a square full of frightened people with sticks. Give me a reason to go home.`],['If the crowd sits down',`Nobody dies on these steps today. Not on my record.`]]},
 38:{look:`A woman of sixty, thin as a rake, in a grey robe, comes to meet you with both hands out to take one of yours. Her voice goes down at the end of everything she says, like being tucked in.`,
  lines:[['Greeting',`There. There you are.`],['To anyone tired',`You needn't decide anything. You can just sit.`],
   ['About the Cult',`We don't take. We're given.`],['About the price',`I'll tell you exactly what it costs before you say yes. I wouldn't do that to you.`]]},
 39:{look:`A round little man in a grey robe goes along the rows of beds whispering, always folding something: a blanket, a sock, a hand put back under the covers.`,
  lines:[['Greeting',`Oh, shoes, please. Thank you.`],['About a sleeper',`That's Master Wick. He was a dyer. He's been here since my grandfather.`],
   ['About the sleepers',`They're not unhappy. I'd have known.`],['If they bring socks for bed forty-one',`Forty-one. Aunt Posy. Nobody's ever... Oh, thank you.`]]},
 40:{look:`A young woman, pale and exact, tucks a blanket into an empty bed with perfect corners, then looks up at whichever of you is most tired.`,
  lines:[['Greeting',`I don't dream. It's very restful.`],['To the most tired one',`You look so tired.`],['Asked what she gave',`I don't mind. Really. I don't mind.`]]},
 41:{look:`A big, slow man in a farmer's coat is chopping wood beside the Hall, very carefully, as if he has all the time in the world. Every so often he stops and looks at the door.`,
  lines:[['Greeting',`I was going to take her home. I expect I still am.`],['About his wife',`Bed two hundred and twelve. I sat down for a minute.`],
   ['If they try to take Pip away',`He'll sleep in a bit. He always does in the end.`],['If they offer to bring his wife out',`You'd do that? Then I'm coming. I'll carry her. I'm good at carrying.`]]},
 42:{look:`A boy of six, furious, is throwing stones at the Hall doors one at a time. He is the only person on the hill who looks properly awake.`,
  lines:[['Greeting',`There's a man on the stairs. He's got a hammer. Nobody believes me because they're all asleep even when they're not.`],
   ['Asked how many steps',`A hundred exactly. I did it by listening. And there's a man.`],['Later, proved right',`I said there was a man.`],
   ['A warning',`There's soldiers. They're walking funny. They're not making any noise.`]]},
 43:{look:`A young woman, filthy and hoarse, slides off a ruined horse and stands bent double with her hands on her knees, trying to talk before she has the breath for it.`,
  lines:[['Greeting',`Hallowmere. I've come from... give me a minute. She's packing.`],['The news',`She's leaving the city. Vesk. Herself. Within the day.`],
   ['If they doubt her',`I've watched that gate four years. She's never once come out of it.`]]},
};
for (const [num,title,aliases,names,role,statLine] of [
 [31,'MAREN TALLA','',['Maren Talla'],'A weaver of Glassreach, Stilled on the first night of the freeze, in 2 SS. Wyn Talla\'s family has kept vigil over her for four hundred years. She asks first after her brother, Pell.','Stilled Person while the glass holds her; Commoner once woken'],
 [32,'WYN TALLA','',['Wyn Talla'],'An old trapper at the edge of Glassreach, beside Yara Thenn\'s camp, and the last of her family to keep the vigil over Maren Talla. She paid Edrin Moss to carry the glass letter.'],
 [33,'EDRIN MOSS','',['Edrin Moss'],'A Glassreach trapper who can\'t read. Wyn Talla paid him to carry the glass letter (Session 8). He will guide them to the forest, but never past the first tree.'],
 [34,'CORRAN VELL','Bosun Corran Vell',['Bosun Corran Vell','Corran Vell'],'Bosun of the Brightwater, a ship out of Zazesspur caught in the freeze of 2 SS with thirty-one aboard. He thinks it is 1082 DR.','Stilled Person until calmed; Commoner once thawed'],
 [35,'TESSA CADDOCK, THE HOSTAGE','Tessa, Tessa Caddock',['Tessa Caddock'],'Wren Caddock\'s daughter, held in the clerks\' dormitory of the Hall of Tithes to keep her mother working for the Court (Session 6). If your table has not agreed to children in danger, make her Wren\'s grown sister.'],
 [36,'MABRY COLE','Sergeant Mabry Cole, Sergeant Cole, Sgt Mabry Cole',['Sergeant Mabry Cole','Sgt Mabry Cole','Sergeant Cole'],'The Hushman sergeant on Hallowmere\'s gate (Session 4). He reads writs well. In Session 9 he holds the north gate against the Ringer, and he may remember them.'],
 [37,'ORLA GAUNT','Sergeant Orla Gaunt, Sgt Orla Gaunt',['Sergeant Orla Gaunt','Sgt Orla Gaunt'],'The Hushman sergeant who commands the line at the Hall of Tithes in Session 7. She doesn\'t want a massacre.'],
 [38,'MOTHER LUMEN','',['Mother Lumen'],'Leader of the Hush Cult in the Sleeping Hall at Vael Tor. She is dying slowly, and she feeds the Hush her own dreams first.'],
 [39,'BROTHER LULL','',['Brother Lull'],'A Hush Cultist who looks after the sleepers in the Sleeping Hall. He has never given a dream: he says he is too busy, and he is frightened to.'],
 [40,'SISTER NOD','',['Sister Nod'],'A Hush Cultist of twenty who gave up dreaming last winter, and has forgotten what she used to want.'],
 [41,'WAT FURROW','',['Wat Furrow','Wat and Pip Furrow'],'Came up to Vael Tor in the autumn with his son, Pip, to take his wife home from bed two hundred and twelve of the Sleeping Hall, and stayed.','Hush Cultist'],
 [42,'PIP FURROW','',['Pip Furrow','Pip','Wat and Pip Furrow'],'Wat Furrow\'s son: six, and a bad sleeper. He has given the Hush nothing, keeps waking up, and is the only one who has seen what comes up the stair.','No stats: he is six'],
 [43,'LINNET PASK','',['Linnet Pask','Linnet'],'A scout for anybody who hates the Court. She rides in on a ruined horse in Session 21 with news that Maudrin\'s trunk is being packed, and stays with the party to the summit.'],
]){
 const mine=guideRows.filter(r=>names.includes(whoName(r.cells[0])));
 if (!mine.length) throw new Error('no guide rows for '+title);
 const stats=statLine?[statLine]:[...new Set(mine.filter(r=>r.kind==='who').map(r=>r.cells[2]))],lines=[];
 for (const label of [...new Set(mine.map(r=>r.label))]){
  const who=mine.filter(r=>r.label===label&&r.kind==='who'),voice=mine.filter(r=>r.label===label&&r.kind==='voice'),bits=[];
  for (const r of who){const [,what,,where,starts,influence,secret]=r.cells,note=whoNote(r.cells[0]);
   bits.push((note?'('+note+') ':'')+what+'. **Where:** '+where+'. **Starts:** '+starts+'. **Influence:** '+influence+'. **Secret:** '+secret);}
  for (const r of voice){const [,how,wants,first]=r.cells;bits.push('**Voice:** '+how+'. **Wants:** '+wants+'. **First words:** '+first);}
  lines.push({label,text:bits.join(' ').replace(/(?<!\.)\.\.(?!\.)/g,'.').replace(/([!?])\./g,'$1')});
 }
 const merged=[];
 for (const l of lines){const last=merged[merged.length-1];if(last&&last.text===l.text)last.labels.push(l.label);else merged.push({labels:[l.label],text:l.text});}
 const v=guideVoices[num];
 if (!v) throw new Error('no first look for '+title);
 const body=['- **Role:** '+role,'- **First look (read aloud):** '+said(v.look),'- **Things to say:**',...v.lines.map(([k,t])=>'  - *'+k+':* '+said(t)),
  '- **Stat block:** '+stats.join('; ')+'.','',
  '**Session by session** *(from the guides\' people tables)*',
  ...merged.map(m=>'- **Session'+(m.labels.length>1?'s ':' ')+m.labels.join(', ')+':** '+m.text)].join('\n').replace(/(?<!\.)\.\.(?!\.)/g,'.');
 pages.push({id:'v7-npc-'+title.split(',')[0].toLowerCase().replace(/[^a-z]+/g,'-'),title:num+'. '+title,kind:'NPC',status:'Confirmed',visibility:'DM only',aliases,body});
}
// The names the plans use for people and places that had no page: Imber and the Sexton, the Librarian, the Tor, the Spire and the Cult
// open their pages, and the dead the story turns on, the Mere, the Old Works and the other three endings get pages of their own.
for (const [id,to] of [['sb-bb93b0c927c2b0dc','Imber, Sexton, High Sexton'],['sb-b0f92748217e1595','Librarian'],['sb-2ba366669232d0c6','the Tor'],
 ['sb-72c0b21c8d4cfbdb','Frost Spire, the Spire'],['sb-5ab0b331dfa9af2d','the Cult']]) addAliases(id,to);
for (const [id,title,aliases,lines,kind] of [
 ['v7-npc-edda-thorne','EDDA THORNE (DECEASED)','',[
  "- **Role:** Warden of the Bellwright Tower on the Quiet Night. She died in the Court's custody in 9 SS. Nobody meets her; her words come back.",
  "- **What she heard:** at the last routine tuning, in 1 BS, a \"note beneath the note\" in Ysh's tone. She wrote in her diary that she was afraid of it.",
  "- **The Quiet Night:** Imber Vesk ordered her to tune the bells into one long spring. She refused, wrote a warning in her diary and gave him a copy in person. He tuned them anyway, with the Key.",
  "- **Her diary:** taken by the Court's first Tithe-clerks in 1 SS and sealed in the Tithe-Ledger Room, labelled MIREL, LOST. Lysse Carrow has looked for it for years. The party can take it in Session 5.",
  "- **Edda Thorne's Notes:** the Bellwrights' copy of her tuning pages, made after the ban of 112 SS. Corin Aldeth's family keeps them, and he shows them in Session 18A. They describe the Concord.",
  "- **The Librarian:** began as her tuning pages, bound into a book by Court archivists who could not bear to burn them.",
  "- **Where her words matter:** Session 5 (the diary), Session 12 (say her name and the Sexton goes still), Session 13 (read her diary to him and the Frost Heart comes free at once) and Session 22 (her page tells the truth of the Key)."],'NPC'],
 ['v7-npc-cassia-vesk','CASSIA VESK (DECEASED)','',[
  "- **Role:** Imber Vesk's daughter, dead for centuries. Maudrin Vesk is descended from her, through Ilse Vesk.",
  "- **The Key:** when Imber was disgraced after the Quiet Night, Cassia took the Tuning Key home to the Vesk family reliquary. It stayed there until Maudrin took it in 374 SS.",
  "- **Imber remembers her** asleep in the vestry because the rehearsals ran late (Session 12), and laughing like his mother (Session 13). Detect Thoughts on him finds a lullaby and her name. Asking him about her earns Heroic Inspiration.",
  "- **Maudrin says her name** under her breath when she is hurt (Session 23), and again before she strikes (Session 26). Saying it to her gives Advantage on the Persuasion that might stop her."],'NPC'],
 ['v7-npc-ilse-vesk','ILSE VESK','',[
  "- **Role:** Maudrin Vesk's grandmother, and the first Warden of Silence. She is not met in the campaign.",
  "- **374 SS:** she stood in the doorway when Maudrin, at twenty, took the Tuning Key from the family's reliquary. All she said was not to drop it (Session 24).",
  "- **382 SS:** in the chaos after the Ironhorn raid on Brassfall, she seized control of the Quiet Court and named herself Warden of Silence.",
  "- **384 SS:** her Landing Charter made Pellmoor the only lawful landing for foreign ships, with a Court writ of passage for any foreigner going inland.",
  "- **Session 26:** Maudrin says her name before she strikes. Saying it to her gives Advantage on the Persuasion that might stop her."],'NPC'],
 ['v7-npc-wenna-aldeth',"WENNA ALDETH, CORIN'S GRANDMOTHER (DECEASED)",'Wenna, Wenna Aldeth',[
  "- **Role:** a Bellwright, and Corin Aldeth's grandmother. She died in 352 SS.",
  "- **The Great Nightmare Wave (352 SS):** she rang a small handbell at the foot of Vael Tor. The sound lasted one breath. The Sleepless poured out and killed forty people. The Court blamed the Bellwrights, and she was caught and died in the hunt.",
  "- **Her handbell:** cracked, on the back wall of Corin's workshop, labelled with her name and Vael Tor (Session 18A). He lets people hold it, not ring it. Peal, the oldest Heart-Hound, was cast from the crack.",
  "- **Her work:** Corin's family has tried to finish it for three generations: Wenna, his mother, and now him (Sessions 18A and 26)."],'NPC'],
 ['v7-place-mute-mere','THE MUTE MERE','Mute Mere, the Mere',[
  "**The Mute Mere is the great still lake in the middle of Corvane.** The river Pell runs about forty miles inland from the Seam into it. Act I (Sessions 1 to 3) happens on it and under it.",
  "- **Ossa is silent, so the dead don't rest:** their memories bleed into the water. A character who spends a full night on the shore rolls on the Mere Memory table (11.4) unless they make a DC 12 Wisdom save. Drowned bodies do not decay.",
  "- **Under it:** Old Pellmoor, drowned when the Mere rose in 14 SS. Ossa hangs in its belfry, and the Drowned Choir sings there in Ondra Sallow's voice.",
  "- **On its shores:** Pellmoor Landing on the west, where the Pell flows in, and the ferry-folk and the Mere Memory Shore. Vael Tor is three days east, through the marsh; Hallowmere is three days by ferry and road.",
  "- **Its weather:** none for centuries, until the Wrongweather of 382 SS tore up the Pell and opened the Seam. Davin Sallow drowned in it.",
  "- **Six weeks before Session 1,** the ice cracked early, and Tam Harrow's net came up with Ossa's Heart in an oilskin."],'Location'],
 ['v7-place-old-works','THE OLD WORKS','Old Works',[
  "**The Old Works are Old Garrow's mine at Brassfall:** three mouths in a cliff and a foreman's hut with no roof. The galleries run from the mouths to the Lightning Shafts, where Thrane hangs.",
  "- **372 SS:** Garrow found an unstable deposit of dead lightning, sealed the shafts with his own hands and died in the collapse. His ghost walks the mine with a blue lamp.",
  "- **382 SS:** the Ironhorn, raiding for bronze, broke his seals. The dead lightning called the storms at the rim, and the Wrongweather opened the Seam.",
  "- **Session 16A:** with Garrow's lamp it is a guided tour, with no rolls. Without it there are three galleries: long and safe, flooded and humming, or short and visibly cracked (DC 13 Dexterity save, 3d6 Bludgeoning damage, half on a success).",
  "- Garrow's body lies under the fall in the middle gallery. His daughter, Yenna Garrow, has heard his voice in the mine for a year and never told the Thane."],'Location'],
 ['v7-term-empty-choir','THE EMPTY CHOIR','Empty Choir',[
  "**The Empty Choir is the ending where the Court wins (10.1).** The Court secures the unstruck Key and the shrine, and the group ends its resistance.",
  "- **Only by choice:** it happens only if every player says they have finished fighting (Session 27). If the Court has the Key and they are still fighting, it is the rescue chapter instead.",
  "- **The world:** the Long Dusk goes on and the Court rules. The places the party changed still bear their mark.",
  "- **Sessions 28 to 30:** Scene 2, in whispers, then the Court rules on in Scene 5. The epilogue script is Path 3 in 10.4. The tone is dark and quiet."]],
 ['v7-term-second-dawn','THE SECOND DAWN','Second Dawn',[
  "**The Second Dawn is the ending where the party seals the Key away unstruck (10.1).** Any number of bells may have been rung.",
  "- **The price:** no Toll. One character, one uninterrupted minute at the recess in the rock below Ysh: in a fight, one action a round for ten rounds, and a skipped round starts it again (Session 27).",
  "- **What changes:** what was rung stays rung; what wasn't doesn't come back. With no bells rung it is a stalemate, and nothing is mended. If Mirel is unrung, seven Sleepless come up the stair.",
  "- **It is also the way out** if a Ringer declines the Great Toll (10.3).",
  "- **Sessions 28 to 30:** all five scenes. The epilogue script is Path 4 in 10.4. The tone is mixed and realistic."]],
 ['v7-term-hush-unbound','THE HUSH UNBOUND','Hush Unbound, Remake, Unmake',[
  "**The Hush Unbound is the ending where the Seventh is struck (10.1),** by the party or by Maudrin. It stays open until the Key is sealed.",
  "- **The price:** whoever strikes pays all six kinds of Toll, each Ruinous: the Memory, the Year, the Sense, the Name, the Fear and the Gift.",
  "- **Then Oum wakes** and asks whether the dream is finished. Oum asks direct questions and never lies (Session 27).",
  "- **Remake:** Oum dreams the world again from the parts it loved best. Each player names one thing that won't be lost.",
  "- **Unmake:** the dream ends: one last night with everyone they love, then the light. It happens only if every player wants it; any doubt means Remake. The votes are folded, on paper.",
  "- **Sessions 28 to 30:** a Remake runs Scenes 1 to 4 in a world a little different, then the rebuilt one. An Unmake skips to the last night. The tone is hopeful and strange (Remake), or sad and beautiful (Unmake)."]],
 ["v7-term-far-shore","THE FAR SHORE","Far Shore",["**The Far Shore is the ending where the party leaves Corvane for good (7.19).** Once Thrane is rung the Seam is wide enough for a fleet, and the party can sail out with everyone who will come.","- **Only by choice:** the players choose it (any-sail-out); a clock or a lost fight never does. Ysh must still be unstruck.","- **What stays behind:** the bells, the Court, the Hush failing slowly, and everyone who won't come. Each player names one person who comes and one who stays.","- **The Seam front:** after Thrane the Sword Coast fleets arrive. Write the Pellmoor Charter with Brannagh, Sela and Venn, or the Seam clock runs to 6 and the Landing falls to the fleets and the Court.","- **Session 28:** the epilogue round at sea and on a Sword Coast dock (s28-far-shore). The tone is bittersweet."]],
 ["v7-term-dreamers-sleep","THE DREAMER'S SLEEP","Dreamer's Sleep",["**The Dreamer's Sleep is the ending on the Hush's side (7.19).** The party keeps Oum asleep because Oum is tired and loves its dream.","- **The oath:** \"I will keep the Dreamer's sleep.\" Taken with Mother Lumen in the Sleeping Hall (Session 17B), or at the bell after hearing the Hush on the Stairs (Sessions 25 and 26).","- **What it needs:** the oath, the Cult's feeding stopped, Ysh unstruck, the Key in the party's hands, and someone at the Shrine.","- **What happens:** the Key is laid in the Hush, so nobody can strike Ysh again. The stolen dreams come home and the sleepers wake. What was rung stays rung, and nothing else is mended.","- **Session 28:** the epilogue round, ending with whoever stayed below to sing (s28-dreamers-sleep). The tone is gentle."]],
 ["v7-term-reformed-court","THE REFORMED COURT","Reformed Court, Reform clock",["**The Reformed Court is the path inside the Court (7.19).** A party that took Maudrin's bargain in Session 4 can accept her commission and work as her agents.","- **Agents:** a writ that opens Court doors, errands with a Warden minder, and friends who may not forgive the grey seal.","- **Reform:** each reform won from inside (a Tithe ended, a Ringer pardoned, jars sent home) ticks the Reform clock. At 3 Maudrin asks what they want the Court to be; at 6 her Final Offer becomes the Reformed Court (s24-reformed-court).","- **Turning:** they can use the writ against her once (any-turn-on-the-court). The favor breaks and the reforms stop.","- **Endings:** a reformed Maudrin can be the Seventh's voice for the Concord, or keep the empty chair."]],
 ["v7-term-empty-chair","THE EMPTY CHAIR","empty chair, Claim clock",["**The empty chair is the contest over who rules the Ninefold Shore after Maudrin (7.19).** It runs from Act III to the epilogue.","- **Claimants:** Captain Rook and the Dawn Order, Tristan Vesk, Thane Kessa, the Blanks' bench, one of the party, or a reformed Maudrin.","- **Backers:** each faction backs the party's claimant for one promise (any-claim-backers), and each backer ticks the Claim clock. A broken promise loses the backer.","- **Pressure:** at Claim clock 3 a rival strikes at the claimant (any-claim-rival-moves).","- **Session 28:** with the Claim clock full the shore seats the claimant (s28-chair-seated); otherwise it is argued out on the terraces (s28-chair-contested)."]],
 ["v7-term-treasure","TREASURE","treasure, magic items, Rare items",["**Treasure in The Seventh Bell runs to about two Rare items per character by level 9, and a Very Rare for most by level 11 (7.20, 7.24).** Each item is a 2024 rulebook item in Corvane dress; swap any of them for something your table will use.","- **Act I and II:** a Pearl of Power (S2), the writ (S6), the Ringer's Band, a Ring of Protection (S9).","- **Act III:** the Glass-weave Cloak, a Cloak of Displacement (S11); the Sexton's Bracers or the Choirmaster's Baton (S13); Hieme's Shard (S14).","- **Act IV, Brassfall road:** Garrow's Pick, a lightning Flame Tongue (S16A); Storm-Set (S18A); the Captain's Steel, a +2 weapon or +1 armour (S19A).","- **Act IV, Vael Tor road:** the Sleeper's Torc, an Amulet of Health (S16B); Lumen's Crook, a Staff of Healing (S17B); the Rider's Bell-boots, Boots of Speed (S19B).","- **Either road:** the Bellwright's Charm, from Corin or the Bellwrights (any-bellwright-charm).","- **Side dungeons (7.21):** an Uncommon item in each, on top of the Rare ones: a Cap of Water Breathing (S1), a Bag of Holding (S3), a Hat of Disguise (S5), a +1 Longsword (S6), a Cloak of Protection (S7), Boots of Striding and Springing (S9), a Ring of Warmth (S10) and Boots of the Winterlands (S14). See Side dungeons.","- **Big dungeons (7.23):** Gloves of Thievery (the Tithe-works, S8) and an Amulet of Proof against Detection and Location (the Quiet Quarry, S22), on top of Hieme's Shard in the Frost Spire (S14).","- **Act V (7.24):** the Silent Shield, a Spellguard Shield (S23); the Storm-bell Staff, a Staff of Thunder and Lightning, and the Ringers' Mantle, a Mantle of Spell Resistance (S24); the Stair-stone, an Ioun Stone of Insight (S25).","- **Random finds (7.22):** a roll on the Random magic table from a wreck, a shrine dish, a dead traveller or Gammer Tansy (see Random magic and wonders); a good find or something that shouldn't be here at any trader, on a d6 (see the Shops pages); and a small prize behind each side dungeon's puzzle.","- **Coin and potions** come with each parcel, so they can buy from Trusted factions (Faction standing)."]],
 ["v7-term-faction-standing","FACTION STANDING","standing, reputation",["**Faction standing is how each faction feels about the party (7.20).** Set it in Waypoint's Faction standing panel, from Enemies to Allied; move it one step for a real favour or a betrayal.","- **Enemies, Hostile:** they hunt or inform on the party. **Wary:** no favours. **Neutral:** business. **Friendly:** one favour per act and fair prices. **Trusted:** a person lent, uncommon items at book price, and the perk below. **Allied:** a company at the Strike.","- **Trusted perks:** the Church, a Greater Restoration once per act; the Bellwrights, a Bellwright's Charm or Storm-Set made free; the Drowned Choir, a song that gives Advantage on one Charisma check per session; the Dawn Order, two outriders for a session; the Ironhorn, horses for the whole party.","- **More perks:** the Hush Cult, dream-tea; the Ferry-folk and Pilots, free passage on any water; the Landing, one uncommon item at half price each act; the Court, a Reckoner who looks the other way once per act.","- **Clocks are separate:** a faction clock is what the faction does next; standing is how it feels about the party."]],
 ["v7-term-bell-boons","BELL BOONS","boons, bell charms",["**Every bell rung gives the party a small boon, set against the Toll (7.20).** The Toll is never smaller for it.","- **Vaer:** Hallowmere's safe houses, and a Dawn-charm (Heroic Inspiration and one Exhaustion level gone, once per character).","- **Ossa:** free passage on the Mere, and a Memory-charm (remember one thing exactly, once per character).","- **Calla:** rations on the road, and a Harvest-charm (all Hit Point Dice back on one Long Rest per act).","- **Hieme:** Resistance to Cold, and the Long Cold no longer touches them.","- **Thrane:** storm-stones at cost, and a Storm-charm (2d8 Lightning back at an attacker, once per Long Rest).","- **Mirel:** a Dream-charm (Heroic Inspiration after a Long Rest, once per act), even for those who lost their dreams."]],
 ["v7-term-growth","PERSONAL BEATS, LOST THINGS AND TOLL-MARKS","personal beat, lost thing, Toll-mark",["**Characters grow as well as lose (7.20).** Three things carry it, all built from session zero.","- **Personal beats:** one scene per character per act from their session-zero answers (any-personal-beat; Sessions 8, 11, 20 and 24). Heroic Inspiration when it lands.","- **Lost things:** what a character lost before the campaign can be won back, through a Tithe jar, the Hush's dreams or a person found alive (any-win-back-the-lost-thing). It brings an Origin feat or a named ally.","- **Toll-marks:** every Toll leaves a mark and one small boon that grows from what was taken (any-toll-mark). Tolls are permanent; a mark never gives anything back.","- **Standing and boons:** see Faction standing and Bell boons."]],
 ["v7-term-side-dungeons","SIDE DUNGEONS","side dungeon, side dungeons, mini dungeon, dungeon crawl",["**Side dungeons are short, optional crawls scattered through the campaign (7.21):** a door that goes down, a few rooms, a trap or two, something hidden and a fight that can usually be talked out of. Each has a play in its session (search for *Side dungeon*), a page here with every room keyed and what to say, a treasure play, and its fight in the Combat tab.","","**They're possibilities, not plot points.** Drop a hook when the moment's right and let the players choose. If they walk past, nothing is lost. **Three big dungeons are different (7.23):** the Tithe-works (Session 8), the Frost Spire (Session 14) and the Quiet Quarry (Session 22). Each is the obvious play in its session, with its door in plain sight, an evening's crawl and its own page here.","","| Session | Where | Level | Fight | Uncommon item |","|---|---|---|---|---|","| 1 | The Undertow's cellar, under the Quays | 3 | Brine Annet's thieves | Cap of Water Breathing |","| 3 | The Vennmark bond-house | 3 | A Mimic and Venn's night watch | Bag of Holding |","| 5 | The Inkwell, under a bindery | 3 | Quen Ashdown and a Hushman | Hat of Disguise |","| 6 | The Dawn undercroft | 3 | Ser Bran Hollis | +1 Longsword |","| 7 | The Lamplighters' cistern | 4 | Corvin Hale's gang | Cloak of Protection |","| 8 | The Tithe-works, under the palace | 4 | A patrol, memory-eels, the First Tallyman | Gloves of Thievery |","| 9 | The kilns at Kell's Crossing | 4 | Morra Senn's Grey Coats | Boots of Striding and Springing |","| 10 | The reeve's icehouse | 5 | Stilled wreckers and frost-motes | Ring of Warmth |","| 14 | The Frost Spire's inner stair | 6 | Wolves, the choir, the Bell-Warden | Boots of the Winterlands |","| 22 | The Quiet Quarry, on the Tor road | 9 | The quarry guard, Xorns, Old Patient | Amulet of Proof against Detection and Location |","","**Running them.**","- **Traps are fair.** Each has a clue a careful character can see, with its DC. A player who says they're checking for traps gets the clue on a success. When one goes off, describe it first, then roll the damage.","- **Something is always hidden,** with its DC. If they miss it, it isn't gone: someone mentions it later.","- **Every fight has a way out.** These are people who would rather deal or run than die, and each fight says when they do.","- **About 45 minutes each.** If the session is full, run it at the start of the next one, or skip it. Nothing in the main story depends on one.","- **The Uncommon items** come on top of the two Rare items each by level 9 (see Treasure)."],"Lore"],
 ["v7-place-undertow-cellar","THE UNDERTOW'S CELLAR","Undertow, Undertow's cellar, Coyle's Chandlery, Brine Annet",["**A side dungeon for Session 1 (7.21): a thieves' den in the attic of a drowned house, under the Quays.** Level 3, six rooms, three traps, one fight, about 45 minutes. The play is *Side dungeon: the Undertow's cellar*.","","**What's going on.** Pellmoor pays its way in gold now, so bottled memories are scarce and worth more than ever. Brine Annet's crew of six, the Undertow, steal jars from the Vennmark bond-house and the Coster ships and sell them on. Their best customer is Tobias Quill, who buys stolen jars to make up his quota. Annet writes everything down.","","**Getting there,** in the port (Scene 3) or after dark:","- A wiry dockhand lifts a character's purse, ducks into Coyle's Chandlery on the Quays, and doesn't come out.","- Sela Maunt: \"Somebody's lifting Venn's jars. And somebody's buying them who shouldn't be.\"","- Ila saw Quill go into the chandlery after dark, alone, and come out with a sack that clinked.","","**Running it.** The den is under the Quays' timbers, in the top floors of a house that drowned with Old Pellmoor in 14 SS. Below the ladder it's dark: lanterns or Darkvision. The crew are thieves, not killers, and run before they die. Noise in rooms 2 to 4 warns Annet, and then nobody in room 5 is Surprised.","","### 1. Coyle's Chandlery","> **SAY:** \"The chandlery smells of tar and wet hemp. Coils of rope hang from the rafters like sleeping snakes. Behind the counter an old man mends a net, very carefully not looking at you.\"","- **Pim Coyle** (Commoner, deaf in his left ear) is paid a silver a night to watch the trapdoor. If strangers go near the anchor chain he calls \"Tide's in!\", the crew's warning.","- **Talking him round:** 5 gp, or Influence DC 12 (Advantage for anyone who speaks into his right ear). He gives them the password, \"Tide's out.\" Said at the top of the ladder, it means the crew below don't reach for their knives.","- **The trapdoor** is under a coil of anchor chain. Wisdom (Perception) DC 13 to see the scrape marks. Moving the chain quietly is a DC 12 Strength (Athletics) check; on a failure it rattles and the crew are warned.","","### 2. The long ladder","> **SAY:** \"The ladder goes down through the Quays' pilings into another town. Below you the slate roof of a drowned house rises out of black water, and someone has cut a door in it.\"","- **Trap: the sawn rung.** The seventh rung is cut almost through; the crew step over it. Passive Perception 12 notices fresh sawdust. Anyone who puts their weight on it makes a DC 12 Dexterity saving throw. On a failure they fall 10 feet into room 3, take 1d6 Bludgeoning damage and land Prone, and the crew are warned.","","### 3. The attic (the tally room)","> **SAY:** \"Lamplight, and voices. The attic is dry, tarred and hung with sailcloth. Two people sit at a table counting stoppered bottles into rows, chalking each one on a board. One bottle glows faintly, like a coal remembering it was a fire.\"","- **Gully and Fen** (Bandits), playing knucklebones. Given the password, they wave the party on to \"Annet's room\". Taken by surprise, they give up at the first hit and tell everything they know.","- **Trap: the net-weights.** A tripwire across the far doorway at ankle height. Perception DC 13 to spot (Advantage with a lantern held low); cut it safely with a knife or thieves' tools and a DC 12 Dexterity (Sleight of Hand) check. If it goes, a net of lead fishing weights drops from the rafters: DC 12 Dexterity saving throw, or 2d6 Bludgeoning damage and Restrained (escape DC 12, or cut the net: AC 10, 5 HP). The clatter warns Annet.","- **Hidden: the tally book,** in the table drawer (no roll). Three lines read *T.Q., six jars, 12 gp*. Quill has been buying stolen memories to make up his quota.","- **Puzzle (7.22): Annet's cipher.** The last page of the tally book is one line of nonsense: *UBYZLYF JOPTULF AOPYK IYPJR BW*. In the corner of the counting board, chalked and circled, is a single *7*. Every letter has been moved seven places on; count each one back seven (U is N, B is U) and it reads *NURSERY CHIMNEY THIRD BRICK UP*. Intelligence (Investigation) DC 13 to see how it works, or DC 10 if anyone noticed the seventh rung. See room 4.","","### 4. The jar room (the old nursery)","> **SAY:** \"Shelves on every wall, and on the shelves, bottles. Thirty of them, perhaps. Up close you can hear them: not sound, but the memory of sound. A dog barking on a summer afternoon. Somebody laughing at a wedding.\"","- **Thirty bottled memories,** labelled in Amnian chalk: *a harvest dance, 371*; *first boat, very fine*. Holding a glowing one shows a few seconds of a stranger's life. Mother Sallow can tell whose most of them were.","- **Trap: the tin cups.** One floorboard in front of the shelves (Perception DC 14: it's newer than the rest) pulls a string of tin cups in room 5. Annet is warned and comes out with her crossbow.","- **Hidden:** a loose board under the cot (Intelligence (Investigation) DC 14). In a waxed bag: 40 gp and a grey Mere pearl worth 50 gp.","- **Hidden (7.22): Annet's stash.** The jar room was a nursery once, and its little fireplace is still there under the shelves. Third brick up inside the chimney, one slides out: no roll with the cipher, Investigation DC 18 without it. In oilcloth behind it: 30 gp, a Potion of Water Breathing, and a map of the drowned streets.","","### 5. Brine Annet's room","> **SAY:** \"The last room was a bedroom once. Now it's an office: a desk made from a ship's hatch, a sea-chest with brass corners, and a woman with a crossbow across her knees who looks as if she's been expecting you all her life.\"","- **Brine Annet** (Bandit Captain) and **four Undertow** (Bandits), fewer if they've met some already. The fight is *The Undertow's cellar* in the Combat tab.","- **She'd rather deal.** At Bloodied, or if they show they've read the tally book, she offers the book, the jars and the name of Quill's go-between for a way out. Refused, she drops through the floor hatch into room 6.","- **Her sea-chest** is locked (thieves' tools DC 13, or the key round her neck). **Trap: a poison needle** in the lock: Investigation DC 13 to spot, a DC 12 Sleight of Hand check to jam it. Pricked: DC 11 Constitution saving throw, or 1d10 Poison damage and Poisoned for 1 hour.","","### 6. The undertow (the way out)","> **SAY:** \"Under the hatch the house goes on down, full of black water. A rope runs down the stairwell and away under the pilings, toward a grey smudge of daylight.\"","- **The swim:** 40 feet underwater along the rope to the old dock on the Old Shore. A DC 10 Strength (Athletics) check, or take 1d4 Bludgeoning damage and come up halfway, gasping. With the diving hood, no check.","- **Two Mere eels** (use the Constrictor Snake) live in the stairwell. The crew keep them off with salt: a sack of it hangs by the hatch. A handful scattered keeps them away for a minute.","","**Rewards.**","- In the sea-chest: 35 gp, two Potions of Healing and **Annet's Diving Hood**, a Cap of Water Breathing (uncommon). Under the cot: 40 gp and the pearl (50 gp).","- **The jars.** Taken home to the Old Shore through Mother Sallow, they win the ferry-folk over: each character who helped gains Heroic Inspiration, and the ferry-folk hide the party from the Hushmen without being asked. Sold back to Venn, they fetch 5 gp each and his good opinion.","- **The tally book** is leverage. Intimidation against Quill has Advantage for the rest of Act I, and if they ask, he leaves their names out of his report to Hallowmere.","- **Annet's stash (7.22),** behind the cipher: 30 gp, a Potion of Water Breathing, and her **map of the drowned streets**. With it they can reach any pier in Pellmoor unseen, and it marks the chapel at low tide (The coast road, entry 11). Whoever worked it out gains Heroic Inspiration.","","**Afterwards.** If Annet got away, she turns up in Session 3 with a grudge, or a deal. Pim Coyle keeps the chandlery and keeps quiet."],"Location"],
 ["v7-place-vennmark-bond-house","THE VENNMARK BOND-HOUSE","bond-house, Vennmark bond-house, Venn's cellar",["**A side dungeon for Session 3 (7.21): Master Venn's warehouse on the Quays, and the cellar where bottled memories wait for the Gilded Heron.** Level 3, five rooms, three traps, a guardian and one fight, about 45 minutes. The play is *Side dungeon: the Vennmark bond-house*.","","**What's going on.** Orsolo Venn exports bottled memories to rich buyers across the sea and pays Quill to look away from some cargoes. Everything he's bought this season is in his cellar, waiting to be loaded. If the party sold him the Heart, it's here too, in his strongroom.","","**Getting there:**","- Venn's note offers to buy \"a humming relic\". He shows them round the counting-house himself, and his clerk lets slip that the good stock is downstairs.","- They sold him the Heart and want it back.","- Annet's tally book (Session 1) names the bond-house as where her jars came from.","- Mother Sallow has heard there's a bottle in Venn's cellar with her Davin's name on it.","","**Running it.** At night there's one watchman, his mastiff and two Toughs hired off the Quays. By day there are clerks, and Venn in plum velvet. Venn never calls the Hushmen: he'd have to explain his cargo.","","### 1. The counting-house","> **SAY:** \"Every wall of Venn's counting-house is covered with clocks. Brass, walnut, enamel, a hundred faces, every hand moving, and not one of them makes a sound.\"","- **Ways in:** the loading door on the Quays (thieves' tools DC 13, or a loud DC 15 Strength check); the coal chute at the back (Small or Medium; a DC 12 Dexterity (Acrobatics) check or stick halfway; it comes out in room 3, black with soot); or the front door by appointment, when Venn shows them rooms 1 and 3 and makes his offer.","- **Watchman Dunstan** (Guard) dozes in the clerks' room with **Pudding** (Mastiff). Pudding can be bought with anything from the pantry.","- **Puzzle (7.22): the stopped clock.** One clock in the room isn't moving: a walnut case clock behind the counter, stopped at a quarter past nine. Its brass plate says *The hour the Heron first came in*. Venn's pocket watch, if anyone sees it, has stopped at the same time. History or Insight DC 12, or asking any clerk: the *Gilded Heron* was Venn's first ship, and he keeps that hour for luck. See room 5.","","### 2. The speaking stair","> **SAY:** \"Narrow stairs go down beside a brass pipe with a trumpet mouth at the top.\"","- **Trap: the speaking-tube.** The handrail is a speaking-tube to the clerks' room. Perception DC 12 to notice it. Anything said on the stair, even a whisper, is heard upstairs: a DC 13 group Stealth check to go down in silence, or stuff the mouth with a glove (no roll, once they've noticed).","- **Trap: the cask.** A tripwire at the foot of the stair lets a cask of Amnian wine roll from its cradle. Perception DC 13 to spot. DC 13 Dexterity saving throw, or 2d6 Bludgeoning damage and knocked Prone. Broken, it floods the floor with wine, and the smell reaches Dunstan.","","### 3. The bottle racks","> **SAY:** \"Racks run the length of the cellar, the bottles packed in straw. Each has a paper label in a neat Amnian hand. *A summer, 302 SS, very fine. First kiss, harbour, moderate. A mother's voice, singing.*\"","- About two hundred bottled memories, all listed in Venn's shipping book. Most were sold by people who needed the money. Not all.","- **Hidden:** on the lowest rack, wrapped in a shawl: *D. Sallow, the old dock, not for sale.* Investigation DC 12, or no roll if Mother Sallow asked them to look. Venn kept it for himself.","","### 4. The cabinet of curiosities","> **SAY:** \"Venn's private room. A narwhal's horn, a Calishite astrolabe, a stuffed sea-cat with glass eyes, and a sea-chest with brass corners that is, very slightly, breathing.\"","- **Guardian: the chest is a Mimic.** Venn bought it in Calimport as a watchdog, and the clerk feeds it a ham-hock every evening. Intelligence (Investigation) DC 15 to see it's alive (Advantage if anyone mentions the breathing). A ham from the pantry keeps it busy for a minute. Anything that touches it sticks.","","### 5. The strongroom","> **SAY:** \"An iron door with a lock shaped like a clock face. Every number is a keyhole.\"","- **The lock** opens with Venn's key (on his watch-chain) or thieves' tools DC 15. **Trap: a poison needle** behind the twelve: Investigation DC 15 to spot, a DC 13 Dexterity check with thieves' tools to jam it. Pricked: DC 13 Constitution saving throw, or 2d10 Poison damage and Poisoned for 1 hour.","- **Puzzle (7.22): the hour.** Turn a key or a knife-point in the IX keyhole, then the III: a quarter past nine. The lock opens with no roll, and the needle never moves. Any other keyhole tried first springs the needle. Behind the IX a little drawer slides out that thieves' tools would never find, with Venn's lucky charm in it: a **Clockwork Amulet**.","- **Inside:** the Heart if they sold it, in a case lined with plum velvet; 150 gp in Amnian coin; a Potion of Climbing and a Potion of Healing; the shipping book; and the plum bag.","","**The fight.** If they're heard, Dunstan, Pudding and the two Toughs come down, and the Mimic joins in wherever it is: *The Vennmark bond-house* in the Combat tab. The Toughs are paid for the night, not for dying: they leave when one drops.","","**Rewards.**","- **Venn's Plum Bag**, a Bag of Holding (uncommon) in plum velvet, embroidered with a silent clock. With it: 150 gp, a Potion of Climbing and a Potion of Healing.","- **The Heart,** if they sold it. Venn has paid them 600 gp for it and will want one or the other back.","- **Davin Sallow's bottle.** Mother Sallow watches it once, alone. Afterwards she trusts them completely, and each character who brought it home gains Heroic Inspiration.","- **The shipping book** proves Quill takes Venn's money. With Annet's tally book as well, they could ruin him.","- **The hour (7.22).** Opened at a quarter past nine, the strongroom gives up Venn's Clockwork Amulet (common) from the drawer behind the IX. Whoever worked it out gains Heroic Inspiration.","","**Afterwards.** In the morning Venn sends a polite note: *A pity. I would have paid.* If they took the Heart back after he paid for it, his Toughs watch the Old Shore until the party leaves."],"Location"],
 ["v7-place-inkwell","THE INKWELL","Inkwell, Ashdown's Bindery, Quen Ashdown, Vellum Lane",["**A side dungeon for Session 5, or any night in Hallowmere (7.21): a forger's cellar under a bindery on Vellum Lane.** Level 3, five rooms, two traps, one fight, about 45 minutes. The play is *Side dungeon: the Inkwell*.","","**What's going on.** Quen Ashdown binds prayer-books by day. At night, under the shop, his people forge Tithe receipts and gate writs for families who need to get out of Hallowmere, and charge them everything they have. Then he sells their names to the Hushmen, so the Court knows who tried. He keeps the names in a blue ledger.","","**Getting there:**","- Lysse Carrow, or any friend in the city: \"If you need papers, there's a binder on Vellum Lane. Only, nobody he helps ever seems to get out.\"","- A family, Bet or a Blank asks them to find out why their cousins were arrested at the gate with perfect papers.","- They want a way out of Hallowmere for Session 9.","","**Running it.** Ashdown is a Court informant, not a fighter. A Hushman sits in his study most nights, drinking his wine. Nobody down here wants a death that brings the Court in.","","### 1. Ashdown's Bindery","> **SAY:** \"A narrow shop that smells of glue and new leather. Prayer-books stand in rows, every one bound in white. An apprentice with ink to his elbows is pretending to sweep.\"","- **Tobin** (Commoner, nineteen) hates his master. 10 gp, or Influence DC 13 (Advantage if they mention the arrests), and he shows them the way down and warns them about the floor.","- **The secret door** is a bookcase. Pull *Sermons of the Quiet, Volume IX* (there is no Volume IX). Investigation DC 13 to find it.","- **Over the door (7.22),** painted in gold on a black board: *Ashdown's. We keep it QUIET.* The last word is in capitals, and newer than the rest. See room 4.","","### 2. The press-room","> **SAY:** \"A printing press the size of a cart, and lines of drying paper strung across the room like washing. Every sheet is a gate writ. The floor shines.\"","- **Trap: the black floor.** The boards round the press are oiled and inked so that strangers slip. The forgers walk a dry path (Perception DC 12 to see their footprints). Off the path the floor is Difficult Terrain, and anyone who Dashes across makes a DC 12 Dexterity (Acrobatics) check or falls Prone.","- **The writs** are blank. They need Ashdown's seal (room 4) to fool a gate.","","### 3. The seal passage","> **SAY:** \"A short brick passage, and an iron-bound door with two handles: one bright, one dark with use.\"","- **Trap: the grille.** The bright handle drops an iron grille across the passage behind them, and a counterweight thumps down in room 4. Investigation DC 14 notices that nobody with ink on their hands has ever touched the bright one. The grille: AC 19, 30 HP, a DC 17 Strength (Athletics) check to lift. The forgers arrive in 2 rounds.","","### 4. Ashdown's study","> **SAY:** \"A warm study lined with ledgers. On the desk: a seal-press, a lamp, a blue-bound book, and an inkwell in the shape of a closed eye.\"","- **Quen Ashdown** (Spy), **three forgers** (Toughs) and **Hushman Garrick**, off duty. The fight is *The Inkwell* in the Combat tab. Ashdown runs for room 5 the moment it turns.","- **The blue ledger:** forty names, and the date each one was sold.","- **Hidden:** the closed-eye inkwell has a false bottom (Investigation DC 15) with a small iron key in it. The key opens a floor safe under the rug.","- **Puzzle (7.22): the dial.** Beside the floor safe's keyhole is a ring of five letter-dials, and the key won't turn until they spell the word. On the blotter, in mirror-writing (Investigation DC 12, or hold it up to the lamp's brass): *the word is what we keep*. It's on the sign upstairs: QUIET. A wrong word breaks a vial of ink inside the safe and ruins the scroll; the hat and the gold survive. Thieves' tools DC 18 can work the dial, but a failure breaks the vial too.","","### 5. The back way","> **SAY:** \"A culvert, waist-high and stinking, runs under the lane toward the canal.\"","- DC 10 Constitution saving throw or Poisoned for 10 minutes from the stench. It comes out under a footbridge, unseen.","","**Rewards.**","- In the floor safe: **Ashdown's Grey Hat**, a Hat of Disguise (uncommon, requires attunement), 60 gp and a Spell Scroll of Disguise Self.","- **Sealed writs.** With Ashdown's seal they can finish three writs (Tobin does it, or a DC 12 check with a forgery kit). In Session 9 a sealed writ is one answer to getting out: it passes one checkpoint without a roll, or gives Advantage on a check to bluff the Gate Sweep.","- **The blue ledger.** Burned, it saves forty families from arrest, and Bet, Aurelie or Rook hears who did it. Given to Rook, it's proof the Court pays informants.","- **The word (7.22).** Opened with QUIET, the safe gives up everything, the Spell Scroll of Disguise Self included. Whoever worked it out gains Heroic Inspiration.","","**Afterwards.** If Ashdown got away, he tells the Court exactly what they look like. If Tobin helped, he keeps the shop and makes papers honestly, or at least for free."],"Location"],
 ["v7-place-dawn-undercroft","THE DAWN UNDERCROFT","Dawn undercroft, undercroft, Ser Bran Hollis",["**A side dungeon for Session 6 (7.21): the crypt under the Dawn Order's chapterhouse, where Ser Haldric hides the Court's silver.** Level 3, five rooms, two traps, a knight's tomb and one fight, about 45 minutes. Best the night before the oath-duel. The play is *Side dungeon: the Dawn undercroft*.","","**What's going on.** Haldric sells the Order's protection to the Court, and the Court pays in silver. He can't bank it, so he hides it with the dead, in the undercroft where the Order buries its knights. Ser Bran Hollis, the one knight he trusts, guards it at night, and hates it.","","**Getting there:**","- Captain Rook asks for proof (Scene 1): \"If he's paid, the money's somewhere. Not in his rooms. I've looked.\"","- After her confession, Wren says where she took Haldric's messages: the chapel, after dark.","- A squire whispers that Ser Bran goes down into the crypt every night and comes up with nothing.","","**Running it.** The Dawn Order are knights, not thieves. Anyone caught is arrested, not killed, and Rook can get them out by morning if she's their friend. Ser Bran yields when Bloodied: he'd rather lose than die for Haldric.","","### 1. The chapel of the Dawn","> **SAY:** \"The chapel faces east. The altar is a single block of white stone carved with a rising sun, and a squire is asleep in the front pew with his sword across his knees.\"","- **Squire Lenn** (Guard) sleeps through anything quieter than a fight (DC 10 group Stealth check). Awake, he's frightened and honest: Influence DC 12 and he goes for Rook instead of the watch.","- **The way down:** the sun on the altar turns. Turn it to face the east window and the altar slides aside on a stair. Religion or History DC 12 to guess; Rook knows.","","### 2. The hall of shields","> **SAY:** \"A long vaulted hall hung with shields, a hundred of them, each painted with a knight's arms and a date. The floor is laid with great square stones, and each stone is carved with a single word.\"","- **Trap: the oath-stones.** The words are the Order's four virtues, Dawn, Truth, Mercy and Shield, mixed with their opposites: Night, Lies, Wrath and Fear. Step only on the virtues. Step on any other and spears thrust from the walls: DC 13 Dexterity saving throw or 2d8 Piercing damage. Perception DC 14 to see the holes in the walls. History or Religion DC 12, or a Dawn Order friend, to know the virtues. Ser Bran's boot-prints show the safe stones (Survival DC 13).","","### 3. The tombs","> **SAY:** \"Stone knights lie on their tombs with their hands folded on stone swords. One tomb has a real sword: steel, laid on the effigy's chest, bright as if someone oiled it yesterday.\"","- **Ser Aldous Morrow's tomb.** The Order buried him with his sword, Morrow's Edge, on a stone rest that snaps shut if the sword is lifted carelessly. **Trap: the sword-rest.** Investigation DC 13 to see the counterweight; a DC 12 Dexterity (Sleight of Hand) check lifts it cleanly. On a failure the rest snaps on the lifter's hands: DC 12 Dexterity saving throw or 1d10 Bludgeoning damage, and the crash echoes down the hall.","- Rook, if they ask her later: \"Morrow would rather it fought Haldric than rusted. Keep it.\"","- In a dead knight's satchel at the foot of the next tomb: two Potions of Healing (no roll if anyone looks).","- **Puzzle (7.22): Morrow's riddle.** At the head of Morrow's tomb a niche is shut by a carved stone face, and under it: *I am given and cannot be taken. I am kept and weigh nothing. I am broken and make no sound.* Say the answer aloud (an oath, a promise or your word all work) and the face slides down. Hints: the hall of shields is full of oaths, and Rook knows the old knights' riddles and that Morrow was proud of this one. Breaking the face is a DC 15 Strength check, and loud enough to bring Ser Bran and the guards from room 4.","","### 4. The reliquary","> **SAY:** \"A small round chamber where the Order once kept its relics. The niches are empty. In the middle of the floor stand three iron-bound chests, and in front of them a tall knight in full plate, with his visor up and a very tired face.\"","- **Ser Bran Hollis** (Knight) and **two Dawn Order guards** (Guards). He talks first: \"I know what's in them. I don't know what to do about it.\" Influence DC 15 (Advantage if they have the Ledger or Ansel's copy) and he stands aside, and will speak for Rook at the duel. Otherwise he fights until Bloodied, then yields. The fight is *The Dawn undercroft* in the Combat tab.","- **The chests:** 300 gp in new Court silver, every coin stamped with the Quiet Court's seal; a letter from the Chancellor's office, *For the Order's continued understanding*; and a list of the nights the Order looked away.","","### 5. The bone stair","> **SAY:** \"Behind the reliquary a narrow stair climbs between walls of skulls toward a grating and the smell of the river.\"","- The way out to the river steps. The grating is locked: thieves' tools DC 12, or a DC 14 Strength check.","","**Rewards.**","- **Morrow's Edge,** a +1 Longsword (uncommon). Swap it for whatever +1 weapon your party will use.","- **The silver,** 300 gp. Spending Court silver in Hallowmere gets noticed.","- **Evidence for the oath-duel (Scene 2).** The letter and the silver are evidence, and Ser Bran, if he stood aside, is a witness. Add them to whatever else the party brings.","- **Morrow's niche (7.22):** a white-gold sun symbol worth 50 gp, a Spell Scroll of Lesser Restoration, and a letter in Morrow's hand to whoever reads it: *Remind them.* Shown at the oath-duel, the letter gives Advantage on one check there. Whoever worked it out gains Heroic Inspiration.","","**Afterwards.** Haldric knows by morning. If they left the silver, he moves it. If Ser Bran speaks for Rook, Haldric has lost his one friend in the Order."],"Location"],
 ["v7-place-lamplighters-cistern","THE LAMPLIGHTERS' CISTERN","Lamplighters, cistern, Corvin Hale, Lamp Street",["**A side dungeon for Session 7 (7.21): an old bathhouse under Lamp Street, where a gang sells Blanks to the Tithe-house.** Level 4, six rooms, two traps and a steam hazard, one fight, about an hour. Cleared, it's a roof for the night. The play is *Side dungeon: the Lamplighters' cistern*.","","**What's going on.** The Lamplighters find Blanks wandering the streets and promise to help them learn who they were. They feed them, give them a blanket in the old bathhouse, and every few nights sell some of them to the Tithe-house as labour, 5 gp a head. Corvin Hale runs it. He thinks of himself as kind.","","**Getting there:**","- In the crowd at the Hall of Tithes, a man with a lantern on a pole is gathering Blanks: \"Come with me. Warm food. We'll find your names.\"","- Bet: people she's helped have vanished after a night \"with the lamp-men\".","- They need somewhere to hide the Bray family (Scene 3), and a Blank tells them about \"the warm place under Lamp Street\".","","**Running it.** Hale's people won't fight in front of the Blanks if they can help it: the Blanks believe in them. Turn the Blanks, and the Lamplighters lose their nerve.","","### 1. The bathhouse door","> **SAY:** \"A Ninefold bathhouse, boarded up for fifty years. A lantern burns on the roof, hooded on three sides, and someone behind it is watching the street.\"","- **Tamsin** (Scout) is on the roof. If she sees strangers she shutters the lantern twice and Hale is warned. Stealth against her passive Perception 15, or walk in with the Blanks: anyone who looks lost is waved inside.","- The door is barred inside. The coal hatch in the alley isn't (Small or Medium, no check).","","### 2. The changing hall","> **SAY:** \"Stone benches line a long hall, and on them people sleep under grey blankets. Each has set something beside their pillow: a child's shoe, a wooden spoon, a ring on a string. Whatever was in their pockets when they forgot.\"","- **Twelve Blanks,** grateful to the Lamplighters. Wake them roughly and they scream, and Hale is warned. Influence DC 13 makes one listen; showing them the ledger from room 4 makes it automatic, and once one believes, the rest follow.","- **The mosaic (7.22).** The end wall is a tiled picture of the baths as they were: bathers walking from a blue pool, through a yellow room, into a red one full of steam, all of them smiling. See room 4.","","### 3. The cold plunge","> **SAY:** \"A walkway of blue tiles crosses a deep, empty plunge pool. Halfway over, the tiles change: newer, a slightly different blue.\"","- **Trap: the drop.** The new section is a hinged false floor over the pool. Perception DC 14 to notice (no roll if someone says they're looking at the tiles). Step on it: DC 13 Dexterity saving throw or fall 15 feet onto broken tile, taking 1d6 Bludgeoning and 1d6 Slashing damage, and the crash warns Hale. The Lamplighters walk round the pool's edge.","","### 4. The furnace room","> **SAY:** \"The furnace that heated the baths is lit again, and roaring. Beside it is a table with a ledger, a cash box, and a string of brass tags, each stamped with a number.\"","- **The ledger:** the names the Lamplighters gave the Blanks, *Tall Woman*, *Spoon*, *Boy with a Ring*, and beside each, *Tithe-house, 5 gp*. The cash box holds 25 gp.","- **Hidden: the ash pit.** The ash under the grate has been raked smooth round a shape (Investigation DC 14). A strongbox, warm to the touch: 90 gp, a Potion of Greater Healing, and a good wool cloak with a silver clasp, taken from a Blank who used to be somebody.","- **Puzzle (7.22): the sluice wheels.** An iron cupboard is bolted to the wall beside the furnace, and its bolts are worked by three valve-wheels painted blue, yellow and red, each on a dial marked *cold*, *warm* and *hot*. Set them as the bathers in the mosaic walk (blue cold, yellow warm, red hot) and the bolts draw back. A wrong setting vents scalding water: DC 12 Dexterity saving throw, 2d6 Fire damage, half on a success. Brute force is a DC 18 Strength check or thieves' tools DC 16, and the bang warns Hale.","","### 5. The steam vault","> **SAY:** \"A domed room full of steam, lit red by the furnace pipes. A broad man in a lamplighter's coat rises from a bath-chair, smiling, his hands open. 'Friends. You look cold. Have you come for a name too?'\"","- **Corvin Hale** (Tough Boss), **three Lamplighters** (Bandits), and Tamsin if she came down. The fight is *The Lamplighters' cistern* in the Combat tab.","- **Hazard: the steam pipes.** On initiative count 20 each round, a jet of scalding steam bursts from the pipes in a 15-foot line you choose: DC 12 Dexterity saving throw, 2d6 Fire damage, half on a success. The room is Lightly Obscured. Shutting the master valve by the door takes an action and a DC 12 Strength (Athletics) check.","- Hale talks before he fights, and gives up if the Blanks turn on him. He can't bear to be hated.","","### 6. The drain stair","> **SAY:** \"A narrow stair climbs to a grating. Through it you can see the underside of the Hall of Tithes' steps, and Hushman boots going past.\"","- This is why it's a good hiding place: the Hushmen walk over it every day and never look down.","","**Rewards.**","- **The Lamplighter's Cloak,** a Cloak of Protection (uncommon, requires attunement), with 90 gp and a Potion of Greater Healing in the ash pit, and 25 gp in the cash box.","- **A roof for the night.** Cleared, the cistern is as safe as Bet's cellar for the Bray family, and the Blanks keep watch.","- **Twelve Blanks freed.** Each character who helped turn them gains Heroic Inspiration.","- **The ledger** proves the Tithe-house buys people.","- **The bath-keeper's cupboard (7.22):** a Perfume of Bewitching, a Candle of the Deep and two Potions of Healing, left by whoever kept the baths. Whoever worked it out gains Heroic Inspiration.","","**Afterwards.** If Hale got away, he sells the party's description to the Hushmen. Taken alive, Rook or Bet can hand him to someone who'll keep him."],"Location"],
 ["v7-place-kells-kilns","THE KILNS AT KELL'S CROSSING","kilns, Grey Coats, Morra Senn",["**A side dungeon for Session 9 (7.21), or the start of Session 10 if tonight is full: a ring of old charcoal kilns on the ash plain, where Court bailiffs rob the families running north.** Level 4 (or 5, if they've levelled), six areas, two traps and a hazard, one fight, about 45 minutes. The play is *Side dungeon: the kilns at Kell's Crossing*.","","**What's going on.** Kell's Crossing is the first place families stop when they run from Hallowmere. Morra Senn and her Grey Coats wear the Tithe-house badge and \"collect\" from anyone on the road: food, tools, coats, children's boots. They keep it all in the old kilns.","","**Getting there:**","- Nessa Harrow, or any farmer at the Crossing: \"The Grey Coats took my seed-corn. They live in the kilns. Nobody goes out there.\"","- A family by the road with no coats, no cart and a story.","- Something of the party's goes missing in the night.","","**Running it.** The ash muffles footsteps (Advantage on Stealth checks while walking), but running raises a cloud: the area is Lightly Obscured, and the cloud can be seen from the kilns.","","### 1. The kiln-yard","> **SAY:** \"Six brick kilns stand in a ring on the grey plain like a giant's beehives. Five are cold. Smoke rises from the sixth, and from a gap in its dome somebody is watching the road.\"","- A Grey Coat lookout (Scout) with a bow sits on the dome of the fire kiln (area 5). The kilns are joined underground by the old flue tunnels.","- **Puzzle (7.22): the burners' box.** An iron box is set into the yard wall, with six brass plates that slide in any order, marked with a hare, a crow, an oak leaf, a wheel, a fish and a crescent moon. The same six marks are cut over the six kiln mouths, worn by weather. Slide the plates in the order the burners fired the kilns and the box opens. The order is in the bricks: the most weathered mark was fired first (Investigation DC 13). Anyone from Kell's Crossing knows the burners' counting-song: *First the hare and then the crow, then the oak where the embers glow, then the wheel and then the fish, and the moon last, make a wish.* A wrong order puffs soot out of the box: DC 12 Constitution saving throw or Blinded until the end of your next turn. It's all in full view of the lookout on the dome.","","### 2. The cold kiln","> **SAY:** \"Inside the nearest kiln it's dark and dry and smells of old fire. There's a hole in the floor where the flue goes down.\"","- **Trap: the ash pit.** The floor before the hole is a crust over a 10-foot pit of loose ash. Perception DC 13 (the crust is too smooth). Step on it: DC 13 Dexterity saving throw or fall in, taking 1d6 Bludgeoning damage, Blinded while in the ash and coughing (Poisoned until the end of the next turn). Climbing out is a DC 12 Strength (Athletics) check.","","### 3. The flues","> **SAY:** \"The flue tunnels are brick, three feet high and black with soot, and they go off in every direction.\"","- Crawling: Difficult Terrain, and no Dash. Large creatures can't fit. A DC 12 Survival or Perception check follows fresh scuffs to area 4; otherwise they find a dead end first and lose ten minutes.","- **Trap: the bone-rattle.** A string of knucklebones across the last flue clatters in area 5. Perception DC 13 to spot it in the dark; any blade cuts it.","","### 4. The store kiln","> **SAY:** \"This kiln is full to the dome: coats, boots, pots, a cradle, sacks of seed-corn, a plough-blade, a fiddle with no strings. A man is chained to the wall, asleep sitting up.\"","- **Aldo Penn** (Commoner), a cooper from Hallowmere, kept to mend the Grey Coats' barrels. Freed, he tells them how many there are, where Senn sleeps and where she hides her money. He wants his wife's coat back. It's here.","- Nessa's seed-corn is here too. To Kell's Crossing it's worth more than gold.","","### 5. The fire kiln","> **SAY:** \"The last kiln is warm and full of firelight. Bedrolls, a cookpot, a barrel of Hallowmere ale, and a woman in a grey coat with a Tithe-house badge, sharpening a long knife.\"","- **Morra Senn** (Warrior Veteran), **four Grey Coats** (Bandits) and **two lookouts** (Scouts), one on the dome. The fight is *The Grey Coats' kilns* in the Combat tab.","- **Hazard: the kiln mouth.** The furnace door stands open on a bed of coals. A creature shoved into it takes 2d6 Fire damage and must use its next move to get out.","- Her badge is real, and she says so: \"I'm the Tithe-house. You can't rob the Tithe-house.\" If they show her the Court has no hold on them, she runs.","","### 6. The chimney cache","- **Hidden:** in the fire kiln's chimney, one brick is a different color (Perception DC 15, or Aldo knows). Behind it: 120 gp, the Grey Coats' list of who they've robbed, and a pair of grey courier's boots.","","**Rewards.**","- **Senn's Running Boots,** Boots of Striding and Springing (uncommon, requires attunement): a Court courier's boots, before she took them. With them, 120 gp, and two Potions of Healing on the cookpot shelf.","- **The store kiln.** Everything goes back to the families, and Kell's Crossing feeds the party for as long as they stay. They have friends at the Crossing.","- **The burners' box (7.22):** 50 gp in old coin, an Orb of Direction, and a Potion of Resistance (Cold), which is worth having on the glass. Whoever worked it out gains Heroic Inspiration.","","**Afterwards.** Isolde's coach passes the kilns next day. If Senn escaped, she tells Isolde which way they went."],"Location"],
 ["v7-place-reeves-icehouse","THE REEVE'S ICEHOUSE","icehouse, reeve's icehouse, Ketter Mawl, wreckers",["**A side dungeon for Session 10 (7.21): a wreckers' hideout at the edge of the glass, frozen the night Glassreach froze, with the wreckers still inside.** Level 5, five rooms, two traps, one fight that can be talked down, about 45 minutes. The play is *Side dungeon: the reeve's icehouse*.","","**What's going on.** On the night the winter came, in 2 SS, five wreckers were in the reeve's icehouse dividing their last haul. They'd lit false lights on the headland and wrecked a merchant ship. The glass caught them mid-count. They're Stilled now: alive, frozen, and still arguing about the share.","","**Getting there:**","- Yara: \"Don't go in the icehouse at the reeve's house. When it's quiet you can hear them counting.\"","- On the path in (Scene 4), a glass house with a cellar door, and Glass-Wolf prints that go down and don't come back up.","- Corran Vell, if he's awake: \"There were wreckers on this coast. They lit lights. If you find them, I'd like a word.\"","","**Running it.** Every rule of the glass holds: **warmth wakes people gently; breaking the glass hurts them.** These Stilled are wreckers, not innocents, but they're still people. Glassreach is Extreme Cold.","","### 1. The reeve's house","> **SAY:** \"The house is glass to the eaves. Through the window you can see a table laid for supper four hundred years ago: bread, a jug, and a candle whose flame has frozen into a little yellow tear.\"","- On the door, under the frost, a notice in old Corvanese: *Wreckers seen on the headland. Lock your doors. By order of the Reeve.*","- The reeve is Stilled at his table, spoon raised. Woken gently (an hour by a fire), he says, \"They're in my icehouse. They said they'd kill my wife.\" His wife isn't here.","","### 2. The icehouse stair","> **SAY:** \"Steps go down into the ground beside the house, cut into the earth and glazed with four centuries of ice.\"","- Without rope, spikes or crampons, each character makes a DC 12 Dexterity (Acrobatics) check or slides to the bottom, taking 1d6 Bludgeoning damage. The noise wakes the frost-motes in room 3.","","### 3. The ice-cellar","> **SAY:** \"Blocks of lake ice are stacked to the ceiling in rows, cut and stored for a summer that never came. The aisles between them are narrow, and very cold.\"","- **Trap: the spring-crossbow.** A wire at shin height across the main aisle (Perception DC 14: the frost on it is thinner) fires a heavy crossbow: +5 to hit, 1d10 + 2 Piercing damage. Thieves' tools DC 12 disarms it, or just step over.","- **Trap: the gin-trap.** A bear-trap under the frost in the side aisle. Perception DC 13. DC 13 Dexterity saving throw or 2d6 Piercing damage and Restrained (a DC 13 Strength check opens it). The cold has made it brittle: any Bludgeoning damage breaks it.","- **Frost-motes:** four Ice Mephits live in the ice, spiteful little knots of cold. They come out for noise, fight for fun, and love breaking glass.","","### 4. The counting room","> **SAY:** \"Five figures sit round a barrel-head table, frozen mid-argument. Coins are stacked in front of them. The tall one has his knife half out of his belt, and his mouth is open on a word you'll never hear.\"","- **Ketter Mawl and four wreckers,** Stilled. Gentle warmth wakes them one at a time over an hour. They think it's still 2 SS, that the party are the reeve's men, and that the haul is theirs. Influence DC 15 calms one (Advantage if you show them how long it's been).","- **Woken roughly** (fire in their faces, broken glass, a fight next door), three come at the party as Stilled and the other two run. With the frost-motes it's *The reeve's icehouse* in the Combat tab.","- **Ketter, calmed,** wants one thing: to know whether his sister got out. Nobody knows. For a kind answer he tells them where the haul is.","","### 5. The hoard","- **Hidden:** under the barrel-head, a trapdoor (Investigation DC 14, or Ketter tells them). The haul is frozen in one block in the hole. Thaw it with fire for ten minutes (careful of the Stilled) or chip it out in an hour.","- **Inside:** 220 gp in old coin (double that to a collector in Pellmoor), two Potions of Healing, a merchant's seal with a ship under three stars, and a ring that's warm even here.","","**Rewards.**","- **The Merchant's Ring,** a Ring of Warmth (uncommon, requires attunement). In Glassreach its wearer succeeds on every Extreme Cold save.","- 220 gp in old coin and two Potions of Healing.","- **The seal.** A ship under three stars is the badge on Corran Vell's sea-coat: the wreckers had his ship. Given to him, it's the first thing in four hundred years that's been his. Each character who gives it to him gains Heroic Inspiration.","- **The wreckers,** woken gently, go to Yara's camp. They're dreadful company, but they know the glass.","","**Afterwards.** If the wreckers were woken roughly, the two that ran stand among the Stilled in the Session 11 ambush, and they remember the party."],"Location"],
 ["v7-place-frost-spire","THE FROST SPIRE, AREA BY AREA","Frost Spire, inner stair, Sexton's inner stair, Bell-Warden",["**The Frost Spire as a dungeon (7.21): the Sexton's inner stair.** Imber had the stair cut, and he's never told anyone there were two of them. The second runs up inside the ice, from a bronze door at the north foot to the crown. **This is Session 14's dungeon and the main way up:** run it in place of Scene 2's three climbing checks. A party that would rather climb the open face can still take the outer stair, and the two stairs meet at 60 and 100 feet. The play is *The Sexton's door: the dungeon inside the Spire*.","","- **Level 6.** About 1 hour 15 minutes for the whole climb, 45 minutes the short way (areas 1, 2, 5, 8, 9 and 10). The long way adds the masons' gallery, the echo stair, the choir loft and the icicle gallery.","- **Where to break:** in the lamp-room (area 5).","- **What doesn't change:** Extreme Cold (Constitution DC 10 each hour; a warm cloak succeeds), the Stilled rules (Influence DC 15 as an action calms one, Advantage for reading its ribbon), and magic hums loudly enough for the pack to hear.","- **Inside and out:** the lamp-room window (60 feet) opens onto the outer stair beside the red-ribbon man; a crack in the icicle gallery (100 feet) opens beside another Stilled; the rope shaft runs straight from the lamp-room to the ringing room.","","### 1. The Sexton's door (the north foot)","> **SAY:** \"Behind the sleeping wolves, at the very foot of the north face, the ice is thinner. Under it, like a face under water, is a bronze door twice the height of a man, with the nine-bell sign of the Ninefold Church cast in its centre.\"","- **Finding it:** no roll. Anyone who walks round the foot sees it. Imber points to it if he's free, Yara's map marks \"a door I could never open\", and Maren Talla remembers the masons going in.","- **Opening it:** chip the ice for ten minutes (DC 14 group Stealth check or the wolves wake, as in Scene 1); fire for ten minutes (the pack smells smoke, and one wolf comes to look); Thunder damage cracks it at once and wakes the whole pack; or hum the Spire's note into the bronze (Performance DC 13, Advantage if someone has heard Imber hum it). It opens with a sigh of air four hundred years old.","","### 2. The vestibule of petitions","> **SAY:** \"A round room the color of deep water. The walls are thick with folded papers, thousands of them, frozen into the ice like leaves in a pond. The floor is clear ice too, and under it, a long way down, something dark.\"","- **The petitions** are prayers people left for the High Sexton: *let the harvest come; let my son come home.* One by the door is in Imber's own hand: *Let me go on.* (Investigation DC 10.) It matters in area 9.","- **Trap: the thin floor.** The middle of the floor is thin ice over the old cistern. Perception DC 12 spots the white crazing; round the edge it holds. Anyone who crosses the middle makes a DC 13 Dexterity saving throw or breaks through and drops 10 feet into freezing water: 1d6 Bludgeoning damage, and 1 Exhaustion level unless they're dried at a fire within the hour. Climbing out is a DC 12 Strength (Athletics) check.","","### 3. The masons' gallery (10 to 40 feet)","> **SAY:** \"The stair spirals up into a long, low gallery. Bunks are cut into the ice walls with blankets frozen stiff on them, and tools hang on pegs: chisels, mallets, a saw as long as a man. At a workbench a woman in a leather apron is frozen with a chisel in her hand, frowning at something.\"","- **Tilsa Dunmore, master mason,** Stilled. Woken gently (an hour of warmth), she says: \"Two stairs. He made us swear. One for the people to see, and one for him.\" She knows about the hoist and the echo.","- **The hoist:** a frozen platform on a chain, up to the lamp-room. Thaw the winch with fire (ten minutes) or force it (a DC 13 Strength (Athletics) check; it shrieks, and the wolves hear). It skips area 4.","- **Treasure: the foreman's chest** under the workbench, frozen shut: fire for ten minutes, or a DC 14 Strength check. Inside: Boots of the Winterlands, 80 gp in old coin and a Potion of Fire Breath.","","### 4. The echo stair (40 to 60 feet)","> **SAY:** \"The stair climbs in a tight spiral, smooth as glass. When you speak, your words come back a moment later from below. Then again, fainter. Then again.\"","- **Hazard: the echo.** Anything loud (a shout, a spell with a Verbal component, a fall, a fight) runs down the stair and out of the Sexton's door. A DC 12 group Stealth check climbs quietly; Silence stops it.","- **On a failure,** the Glass-Wolves wake and come in through the door 6 rounds later: *The echo stair* in the Combat tab. They come up one or two abreast, and stop at 60 feet, howling.","","### 5. The lamp-room (60 feet)","> **SAY:** \"A small round room with a great iron lamp in the middle, full of frozen oil. One wall is a single sheet of clear ice, like a window, and through it, a few feet away, a man with a red ribbon stands on the outer stair with his back to you.\"","- **The window.** The red-ribbon man is the one Yara never got past. The pane (AC 13, 15 HP) opens onto the outer stair, and breaking it puts him within 5 feet: he wakes (Influence DC 15, Advantage for his ribbon).","- **The lamp.** Thaw the oil (fire, ten minutes) and light it, and the room is warm: a Short Rest here needs no cold save, and nobody makes the hourly save while they stay. But the light shines through the ice for miles. Isolde sees it, and in Session 15 she knows which way they'll come down.","- **The rope shaft** (area 8) starts here: a hole in the ceiling, with the frozen bell-rope hanging through it.","","### 6. The choir loft (60 to 90 feet)","> **SAY:** \"The stair opens into a tall gallery with tiers of seats cut into the ice, and on the seats, the choir: thirty people in white robes, mouths open, frozen in the middle of a hymn. Small cold lights drift among them like sparks that have forgotten to fall.\"","- **The choir.** Most are frozen deep and don't wake. Four in the front row are close to the surface: noise within 10 feet, or glass breaking, wakes them Stilled and frightened. Influence DC 15 calms one; singing the hymn they're stuck in (Performance DC 13) calms all four at once, and they sit down.","- **Frost-motes:** four Ice Mephits. They hate warmth and noise, and start the fight if anyone lights a torch. The fight is *The choir loft* in the Combat tab.","","### 7. The icicle gallery (90 to 110 feet)","> **SAY:** \"A long gallery under a ceiling of icicles, thousands of them, some as long as spears. They chime, very faintly, when you breathe.\"","- **Hazard: the icicles.** A loud noise brings down the icicles in a 10-foot square round it: DC 13 Dexterity saving throw or 2d6 Piercing damage. Thunder damage brings down the whole ceiling: 4d6 Piercing damage to everything in the gallery, half on a success. A clever party lures pursuers in first.","- **The crack:** halfway along, a crack in the outer wall opens onto the high stair at 100 feet, beside a Stilled.","","### 8. The rope shaft (60 to 140 feet)","> **SAY:** \"The bell-rope hangs down the middle of the Spire through a shaft in the ice, thick as your wrist and frozen as stiff as an iron bar. It goes up into the dark.\"","- **The shortcut:** climb the rope from the lamp-room to the ringing room, 80 feet, skipping areas 6 and 7. Two DC 12 Strength (Athletics) checks; on a failure you slide 20 feet back down and take 1d6 Slashing damage stopping yourself. Fly, Spider Climb or a rope tied off from above makes it automatic.","- **Don't haul on it.** A hard pull (DC 20 Strength) moves the frozen bell a hair: Hieme hums, everyone in the Spire hears, and every Stilled stirs.","","### 9. The ringing room (140 feet)","> **SAY:** \"A round chamber where the ringers once stood, with nine rope-holes in the ceiling and only one rope. Suits of armour stand empty against the walls, holding long poles. In the centre, arms at its sides, waits a giant of ice and bronze. Its chest is a cage with a cold blue light inside.\"","- **The Bell-Warden** was made to keep the crown: use the Flesh Golem, with Cold in place of Lightning (Cold damage heals it). **Four Hollow Wardens** (Animated Armor) are the ringers' armour, still on guard.","- **It stands down for the Heart.** If a character holds up Hieme's Heart, or says Imber's words from the vestibule, \"Let me go on\", it lowers its arms and steps aside, and the armour with it. Otherwise it attacks anyone who goes for the last stair: *The Bell-Warden* in the Combat tab.","","### 10. The last stair (140 to 200 feet)","> **SAY:** \"The stair climbs the last sixty feet inside a shell of ice so thin you can see the sky through it, and the forest far below, and smoke on the south-east horizon.\"","- No checks. It comes out at the crown, beside the frozen bell. Go to Scene 3.","","**Wandering cold.** Roll a d6 when they rest, or when the table goes quiet.","","| d6 | What happens |","|---|---|","| 1 | A gust through a crack: everyone makes the hourly cold save now. |","| 2 | The ice clears for a moment, and a frozen face looks out of the wall, inches away. It blinks. |","| 3 | A Glass-Wolf howls at the foot of the Spire, and the others answer. |","| 4 | Two frost-motes (Ice Mephits) drift in, curious. |","| 5 | Hieme hums, very low. Everyone feels it in their teeth. |","| 6 | Through the ice, smoke on the south-east horizon, closer than yesterday. |","","**Rewards inside.** Boots of the Winterlands, 80 gp and a Potion of Fire Breath (area 3); Tilsa's story; the warm rest (area 5). Hieme's Shard and the rest are where the guide puts them."],"Location"],
 ["v7-term-the-road","ON THE ROAD","random encounter, random encounters, road, roads, travel, journey, wandering, encounter table",["**The road is where Corvane surprises people (7.22).** Between one place and the next, roll on the table for the region, or pick what you'd like to happen. Every entry says what to read out, what's going on, what the players can do, and what it's worth.","","**When to roll.**","- **Once per day of travel,** or once per long stretch of road. Skip the roll if the session is already full.","- **Pick rather than roll** when you know what the table needs: a fight for a quiet night, a laugh for a heavy one, a find before a hard dungeon.","- **Cross off what you've used.** Reroll a repeat, except the wayshrine and the peddler, who turn up anywhere.","","| Region | When | Level | Page |","|---|---|---|---|","| The coast road | Act I, and the road to Hallowmere | 3 to 4 | The coast road |","| Hallowmere and its lanes | Act II | 3 to 5 | Hallowmere's streets |","| The North Road and the glass | Act III | 5 to 6 | The North Road |","| The Brass Road and the steppe | Acts IV and V | 7 to 11 | The Brass Road and the steppe |","","**What's on every table.**","- **Fights** that can usually be talked out of, with numbers for four characters.","- **Finds:** wrecks, shrines, caches and strange places, often with a roll on the Random magic table (see Random magic and wonders).","- **People** with a problem, which is where most of the good stories start.","- **Oddities:** things that make Corvane feel old and haunted.","- **News:** the world moving on without the party, so it feels as if it's alive.","- **A wayshrine and the peddler,** Gammer Tansy and her mule (see Random magic and wonders).","","**Making it feel alive.**","- **People they meet on the road come back.** The carter they helped is at the next inn; the bandit they let go is in the crowd at the hanging. Write down who they met.","- **The road reacts to what they've done.** After a big event (a bell rung, a dungeon cleared, a Court officer embarrassed), let the next road roll carry the news: a song about it, a reward poster, a stranger buying them a drink.","- **Not every day needs a roll.** A quiet day is a description and a campfire question: \"What do you talk about tonight?\"","","**A quiet day on the road (d8).**","1. > **SAY:** \"Rain comes in sideways off the sea, then stops as if someone shut a door on it. Everything steams.\"","2. > **SAY:** \"A heron stands in a ditch and watches you go by, very seriously, the whole length of the field.\"","3. > **SAY:** \"You pass a farmhouse where somebody is singing badly and happily behind a wall. The song stops when they hear your boots, then starts again, quieter.\"","4. > **SAY:** \"The road runs straight for miles between stone walls. Somebody has balanced a pebble on top of every hundredth stone.\"","5. > **SAY:** \"Wind in the grass, the whole afternoon. When it drops, the silence is so big you can hear your own heart.\"","6. > **SAY:** \"A dog follows you for a mile, decides you're not interesting, and trots home.\"","7. > **SAY:** \"At dusk the sky goes the color of a bruise, then of a peach, then of nothing at all. Somewhere far off, a bell rings once.\"","8. > **SAY:** \"You camp under a tree that somebody has carved initials into, hundreds of them, over hundreds of years. Some of the oldest are names you've heard.\""],"Lore"],
 ["v7-place-coast-road","THE COAST ROAD","coast road, Pellmoor road, Old Shore road, road to Hallowmere",["**The coast road (7.22): Pellmoor, the Old Shore, the Mute Mere and the road to Hallowmere.** For Act I and the road to Hallowmere, levels 3 to 4. Roll a d12 once per day of travel, or pick. See On the road for how to use it.","","| d12 | What | Kind |","|---|---|---|","| 1 | The bell in the reeds | Find |","| 2 | The clerk in the ditch | People |","| 3 | The chain across the road | Fight |","| 4 | Lights in the fog | People |","| 5 | The weeping milestone | Oddity |","| 6 | A wayshrine | Find |","| 7 | Gammer Tansy | People |","| 8 | A ferry-folk burning | People |","| 9 | The wreckers' lantern | Fight |","| 10 | The girl with the jar | People |","| 11 | The chapel at low tide | Find |","| 12 | The crier at the crossroads | News |","","### 1. The bell in the reeds","> **SAY:** \"Something is ringing out in the reed-beds, very faintly, every time the wind comes off the Mere. Not a church bell. Smaller. Patient, as if it's been calling for a long time.\"","- **What's going on:** a fishing boat, the *Kittiwake*, sank here last winter. Its warning bell is caught on a post in the reeds, and the boat is 8 feet down under it, with the skipper's strongbox still in the cabin.","- **What to do:** wading out is a DC 10 Strength (Athletics) check through sucking mud (fail: stuck, and 10 minutes lost). Diving down needs a held breath. A Mere eel (Constrictor Snake) has made the cabin its home; it lets go if it's hit hard once, or for a fish.","- **Reward:** the strongbox (thieves' tools DC 12, or smash it and wet everything): 2d10 gp and one roll on the Random magic table, wrapped in oilcloth. **The bell:** carried to the Old Shore, the ferry-folk know the boat by its note, and the skipper's widow gives them a free crossing whenever they want one.","","### 2. The clerk in the ditch","> **SAY:** \"A Court gig lies on its side in the ditch, one wheel spinning. Beside it a thin man in grey is shouting at the horse, which is eating the hedge and ignoring him.\"","- **What's going on:** Clerk Anselm Grebe is carrying tithe receipts to Hallowmere, and his axle has snapped. He's pompous, frightened and very late.","- **What to do:** fix the axle (a DC 12 Strength (Athletics) check to lift the gig and a DC 10 check with carpenter's or tinker's tools, or improvise one with a branch and rope). Or read his receipts while he's busy (Sleight of Hand DC 13): they show which villages are behind, and who's going to be visited by Hushmen. Or leave him.","- **Reward:** helped, he writes them a travel pass in his own hand. It gets them through one Court checkpoint in Hallowmere without a question. Robbed, he remembers their faces, and says so in his report.","","### 3. The chain across the road","> **SAY:** \"A chain is stretched across the road between two posts, and a hut has been built beside it out of an upturned boat. Four Hushmen lean on their spears. 'Road-tithe,' says the sergeant. 'Five gold each, or one memory. Your choice. We're not unreasonable.'\"","- **What's going on:** they aren't Hushmen. They're bandits in stolen coats, led by \"Sergeant\" Rusk, and a peddler they robbed this morning is tied up in the hut.","- **What to do:** Insight DC 13, or anyone who has met a real Hushman: the buttons are bone, not pewter, and the spears are fish-gigs. Pay, bluff (Deception DC 13 to claim to be Court yourself), or fight: *The chain across the road* in the Combat tab. Called out as fakes in front of the peddler, two of the four throw their coats down and run.","- **Reward:** 30 gp and a sack of other people's things in the hut. **A real Hushman's coat** (they took it off a drunk): wearing it gives Advantage on Deception to pass as a Hushman at a distance. **The peddler** is Gammer Tansy. Freed, she gives each of them one oddity from her pack for nothing (see Random magic and wonders), and she remembers them for the rest of the campaign.","","### 4. Lights in the fog","> **SAY:** \"Fog comes off the Mere at dusk, thick as wool. Out in it, low on the water, two lights blink, twice and then once. On the shore below the road, somebody answers with a shuttered lantern.\"","- **What's going on:** a Coster night boat landing bottled memories in a cove, out of sight of the harbor and its clerks. Four boatmen (Commoners) and a tally-man, Dace's cousin Lorn (Spy), who has a crossbow and no interest in a fight.","- **What to do:** watch (DC 13 group Stealth check), follow the cart inland, or walk down and ask. Lorn will pay 20 gp to be forgotten. Pressed (Intimidation DC 14), he'll say where the cart's going: the Vennmark bond-house, or Hallowmere's Tithe-house.","- **Reward:** the bribe, or six crates of fine Amnian wine (10 gp a bottle, twelve bottles a crate) if they take the cargo, or a story to tell Sela Maunt, who'll owe them a favor.","","### 5. The weeping milestone","> **SAY:** \"The milestone says HALLOWMERE 31 in letters worn nearly flat. Salt water is running down its face, though it hasn't rained all day, and the stone is warm when you touch it.\"","- **What's going on:** a woman named Ottilie paid a memory to the Tithe forty years ago, and the Tithe-man was lazy: he put it into the nearest stone. Whoever touches it sees a few seconds of her last walk along this road with her sister.","- **What to do:** Arcana or Religion DC 13 knows what it is. A *Dispel Magic*, a hammer and a DC 15 Strength check, or a heartfelt request (the stone only wants to be listened to) lets the memory go. The sister, Maud, is alive and very old, in the next village.","- **Reward:** told about it, Maud weeps and gives them her sister's ring (a silver ring worth 25 gp) and the best meal they'll have in Act I. The character who freed the memory gains Heroic Inspiration.","","### 6. A wayshrine","> **SAY:** \"At the fork stands a little stone shrine no higher than your waist. It's shaped like a bell, with a niche in its side, a dish in the niche and moss on everything. There's something in the dish.\"","- Roll on Wayshrines in Random magic and wonders.","","### 7. Gammer Tansy","> **SAY:** \"A mule comes round the bend under a load three times its size: pots, lanterns, birdcages, a mirror, a rocking horse. Walking beside it is a tiny old woman with a clay pipe. 'Buying or selling?' she says. 'I'm both.'\"","- See Gammer Tansy in Random magic and wonders.","","### 8. A ferry-folk burning","> **SAY:** \"Out on the grey water a little boat is burning, slow and steady. On the shore twenty people stand in a line, singing a song with no words. An old woman sees you and walks up the bank to the road.\"","- **What's going on:** a ferryman's funeral. His family tithed their memories of him to pay their debts, and none of them can remember his face. They need strangers to say his name, Jory Fenn, three times over the water, so somebody living has.","- **What to do:** say it. Someone who sings with them (Performance DC 10) makes it a good one. Insight DC 12: the old woman, his mother, can't remember him either, and is pretending.","- **Reward:** the ferry-folk carve them an oar-token; shown on the Old Shore, any ferry-folk boat takes them anywhere on the Mere for nothing. His mother gives them his knife (a silver-chased dagger worth 25 gp) because \"it should go with somebody who knew his name\".","","### 9. The wreckers' lantern","> **SAY:** \"On the cliff path above the road, a lantern is swinging from a pole at the very edge, where no lantern should be. Out at sea, a ship's lights are turning toward it.\"","- **What's going on:** wreckers want the ship on the rocks by midnight. Three of them (Bandits) and their boss, Nan Scarrow (Bandit Captain), wait in a gully below.","- **What to do:** put the lantern out and light a warning fire on the headland (a DC 12 Survival check to light it fast in the wind), or drive the wreckers off. They come up to stop it: three Bandits and a Bandit Captain, a little under Low for four level 3 characters. They run if Nan drops.","- **Reward:** the ship, the *Saffron Gull* out of Amn, puts in at Pellmoor next day. Her captain pays 25 gp each, and her cargo includes one crate she'll open for them: one roll on the Random magic table.","","### 10. The girl with the jar","> **SAY:** \"A girl of about nine is sitting on the milestone with a bottle in her lap. It glows faintly. 'Five gold,' she says, holding it up. 'Da says I'm not to come home with it.'\"","- **What's going on:** it's her father's memory of her mother, who died. He bottled it because he couldn't bear it, and now he can't bear to keep it.","- **What to do:** buy it for 5 gp. Walk her home and talk to her father, Aldo Brack, a cooper (Influence DC 13; Advantage if they show they understand). Or give her the money and the jar both.","- **Reward:** if the jar goes home and he drinks it back, he weeps, and the whole family will hide the party, feed them or lie for them for the rest of the campaign. Each character who helped gains Heroic Inspiration. Sold on, it fetches 15 gp from Venn.","","### 11. The chapel at low tide","> **SAY:** \"The tide is out further than you've ever seen it. Half a mile across the wet sand stands a chapel, its roof gone, its door still on its hinges, the water still draining out of its windows.\"","- **What's going on:** a chapel of Old Pellmoor that drowned in 14 SS. The tide gives them an hour.","- **What to do:** walk out (Survival DC 12 to keep out of the soft sand), and search before the water comes back. The reliquary behind the altar is hidden (Investigation DC 13). Track time: after 50 minutes the sea comes in fast, and getting back is a DC 12 Strength (Athletics) check each, or swim the last stretch.","- **Reward:** 2d6 × 5 gp in Old Pellmoor coin (collectors in Hallowmere pay half as much again), a silver chalice worth 50 gp, and one roll on the Random magic table. On the altar, under the weed, the chapel's bell-hymn; the Dawn Mission will pay 25 gp to copy it.","","### 12. The crier at the crossroads","> **SAY:** \"A Court crier stands on a cart at the crossroads, ringing a handbell, with a little crowd round him. 'Hear the Chancellor's word!' he shouts, and unrolls a paper.\"","- **What's going on:** the world moving on. Pick one, or roll a d4:","  1. A new curfew in Pellmoor, from sunset to the dawn bell.","  2. A reward of 100 gp for news of \"persons interfering with the Tithe\", with a rough sketch. If the party has been noticed, the sketch is one of them, badly drawn.","  3. The price of a heartkeep has gone up; the Tithe-house is buying.","  4. A pardon for any debtor who tithes this month. People in the crowd look at each other.","- **Reward:** news. A Persuasion DC 12 afterwards gets a rumor about the next place they're going."],"Location"],
 ["v7-place-hallowmere-streets","HALLOWMERE'S STREETS","Hallowmere streets, Grey City streets, Tallow Lane, Tallow Boys, night in Hallowmere",["**Hallowmere's streets (7.22): the Grey City, its canals and lanes, and the country round it.** For Act II, levels 3 to 5. Roll a d12 when they cross the city, or once a day on the roads outside, or pick. See On the road.","","| d12 | What | Kind |","|---|---|---|","| 1 | A Blank on the bridge | People |","| 2 | The silent procession | People |","| 3 | The book-burning | People |","| 4 | Knives in Tallow Lane | Fight |","| 5 | A wall-shrine | Find |","| 6 | Gammer Tansy | People |","| 7 | The girl on the roofs | People |","| 8 | The Tithe-house cart | Find |","| 9 | Madame Orsini | Oddity |","| 10 | Pistols at dawn | People |","| 11 | The speaking skull | Oddity |","| 12 | Papers, please | News |","","### 1. A Blank on the bridge","> **SAY:** \"A man in a good coat is standing in the middle of a canal bridge, turning a key over and over in his hands. People walk round him. Across the square, two Hushmen have noticed him too, and they're coming.\"","- **What's going on:** Tomas Wedd tithed one memory too many this morning and has forgotten where he lives. If the Hushmen get him, he goes to the Tithe-house as a Blank.","- **What to do:** turn out his pockets. The key has a tag, *Pin Lane, 4*, and Investigation DC 12 finds the rest (a letter to his wife). Or stall the Hushmen (Deception or Persuasion DC 14: \"He's our uncle, he's drunk\"), or walk him away fast (DC 12 group Stealth check).","- **Reward:** his wife, Hanne, hides them in the attic any night in Act II. Tomas was a locksmith, and even now his hands remember: once, he'll open any lock in Hallowmere for them, no roll.","","### 2. The silent procession","> **SAY:** \"A bell rings once, and the whole street stops. Carts. Children. A woman with her mouth open in the middle of a word. Down the middle of the road comes a line of grey-robed clerks, and nobody makes a sound.\"","- **What's going on:** a Procession of the Quiet. By law the street is silent until it has passed, about five minutes. A pickpocket is working the frozen crowd, and he's heading for the party.","- **What to do:** stay silent (anyone loud, nervous or with an animal makes a DC 12 Constitution or Performance check). Notice the pickpocket (Perception DC 14) and catch him without a sound (Sleight of Hand or Athletics DC 13). Anyone who speaks is taken aside by a Hushman and fined 5 gp, or a memory.","- **Reward:** the pickpocket, a boy called Wick, is grateful to be let go. He becomes their eyes on the street: once per session, a rumor or a warning.","","### 3. The book-burning","> **SAY:** \"In the square, clerks are feeding books into a brazier, one at a time, reading out each title before it burns. An old man in ink-stained sleeves stands beside the cart with his hands over his mouth.\"","- **What's going on:** the Court is burning unlicensed histories of the bells. The bookseller is Absalom Dray (see Shops of Hallowmere).","- **What to do:** swipe a box from the cart (Sleight of Hand DC 13, with a distraction), pose as clerks come to collect \"evidence\" (Deception DC 14), or buy them out of the fire (a bribe of 20 gp to the senior clerk, Influence DC 12).","- **Reward:** a box of six books. Among them a Spell Scroll (level 1) of the DM's choice, and *A True History of the Concord*: anyone who reads it (an hour) has Advantage on one History or Religion check about the bells. Absalom gives them a discount for life.","","### 4. Knives in Tallow Lane","> **SAY:** \"Tallow Lane is narrow and dark, and the lamps have been put out. Halfway down, someone steps out of a doorway ahead. Behind you, somebody else does the same.\"","- **What's going on:** a gang of cutpurses, the Tallow Boys, who think the party looks rich and lost.","- **What to do:** fight (*Knives in Tallow Lane* in the Combat tab for Session 5): four Bandits, the two Tallow brothers (Toughs) and their leader, Silk Annie (Spy), a little under Low for four level 3 characters. A show of strength or magic (Intimidation DC 13) sends them running before it starts. They run when Annie drops or two of them do.","- **Reward:** 15 gp between them, a set of thieves' tools, and Annie's map of the city's back ways: with it, the party never needs a check to get across Hallowmere unseen at night.","","### 5. A wall-shrine","> **SAY:** \"Set into a wall at the corner of the lane is a niche no bigger than a bread oven, with a little bronze bell hung in it, green with age. Somebody has left something in the dish beneath.\"","- Roll on Wayshrines in Random magic and wonders.","","### 6. Gammer Tansy","> **SAY:** \"In the middle of the Grey City, in a street where nobody sells anything without a licence, a mule is eating a window box. Its owner, a tiny old woman with a clay pipe, looks up. 'Oh, it's you. Buying or selling?'\"","- See Gammer Tansy in Random magic and wonders. She has never had a licence in her life.","","### 7. The girl on the roofs","> **SAY:** \"Slates clatter overhead. A girl comes over the gutter and drops into the lane right in front of you, with a leather satchel under her arm and Hushmen shouting on the roof behind her. She looks at you, shoves the satchel into somebody's hands and is gone.\"","- **What's going on:** Lark is a Harper runner. The satchel holds Court arrest warrants for tomorrow night, twelve names. One is someone they know.","- **What to do:** hide it (Sleight of Hand DC 12 before the Hushmen drop down), hand it over, or run. Two Hushmen arrive in a round; they want the girl, not the party, unless the party gives them a reason.","- **Reward:** the warrants. Warning the twelve saves them, and everybody in their street hears who did it. Lark finds them that night. The Harpers owe them a favor, and Lark will carry one message anywhere in Hallowmere for them, no questions asked.","","### 8. The Tithe-house cart","> **SAY:** \"A covered cart goes by, heaped with the belongings of people who no longer remember owning them. Shoes. Toys. A clock. It hits a rut, a box falls off the back, and something inside it is glowing.\"","- **What's going on:** Blanks' belongings, on their way to be sold at the Tithe market. The driver doesn't care what falls off.","- **What to do:** pick it up. The driver shrugs. Or follow the cart to the market (see Shops of Hallowmere).","- **Reward:** one roll on the Random magic table, and a name scratched inside the box lid: Elsa Marrow. If they find her (she's a Blank in the Lamplighters' cistern, or at the Dawn Mission), she won't remember it, but she'll smile at it.","","### 9. Madame Orsini","> **SAY:** \"A booth in an archway, hung with bead curtains. 'Madame Orsini Reads Keeps,' says the sign. A hand with a great many rings beckons. 'Come, come. One copper. I see the past, the future, and sometimes your mother.'\"","- **What's going on:** she's mostly a fraud, but she has a touch of real sight.","- **What to do:** let her read one character. Give the player one line that will be true, from what's coming in your campaign. For example: \"You will be asked to choose between a bell and a friend\"; \"Someone you saved will save you, but not in the way you think\"; \"You will meet your own face in the snow.\" Insight DC 15 catches her guessing the rest from their clothes.","- **Reward:** when the prophecy comes true, that character gains Heroic Inspiration.","","### 10. Pistols at dawn","> **SAY:** \"In a little park by the canal, two young men in good coats are taking off their gloves, very slowly. A third holds a pair of swords and looks as if he might be sick. One of the duellists is very good. The other is fifteen.\"","- **What's going on:** young Lord Perrin Ashby insulted the Chancellor's nephew, Ser Osric Vale, and Osric means to kill him.","- **What to do:** talk them out of it (Persuasion DC 14, or DC 10 with a good joke that lets Osric keep his pride), take Perrin's place (Osric fights to first blood against an adult: a Knight, and he stops when he's hit), or trick them.","- **Reward:** the Ashby family send a gift of 50 gp and an invitation to supper, and Perrin's older sister, a Court clerk, will tell them one thing from the Chancellor's office. Osric remembers them too.","","### 11. The speaking skull","> **SAY:** \"The Bone Archive's cart is stopped outside a tavern while the driver drinks. It's full of skulls, each with a paper label tied to it. As you pass, one of them says your name, very quietly.\"","- **What's going on:** an old Archive skull with a scrap of the bells' magic in it. It belonged to Brother Calloway, a bell-keeper, and it knows things.","- **What to do:** ask it three questions before the driver comes back; it answers like *Speak with Dead*, about the bells and the Concord. Take it (Sleight of Hand DC 12), and it talks at night, which is annoying, and helpful once more.","- **Reward:** three true answers. Taken, it gives one more answer in each later act, then is quiet.","","### 12. Papers, please","> **SAY:** \"A Hushman checkpoint has been set up overnight across the end of the street, with a table, a clerk and a lamp. 'Papers,' says the clerk, not looking up.\"","- **What's going on:** the Court tightening its grip. Everyone in Hallowmere is asked for papers now.","- **What to do:** show papers (a forged writ from the Inkwell passes without a roll), bluff (Deception DC 14), turn round (a Hushman notices: DC 13 group Stealth check), or go over the roofs.","- **Reward:** none but getting past. If they're caught, they're fined 10 gp each and their names go on a list, which matters in Session 9."],"Location"],
 ["v7-place-north-road","THE NORTH ROAD","North Road, ash plain road, bounty-riders, Kettle Marr",["**The North Road (7.22): the ash plain, Kell's Crossing and the edge of the glass.** For Act III, levels 5 to 6. Roll a d12 once a day, or pick. See On the road.","","| d12 | What | Kind |","|---|---|---|","| 1 | The families going north | People |","| 2 | Ash-storm | Find |","| 3 | The bounty-riders | Fight |","| 4 | The scarecrow field | People |","| 5 | A wayshrine | Find |","| 6 | Gammer Tansy | People |","| 7 | The frozen wagon | Find |","| 8 | The wolf with the splinter | People |","| 9 | The singing ice | Oddity |","| 10 | The burned waystation | People |","| 11 | The falling star | Find |","| 12 | The pigeon | News |","","### 1. The families going north","> **SAY:** \"Ahead, a line of carts has stopped on the road. Children sit on bundles. A man is lying under the last cart, cursing at a wheel. A woman runs back to you and grabs your arm. 'Riders,' she says. 'An hour behind us. Maybe less.'\"","- **What's going on:** six families running from the Tithe toward Kell's Crossing, with Court riders on their trail.","- **What to do:** fix the wheel (a DC 12 check with tools, or a DC 14 Strength (Athletics) check to hold the axle while somebody else does), carry the children, or lay a false trail for the riders (Survival DC 14). If they fail, the riders catch up: run *The bounty-riders* (entry 3), or let them talk the riders off.","- **Reward:** the families reach the Crossing and tell everyone. The party eat and sleep free there, and one mother gives them a carved wooden bell on a cord: hold it and pray, once, and gain Heroic Inspiration.","","### 2. Ash-storm","> **SAY:** \"The sky turns the color of a dirty sheet. Then the wind comes, full of grey ash, and the world shrinks to the length of your arm.\"","- **What's going on:** a storm off the old burn-scars. It lasts 1d4 hours.","- **What to do:** press on (a DC 12 Constitution saving throw each hour, or 1 level of Exhaustion), or shelter. Survival DC 13 finds a half-buried coach. Inside it is a dead Court courier and his satchel.","- **Reward:** the satchel holds a sealed letter (the Court's orders for the road north: where its patrols will be for the next three days, so the party can avoid them) and one roll on the Random magic table. The courier's horse is still alive, tied to the coach and terrified: Animal Handling DC 12 and it's theirs (a riding horse, worth 75 gp).","","### 3. The bounty-riders","> **SAY:** \"Riders on the ridge: eight of them, in grey coats, with a man in a wide hat at the front. He takes a paper out of his coat, looks at it, looks at you, and folds it away. 'Afternoon,' he calls. 'I think you're worth a good deal of money.'\"","- **What's going on:** Kettle Marr is a bounty-rider with a Court warrant and the party's descriptions. Five of his riders are Hushmen (one a sergeant), and two are trackers.","- **What to do:** fight (*The bounty-riders* in the Combat tab), talk (Marr's paid by the head, so a better offer works: Influence DC 15, or DC 12 with 100 gp), or outrun them (a DC 14 group Survival check to lose them in the ash).","- **Reward:** Marr's purse (40 gp), the warrant (it lists what the Court knows about each of them, which is worth reading), and eight horses. Let Marr go, and he turns up in Act IV with a new warrant, or with a job.","","### 4. The scarecrow field","> **SAY:** \"A field of scarecrows, a hundred of them, standing in rows on the ash where a crop used to be. Each one wears real clothes: a farmer's smock, a girl's dress, a soldier's coat. As you pass, one of them turns its head.\"","- **What's going on:** the villagers dressed the scarecrows in the clothes of people who were taken. The one that moved is Pell Hartigan, a farmer, hiding from the Court in his own scarecrow coat.","- **What to do:** Perception DC 12 notices he's breathing. Talk him down (Influence DC 12); he's terrified.","- **Reward:** Pell tells them about the kilns on the plain where the Grey Coats keep what they steal (The kilns at Kell's Crossing), and the back way into the store kiln. He gives them a sack of apples and the best directions on the plain.","","### 5. A wayshrine","> **SAY:** \"A cairn of grey stones by the road, with a little iron bell hung from a stake on top, frosted white. At its foot, a flat stone with something on it.\"","- Roll on Wayshrines in Random magic and wonders.","","### 6. Gammer Tansy","> **SAY:** \"Out of the ash, of all the places in the world, comes a mule with a birdcage on its back and a tiny old woman leading it, smoking a clay pipe. 'You do get about,' she says. 'Buying or selling?'\"","- See Gammer Tansy in Random magic and wonders. Ask her how she got here and she says, \"Walked.\"","","### 7. The frozen wagon","> **SAY:** \"At the edge of the glass a merchant's wagon has stopped in the middle of the road, its two horses frozen mid-stride and its driver frozen with the whip raised. Glass has grown over all of them like frost. The back of the wagon has not been touched.\"","- **What's going on:** they were caught when Glassreach froze. The driver, Jem Sorrel, is Stilled, not dead.","- **What to do:** reach the cargo (no check) or cut the cargo free of the glass (glass-cutting tools, or a DC 13 Strength (Athletics) check; failure is loud, and a Glass-Wolf comes to look in 1d4 rounds; it goes away if it's hit once).","- **Reward:** Jem's strongbox: 3d10 gp, four warm cloaks (worth 10 gp each, and they matter on the glass), a cask of brandy, and one roll on the Random magic table. If the thaw comes, Jem wakes, and he remembers the faces of whoever left his strongbox alone, or didn't.","","### 8. The wolf with the splinter","> **SAY:** \"Tracks round your camp in the morning, big ones, circling and circling. Then you see it: a Glass-Wolf lying in the snow fifty feet away, watching you. It's holding one forepaw off the ground, and it's whining.\"","- **What's going on:** a young Glass-Wolf with a shard of the glass in its paw. It's alone and in pain.","- **What to do:** approach (Animal Handling DC 15; Advantage with food) and pull the shard (Medicine DC 12). Attacked, it runs.","- **Reward:** it follows the party at a distance for the rest of Act III. Once, it howls before an ambush: the party can't be Surprised, and they have Advantage on Initiative. In the Frost Spire, the echo-stair wolves hesitate one round when they smell it on the party.","","### 9. The singing ice","> **SAY:** \"At dusk the ice in a frozen stream begins to sing: not wind, a tune, high and slow, with words you almost catch. It stops when the sun goes.\"","- **What's going on:** it's the old hymn of Hieme, the same one the choir sang in the Frost Spire, frozen into the stream when the glass came.","- **What to do:** listen and learn it (a DC 12 Performance or Intelligence check, or write it down). It sings again tomorrow at dusk.","- **Reward:** anyone who learned it has Advantage on the Performance check to sing the hymn in the Frost Spire's choir loft, and a bard can use it as a song that gives Heroic Inspiration to one listener, once.","","### 10. The burned waystation","> **SAY:** \"The waystation on Yara's map is a black shell, burned out weeks ago. But there's smoke from somewhere under it, and when you come close, the smoke stops.\"","- **What's going on:** a deserter from the Court, Hushman Brannoc, is hiding in the cellar. He set the fire to make people think it was empty.","- **What to do:** talk him out (Influence DC 12; he's starving and ashamed), or force it (he's a Hushman, and he gives up when hit).","- **Reward:** the cellar is full of the waystation's stores: rations for a week, oil, a tent, rope, 2 Potions of Healing. Brannoc tells them the Court's patrol routes and its signal-horns. If they let him go home, he does. If they take him along, he's useful and nervous.","","### 11. The falling star","> **SAY:** \"A light falls out of the sky, bright enough to throw shadows, and hits the plain a mile off the road with a sound like a door slamming. When you get there, there's a crater, still steaming, and in it something black that ticks as it cools.\"","- **What's going on:** a lump of star-iron, the size of a loaf.","- **What to do:** dig it out (a DC 12 Strength (Athletics) check; without gloves, 1d6 Fire damage) before the villagers from the Crossing come to look.","- **Reward:** star-iron is worth 100 gp to any smith, 150 gp to the Ironhorn. Bruna Hardshale or a Brassfall smith will make a weapon from it for nothing, just to have done it: a Moon-Touched Sword that also shines like a star in moonlight.","","### 12. The pigeon","> **SAY:** \"A pigeon drops out of the sky and lands on someone's shoulder, exhausted, with a tiny case on its leg. Then it goes to sleep.\"","- **What's going on:** a message from somebody to somebody else. Pick one, or roll a d4:","  1. A Court officer to Isolde Drave: the party's route, wrong in an important way.","  2. A farmer to his son in Hallowmere: \"Come home. The Tithe-man's gone.\"","  3. Yara to a buyer in Hallowmere: what she's selling, and her prices, higher than she charges the party.","  4. Written in a hand nobody knows: \"Don't go up the Spire by the front.\"","- **Reward:** news. Send the pigeon on, and it finds its way home."],"Location"],
 ["v7-place-brass-road-travel","THE BRASS ROAD AND THE STEPPE","Brass Road travel, steppe road, storm country, lightning tree, deserters",["**The Brass Road and the steppe (7.22): bronze mountains, the storm country, the Ironhorn grass and the roads to the Tor.** For Acts IV and V, levels 7 to 11. Roll a d12 once a day, or pick. See On the road.","","| d12 | What | Kind |","|---|---|---|","| 1 | The lightning tree | Find |","| 2 | The bronze carts | People |","| 3 | The salvage riders | Fight |","| 4 | The sleeping village | Oddity |","| 5 | A wayshrine | Find |","| 6 | Gammer Tansy | People |","| 7 | The dead courier | News |","| 8 | The giant's cairn | Find |","| 9 | The dreamer at the well | People |","| 10 | The deserters | Fight |","| 11 | The horse-fair | People |","| 12 | The weather | News |","","### 1. The lightning tree","> **SAY:** \"A lone oak stands on the hillside, split down the middle by lightning, years ago. It's still crackling. Blue light crawls up and down the wound, and every hair on your arms stands up when you come near.\"","- **What's going on:** a storm-stone has grown in the heart of the tree, fed by lightning that had nowhere else to go.","- **What to do:** cut it out (a DC 14 Strength check with an axe or a pick). Each attempt, the cutter makes a DC 14 Dexterity saving throw: 2d10 Lightning damage, half on a success. Gloves of anything but metal give Advantage.","- **Reward:** a storm-stone, worth 100 gp in Brassfall or to the Ironhorn. Or take it to a Brassfall storm-smith, who binds it into a Javelin of Lightning (uncommon) for 100 gp and the stone.","","### 2. The bronze carts","> **SAY:** \"A line of bronze carts comes down the road toward you, a dozen of them, each pulled by two oxen. Every wheel is humming. The carters keep looking at the sky.\"","- **What's going on:** a Brassfall cart-train, carrying bronze to the steppe. A storm is coming, and if lightning hits a cart, it hits them all. Their quartermaster is Sallow Kett (see Shops of the Brass Road).","- **What to do:** help them earth the carts with chains into wet ground before the storm (a DC 13 Arcana check, or tinker's or smith's tools, or three DC 12 Strength checks in a row), or shelter with them under the rocks.","- **Reward:** the carters pay 50 gp and let the party buy from Kett's cart at a tenth off. If a cart is hit, it's a terrible noise, and everyone has seen it.","","### 3. The salvage riders","> **SAY:** \"Four riders come over the grass at a canter, with axes on their saddles and horns on their helmets, and they rein in in a circle round you. The leader leans down from her saddle. 'That's a lot of iron,' she says. 'You don't need all of it.'\"","- **What's going on:** Ironhorn salvagers, led by Hask Torvi (if you ran *Four riders* in Session 16A, these are the same four, and they remember the party), who take metal from travellers to melt in the Heart-Hall. They're not killers. They're hungry for iron, and they respect nerve.","- **What to do:** fight (four Ironhorn Riders, using the Warrior Veteran, a Low encounter for four level 7 characters; they stop when two are down), give them something metal they'd value (a weapon or armor worth 25 gp or more), or win it off them: a challenge (an arm-wrestle, a horse race, a drinking match) at DC 15. They respect a good loser almost as much.","- **Reward:** a win or a fair gift makes Hask a friend: she rides to the Thane's camp ahead of them and tells him they're worth meeting (Advantage on the first check of the steppe contest, Session 17A). A fight won gets their horses and 60 gp in hack-silver, and the Ironhorn hear about it.","","### 4. The sleeping village","> **SAY:** \"The village is quiet. Smoke from the chimneys, a cart in the lane, chickens in the road, and nobody moving. Through a window, you see a family at their table, asleep in their chairs, smiling.\"","- **What's going on:** it's near the Tor. The Hush has reached out a little further than it used to, and the village fell asleep at supper two days ago. They're dreaming the same dream: a room full of beds.","- **What to do:** wake one (anything loud works for a minute; a *Lesser Restoration* wakes one person for good). The child Tam wakes first and is very cross.","- **Reward:** Tam says what everyone in the village was dreaming, which is the Sleeping Hall, exactly. Anyone who listens has Advantage on the first check to find their way inside, Session 16B. If the party wakes everyone, the village will take them in for as long as they need.","","### 5. A wayshrine","> **SAY:** \"A wayshrine of bronze, green with age, stands beside the road with a little bell in its roof. The bell is humming. In the dish beneath it, something's been left.\"","- Roll on Wayshrines in Random magic and wonders.","","### 6. Gammer Tansy","> **SAY:** \"On a mountain road a long way from anywhere, there's the mule, and the pots, and the old woman with her pipe. 'You look older,' she says. 'Buying or selling?'\"","- See Gammer Tansy in Random magic and wonders. By now she has a few things she didn't have before.","","### 7. The dead courier","> **SAY:** \"A horse grazes by the road with an empty saddle. Fifty feet away, in the grass, lies its rider, in Court grey, an arrow in his back and a satchel still under his arm.\"","- **What's going on:** a Court courier killed by somebody who didn't know what he was carrying. Two days dead.","- **What to do:** search him. Investigation DC 13 on the arrow: it's Hush Cult fletching. Medicine DC 12: he was running, not fighting.","- **Reward:** the satchel holds orders for the Court's strike force: its route, its numbers, its date (useful in Session 19A). His purse holds 30 gp, his horse is a Court warhorse (worth 400 gp; branded).","","### 8. The giant's cairn","> **SAY:** \"At the top of the pass stands a cairn as tall as a house, built of stones no human could lift. A door of bronze is set into its side, green and shut, and above it a face is carved, with its mouth open.\"","- **What's going on:** a storm giant's grave from before the Concord. The door is a puzzle: The echo door, in Puzzles.","- **What to do:** solve the door, or break it (a DC 22 Strength check, or 60 damage to AC 19 bronze). Breaking it brings the thunder: everyone within 60 feet makes a DC 15 Constitution saving throw or takes 3d8 Thunder damage and is Deafened for an hour.","- **Reward:** the giant's grave goods: 200 gp in ancient bronze rings (collectors in Brassfall pay double), a drinking horn as big as a man, and two rolls on the Random magic table. On the giant's chest, a carved stone plate that shows Thrane, ringing.","","### 9. The dreamer at the well","> **SAY:** \"An old man sits by a well at the roadside with a bucket beside him and a cup in his hand. 'You'll want water,' he says. 'And I'll want a story. I dreamed one last night that I can't finish. Perhaps you know the end.'\"","- **What's going on:** Hob Ellery dreams other people's memories, the ones that were tithed, as if they float up from somewhere. Last night he dreamed one of the party's.","- **What to do:** ask him to tell it. Ask the player what memory it was: something they gave up, or lost, or never told the table. Tell it back to them in Hob's words. They can finish it for him.","- **Reward:** water and a night's rest by the well. The character gains Heroic Inspiration, and the player gets a scene about their character that nobody else could have planned.","","### 10. The deserters","> **SAY:** \"Ten soldiers in Court grey are sitting round a fire that's mostly smoke. Their banner is wrapped round a stick, and one of them is cooking a crow. When they see you, the sergeant gets up slowly and puts his hand on his sword.\"","- **What's going on:** Court soldiers who've had enough. Their warden, Corran Holloway, wants to get his people home, and he'll fight if he thinks the party are sent to bring them back.","- **What to do:** talk (Influence DC 13; show them food or the party's own trouble with the Court, and it's DC 10), fight (*The deserters* in the Combat tab), or slip by (DC 14 group Stealth check).","- **Reward:** fed and pointed home, they give up everything they won't need: 50 gp, two Potions of Greater Healing, and the Court's camp passwords for the month. In Session 22, if the party need people, Holloway brings six of them back.","","### 11. The horse-fair","> **SAY:** \"There's a town of tents in the grass, and a thousand horses, and a noise like a storm: hooves, shouting, bells, somebody singing in a language you don't know. An Ironhorn horse-fair, and everyone is welcome who doesn't steal.\"","- **What's going on:** an Ironhorn fair, where horses, iron and gossip change hands.","- **What to do:** buy horses (see Shops of the Brass Road), enter the race (a DC 15 Wisdom (Animal Handling) or Dexterity (Acrobatics) check, three in a row, against the best rider of the fair), or listen (Persuasion DC 12: news of the Thane, of the Court, and of the Cult).","- **Reward:** the race's prize is a warhorse (worth 400 gp) and the right to sit at the Thane's table. Losing gets cheered almost as loudly.","","### 12. The weather","> **SAY:** \"The sky changes. You'd swear it was listening.\"","- **What's going on:** the weather follows the bells. Say what's true in your campaign:","  - If Thrane has rung: a proper rain, the first in a hundred years. Children are dancing in it.","  - If Thrane hasn't: dry thunder, and lightning that crawls along the ground.","  - If Mirel has rung: people stop on the road, smiling, as if they've remembered something nice.","  - If neither: a grey stillness, and everyone talking quietly.","- **Reward:** none, except that the players see what they've done."],"Location"],
 ["v7-term-wonders","RANDOM MAGIC AND WONDERS","random magic item, random magic, magic item table, wonders, wayshrine, wayshrines, Gammer Tansy, Patience, peddler, oddities, trinkets",["**Random magic and wonders (7.22): what turns up in a dish, a wreck, a pawnshop box or a dead man's satchel.** Use it whenever a page says \"one roll on the Random magic table\", or whenever the party searches somewhere that deserves a surprise.","","**Random magic (d20).** Every result has a \"where it came from\" line; read it out, and the item has a past.","1. **Potion of Healing,** in a little stoppered bottle with a Dawn Mission sun pressed into the wax.","2. **Spell Scroll** (level 1) of your choice, rolled round a candle stub and tied with a hair-ribbon.","3. **Potion of Climbing,** brown and gritty. The label says *For the Spire roof. Don't look down.*","4. **Moon-Touched Sword,** a plain shortsword that sheds moonlight in the dark. The hilt is wrapped in a woman's scarf.","5. **Clockwork Amulet,** ticking quietly, engraved *O.F.* (Osgood Fennick's work; he'll be delighted to see it again).","6. **Cloak of Many Fashions,** grey until somebody wishes it were otherwise.","7. **Orb of Direction,** a glass marble with a needle of light that always points north. It was a sailor's.","8. **Horn of Silent Alarm,** a ram's horn with a Hushman's number burned into it.","9. **Candle of the Deep,** fat and green, smelling of the sea. It burns under water.","10. **Pole of Collapsing,** a walking stick that folds down to a foot long, with a fisherman's initials.","11. **Rope of Mending,** 50 feet of hemp that knits itself back together. Somebody has tied a bell to one end.","12. **Tankard of Sobriety,** pewter, dented, with *NOT TONIGHT* scratched on the bottom.","13. **Mystery Key,** brass, warm, on a string. It opens one lock, once, and nobody knows which.","14. **Talking Doll,** a rag doll that says six things in a child's voice. You choose them; one should be heartbreaking.","15. **Bead of Nourishment,** in a twist of paper, with a note: *For the road north.*","16. **Potion of Water Breathing,** green, with a tiny fish drawn on the label.","17. **Potion of Resistance,** of whichever damage the party will need next; its color says which.","18. **Potion of Greater Healing,** in a heavy blue bottle, very old and still good.","19. **Driftglobe,** a glass ball that glows when its word is spoken. The word is scratched on it, very small, in Old Pellmoor.","20. **Something wonderful (d6):** 1 Immovable Rod; 2 Sending Stones (the other is somewhere you'll want to go); 3 Goggles of Night; 4 Wand of Secrets; 5 Gloves of Swimming and Climbing; 6 Sentinel Shield. At most one of these an act; after that, roll again.","","**Wayshrines.** Little bell-shrines older than the Ninefold Church stand at crossroads and fords all over Corvane, from the days when each of the seven bells had its own wayside saint. Folk still leave things in them: what you leave, the next traveler takes. Leave something and take something; that's the whole rule.","- **What's in the dish (d8):**","  1. A clay cup of good wine, still full. Drink it, and gain Heroic Inspiration.","  2. A child's drawing of a bell, very carefully colored, and 3 gp.","  3. One roll on the Random magic table, wrapped in a handkerchief.","  4. A letter addressed *To whoever needs this*. It's a kind letter. Whoever reads it gains 1d6 Temporary Hit Points each morning for a week.","  5. A heartkeep, and a note: *I don't want it. Maybe you do.* The memory is sweet and not the reader's.","  6. A silver bell-charm worth 10 gp. Worn, it rings when someone lies to the wearer. Once.","  7. Nothing, but somebody has written on the shrine: *Sorry. Back soon.* in a hand one of the party knows.","  8. A Potion of Healing and a sprig of rosemary.","- **Leave something you'll miss** (a keepsake, a letter, a weapon you love), and the character who left it gains Heroic Inspiration. Once per act, per character. What they left turns up later, in somebody else's hands, when it matters.","- **Rob a shrine without leaving anything** and nothing happens, except that the next shrine they come to is empty.","","**Gammer Tansy and her mule, Patience.** A tiny old woman with a clay pipe and a mule under a load of pots, birdcages, lanterns, a mirror and a rocking horse. She turns up on every road in Corvane, often before the party gets there, and she won't say how. She buys anything, sells anything, and talks to Patience as an equal.","- **She says:** \"Buying or selling?\" / \"Patience doesn't like you. That's a compliment; she doesn't like anybody.\" / \"I've walked further than that for less.\"","- **She sells** ordinary gear at the usual price, but only what's on the mule, and always one thing they'll need in the next session (a rope, a warm coat, a crowbar). She buys anything at half its price, and keeps at their value.","- **What else is on the mule (d20).** Each costs 1d10 gp, or a good trade.","  1. A brass spyglass that shows tomorrow's weather.","  2. A jar of fireflies that never die.","  3. A boot with a mouse living in it. The mouse is very well mannered.","  4. A map of a town that doesn't exist. Yet.","  5. A tin soldier with a Hushman's face.","  6. A handbell that rings a note that makes dogs sit.","  7. Seven keys on a ring, all the same.","  8. A pipe that blows smoke in the shape of whatever the smoker is thinking about.","  9. A glass eye that blinks.","  10. A book of blank pages that are always warm.","  11. A music box that plays a song nobody at the table has heard, and everyone can hum afterwards.","  12. A tiny portrait of one of the party, painted years ago.","  13. A walking stick with a compass in the knob.","  14. A Potion of Healing, a little cloudy. It works.","  15. A pair of red shoes that are a size too big for everybody.","  16. A stoppered bottle of sea-fog.","  17. A deck of cards with one card missing: the one they draw.","  18. A wooden bird that sings at dawn.","  19. A bottled memory of a perfect summer's day. Nobody's; she made it, she says.","  20. One roll on the Random magic table. \"Oh, that. I'd forgotten I had that.\"","- **One true thing.** Every time they meet her, she tells them one rumor about the next place they're going, and it's always true.","- **The bell on Patience's collar.** Ask about it, and she says, \"Spoken for.\" At the last meeting of the campaign she unhooks it and gives it to whoever has been kindest to Patience. It isn't magic. It rings a note nobody can name, and whoever carries it gains Heroic Inspiration at the start of the last session.","","**Places of wonder (d10).** For a long road, a lost party, or a session that needs one strange good thing. Most hold a find.","1. **The drowned belfry.** A church tower stands up out of a lake, its bell still hanging. Swim out and ring it, and every fish in the lake comes to the surface to listen. Under the bell, on a ledge: one roll on the Random magic table.","2. **The tree of keys.** An oak hung with hundreds of keys on ribbons, left by people who'd lost a home. One key is still warm (a Mystery Key).","3. **The giant's chair.** A stone throne a hundred feet tall on a hilltop. Climb it (DC 13 Athletics), and from the seat they can see two days of road in every direction: Advantage on Survival checks to navigate for the rest of the journey.","4. **The upside-down waterfall.** A stream falls up a cliff into the clouds. A coin thrown in comes back down an hour later as a different coin, from a country nobody knows (worth 10 gp to a collector).","5. **The ghost market.** On the first night of the new moon, a market of lantern-lit stalls appears in a ruined square, kept by smiling, silent people from three hundred years ago. They take old coin and memories, and they sell one roll on the Random magic table for a memory of a meal. At dawn it's gone, and so is anything they didn't pay for.","6. **The library in the hill.** A door in a grassy mound opens on a dry room of shelves: a bell-keeper's library, sealed before the Concord. One book is a Spell Scroll (level 2) of your choice, and one is a history that gives Advantage on a History check about the bells.","7. **The statue that moved.** A stone knight by the road, pointing. Every time they pass, it's pointing somewhere else. Follow where it points, and in a mile there's a cairn, and in the cairn 3d10 gp and a Potion of Healing.","8. **The singing stones.** A ring of standing stones that hum when the wind blows. Stand in the middle and sing, and they sing it back in harmony. A bard who does it learns a song that grants Heroic Inspiration to one listener, once.","9. **The wreck in the trees.** A ship, a whole ship, wedged in the branches of a forest, forty feet up, a hundred miles from the sea. In the captain's cabin: a log that ends mid-sentence, 2d10 gp, and one roll on the Random magic table.","10. **The well that answers.** Drop a coin in and ask a question; the well answers yes or no, in your own voice, and it's right. It takes one coin a question, and three questions a lifetime."],"Lore"],
 ["v7-term-puzzles","PUZZLES","puzzle, puzzles, riddle, riddles, puzzle door, puzzle lock, hint ladder",["**Puzzles (7.22): how to run them, and six to drop in anywhere.** The side dungeons each have one puzzle of their own now (marked 7.22 on their pages). These six are for a door, a vault or a tomb you want to make memorable.","","**How to run a puzzle.**","- **Never block the main road.** A puzzle guards a treasure, a shortcut or a secret, never the only way on.","- **Give the clue freely.** Anyone who looks at the room sees the clue without a roll. The roll is for understanding it, not finding it.","- **The hint ladder.** Stuck for five minutes of real time? A character with a good Intelligence, Wisdom or a matching skill makes a DC 12 check and you give a nudge. Stuck for ten? Give the answer through the world: a ghost, a carved line, an NPC, a Talking Doll. No puzzle should take more than fifteen minutes.","- **Brute force always works, at a cost:** a noise, a hurt, a lost treasure, an alarm. Say what the cost is before they try.","- **Reward the solve.** A clever answer gets Heroic Inspiration for whoever said it, and the best treasure in the room.","","### 1. The seven-bells door","> **SAY:** \"A round bronze door, and set into it seven small bells in a ring, each with a different mark: a sun, an eye, a snowflake, a sheaf of wheat, a lightning bolt, a crescent moon, and one with no mark at all. Above them, a line is carved: SIX TO WAKE THE WORLD, AND ONE TO LET IT SLEEP.\"","- **The answer:** ring the six in the order of the Concord (Vaer the Dawn, Ossa the Memory, Hieme the Winter, Calla the Harvest, Thrane the Storms, Mirel the Dreams), and leave the seventh, Ysh, silent.","- **Clues:** the order is in the Concord hymn, which any cleric, bard, or anybody raised in Corvane knows (Religion DC 10). Ringing the unmarked bell makes every other bell go quiet: the door is resetting.","- **Brute force:** the door is AC 19 with 50 Hit Points, or a DC 20 Strength check. Every blow rings all seven at once: everyone within 30 feet makes a DC 13 Constitution saving throw or is Deafened for an hour.","- **Reward:** behind it, a bell-keeper's cell: 4d10 gp in old coin and one roll on the Random magic table. Whoever rang the last bell gains Heroic Inspiration.","","### 2. The two heads","> **SAY:** \"Two stone heads are set into the wall between two doors, one smiling, one frowning. 'One of us always tells the truth,' says the smiling head. 'And one of us always lies,' says the frowning one. 'One door goes on. One door goes down. Ask one of us one question.'\"","- **The answer:** ask either head, \"Which door would the other head say goes on?\" and take the other door. (Both heads point at the wrong door.)","- **Clues:** the heads bicker. Get them talking (they're bored; Persuasion DC 10) and each says something about the other that the players can check.","- **Brute force:** pick a door and open it. The wrong one is a 20-foot drop into water (2d6 Bludgeoning damage, DC 13 Dexterity saving throw for half), and the heads laugh for a full minute.","- **Reward:** the right door leads on. Under the smiling head's chin, a coin-slot holds what the last visitors paid: 2d10 gp and a Potion of Healing.","","### 3. The weighing scales","> **SAY:** \"A pair of great bronze scales stand on a dais. In one pan, a heavy stone. The other pan is empty, and on its rim are the words: WHAT WEIGHS MORE THAN GOLD?\"","- **The answer:** a memory. Somebody stands in the empty pan and tells a true happy memory aloud, to the whole table, and the pan sinks.","- **Clues:** gold, weapons and stones don't move it. Lies don't either: the pan rises a little, as if amused (Insight DC 10 notices).","- **Brute force:** pull the pan down by hand (a DC 18 Strength check), and the scales take a memory anyway. The player chooses something their character forgets, and writes it in the Memory ledger.","- **Reward:** the stone pan rises and opens. In it: a heartkeep worth 50 gp, and one roll on the Random magic table. The player who told the memory gains Heroic Inspiration.","","### 4. The sun-floor","> **SAY:** \"The floor is a great bronze sundial, its hours marked in a ring of tiles. In the middle stands the pointer. Hanging from the ceiling on a chain is an iron lantern, cold. Over the far door is carved: OPEN AT THE HOUR OF THE DAWN BELL.\"","- **The answer:** light the lantern and swing it on its chain until the pointer's shadow falls on the sixth hour (the dawn bell rings at six). Hold it there, and the door opens.","- **Clues:** the lantern chain can be hooked at different points along a rail on the ceiling (Investigation DC 10). The tile of the sixth hour is worn by old feet.","- **Brute force:** pry the door with a crowbar (DC 15 Strength). The floor tilts, and everyone on it makes a DC 12 Dexterity saving throw or slides into the pit in the middle: 10 feet, 1d6 Bludgeoning damage.","- **Reward:** behind the door, an old vestry: two Potions of Healing, a Spell Scroll (level 1) of your choice, and a bronze sun worth 25 gp.","","### 5. The echo door","> **SAY:** \"A face is carved over the door, its mouth wide open. When you speak, it says your words back to you, a moment later, from somewhere deep inside the stone. Carved under its chin: SPEAK MY NAME AND I WILL ANSWER. NOBODY HAS EVER SEEN ME. YOU HAVE HEARD ME ALL YOUR LIFE.\"","- **The answer:** \"Echo.\" Say it, and the face says it back, louder each time, until the door opens.","- **Clues:** the face repeats everything except questions. Asked one, it's silent. (It's an echo; it can only give back.)","- **Brute force:** break it (scale the door to the place: at the giant's cairn on the Brass Road it's a DC 22 Strength check). Breaking it lets the stored sound out: everyone within 60 feet makes a Constitution saving throw (DC 13, or DC 15 above level 6), taking 3d8 Thunder damage and Deafened for an hour on a failure.","- **Reward:** whatever the place holds. Whoever said \"Echo\" gains Heroic Inspiration.","","### 6. The three caskets","> **SAY:** \"Three caskets on a table: gold, silver and lead. On each lid, a line. Gold: THE KEY IS IN THIS CASKET. Silver: THE KEY IS NOT IN THIS CASKET. Lead: THE KEY IS NOT IN THE GOLD CASKET. Under them, on the table: ONLY ONE OF US TELLS THE TRUTH.\"","- **The answer:** silver. (If the key were in gold, gold and silver would both be true. If it were in lead, silver and lead would both be true. Only with the key in silver is exactly one line true: lead's.)","- **Clues:** let them reason it out. A DC 13 Intelligence check gives the first step: \"If the key were in the gold casket, what else would be true?\"","- **Brute force:** open the wrong casket, or smash them. Each wrong casket puffs sleeping dust: DC 13 Constitution saving throw or Unconscious for 1 minute (another creature can wake them with an action). Smashing the silver casket breaks the key's glass vial, and whatever it opens stays locked unless they break that too.","- **Reward:** the key opens whatever you like: a strongbox, a cell, a secret door. In the silver casket with it: a Potion of Greater Healing, wrapped in velvet."],"Lore"],
 ["v7-place-shops-pellmoor","SHOPS OF PELLMOOR","shop, shops, shopkeeper, shopkeepers, merchant, trader, buy, sell, haggle, Pellmoor shops",["**Shops of Pellmoor (7.22): Strangers' Row, the Quays and the Old Shore.** Everyone in Pellmoor who'll trade with the party, what they have, and what they might have today. Uncommon items can also be ordered through the Vennmark Coster or Smiling Dace, and take a week.","","**How shops work (7.22).**","- **Prices** are the 2024 rules prices. Common magic items cost 100 gp and uncommon ones 400 gp; potions and scrolls cost half that. Rare items are never for sale: they're found.","- **Something special.** Each time the party visits a trader, roll a d6. On a 1 to 4, it's the usual stock. On a 5, the trader has their **good find**. On a 6, they have **something that shouldn't be here**. Once a special item is sold, it's gone.","- **Selling.** Traders buy ordinary gear at half its price, if they want it at all. Magic items sell for half their price, and only to the traders who say they buy them.","- **Keeps.** Traders who take keeps (heartkeeps) value one at 25 to 100 gp, depending on the memory. The player chooses which memory, and writes it in the Memory ledger.","- **Haggling.** Persuasion DC 15 takes a tenth off; DC 20 takes a fifth. Fail by 5 or more and the price goes up a tenth, and that trader won't haggle again this visit. Some traders say what works better than Persuasion.","","### Bruna Hardshale, the smithy on Strangers' Row","> **SAY:** \"Heat, and a hammer going like a heartbeat. The smith is a dwarf with arms like hawsers and her beard tied up out of the sparks. She looks at your weapons before she looks at your faces.\"","- **Says:** \"Gold or keeps, I don't care which. Bronze, I care about.\" / \"Who sharpened this? Never let them near it again.\"","- **Stock:** longsword 15 gp, shortsword 10 gp, rapier 25 gp, battleaxe 10 gp, warhammer 15 gp, handaxe 5 gp, spear 1 gp, crossbow bolts (20) 1 gp, chain shirt 50 gp, scale mail 50 gp, chain mail 75 gp, shield 10 gp. Breastplate (400 gp) and half plate (750 gp) to order, in a week. Repairs for nothing if she likes you. Silvering a weapon or ten bolts: 100 gp, a day.","- **Good find (5):** a **Moon-Touched Sword** (common, 100 gp), a longsword she made \"for practice\".","- **Shouldn't be here (6):** a **Mithral Chain Shirt** (uncommon, 400 gp), from Mirabar. A cousin owed her; she'll sell it only to someone she thinks will get it scratched properly.","- **Buys:** any bronze at twice its weight in silver, and good weapons at half price. She doesn't buy magic. \"Not my trade.\"","- **Haggling:** she doesn't. Bring her bronze, or a story about a fight that's actually true (Insight DC 10 says she can tell), and she takes a fifth off.","","### Ulm Teasel, chandler","> **SAY:** \"A shop like the inside of a ship's hold: rope in coils to the ceiling, lanterns hanging like fruit, barrels, sacks, nets. The chandler is a small, sad man with very clean hands.\"","- **Says:** \"Everything for the road, and nothing for the heart.\" / \"You'll want more rope than that. Everyone always wants more rope than that.\"","- **Stock:** rope (50 feet) 1 gp, hooded lantern 5 gp, oil 1 sp a flask, rations 5 sp a day, tent 2 gp, bedroll 1 gp, blanket 5 sp, climber's kit 25 gp, healer's kit 5 gp, crowbar 2 gp, grappling hook 2 gp, chain (10 feet) 5 gp, caltrops 1 gp, ball bearings 1 gp, waterskin 2 sp, shovel 2 gp, manacles 2 gp, torches 1 cp each, candles 1 cp each.","- **Good find (5):** a **Candle of the Deep** (common, 50 gp), \"for divers\".","- **Shouldn't be here (6):** a coil of **Rope of Climbing** (uncommon) on the shelf with the rest, priced as rope, 1 gp. Ulm doesn't know. *Detect Magic*, or Arcana DC 15 from anyone who handles it, notices it's knotting itself. If they tell him, he looks at it a long time and then says, \"Still 1 gp. Honesty's worth something.\"","- **Buys:** ordinary gear at half price. No magic, no keeps.","","### Pim Coyle, the Quays chandlery","> **SAY:** \"A bow-fronted shop on the Quays, hung with oilskins and fishing gear. The man behind the counter is all smile and no eyes.\"","- **Says:** \"Boat hire by the day. No questions by the hour.\" / \"Whatever you heard about the cellar, you heard it from somebody else.\"","- **Stock:** oilskin coat 5 gp, net 1 gp, fishing gear 1 gp, pitch, sailcloth, hooded lantern 5 gp, rope 1 gp, rowboat hire 2 gp a day (or 50 gp to buy).","- **Good find (5):** a **Potion of Water Breathing** (uncommon, 200 gp). \"Off a diver. He won't need it.\"","- **Shouldn't be here (6):** a set of **Mariner's Armor** (uncommon, scale mail, 400 gp), taken off a drowned man and sold as a curiosity.","- **Buys:** anything off a boat. If the Undertow are still in business below him, he buys stolen bottles too, at 3 gp each.","","### Smiling Dace, the fence on Strangers' Row","> **SAY:** \"A back room behind a pawn-shop, warm and smelling of oranges. A thin man in a very good coat smiles at you, and keeps smiling, all the time you're there.\"","- **Says:** \"I don't know you. That's the arrangement.\" / \"Everything has a price. I'm just the one who knows it.\"","- **Stock:** thieves' tools 25 gp, disguise kit 25 gp, forgery kit 15 gp, poisoner's kit 50 gp, a vial of basic poison 100 gp. Uncommon magic to order: 400 gp plus a tenth, a week, no questions.","- **Good find (5):** a **Potion of Climbing** (common, 50 gp), \"for windows\".","- **Shouldn't be here (6):** **Dust of Disappearance** (uncommon, 200 gp), in a twist of paper. He doesn't say where it came from, and if they ask, his smile gets a little wider.","- **Buys:** anything stolen, at a third of its price; magic at half; keeps at full value. He's the Zhentarim's man, and the Zhentarim write everything down.","- **Haggling:** never with Persuasion. A secret he can sell takes a fifth off.","","### The Vennmark Coster: Tesra Velarion and Ilario Brask","> **SAY:** \"A counting-house on the Quays with glass in its windows and a guard at its door. Inside, two clerks in Amnian plum, one older and very calm, one young and very eager, sit at desks under a portrait of Master Venn.\"","- **Says (Tesra):** \"The Coster buys what Corvane has. Corvane has memories.\" / **(Ilario):** \"And we sell everything else! Have you tried the perfume?\"","- **Stock:** Amnian wine 10 gp a bottle, perfume 5 gp, fine clothes 15 gp, spices, silk, glass. Magic to order from Amn: any uncommon item, 400 gp, a week.","- **Good find (5):** **Perfume of Bewitching** (common, 50 gp), in a plum bottle.","- **Shouldn't be here (6):** a **Lantern of Revealing** (uncommon, 400 gp). \"From an estate. The family thought it was haunted.\"","- **Buys:** keeps at full value, always, and they don't ask whose. Magic at half price.","- **Remember:** buying from the Coster feeds Venn's trade, and Venn is watching who buys.","","### The Corvane Venture: Aubric Delamere and Marigold Teague","> **SAY:** \"A Waterdhavian trading-house in a borrowed hall. Bolts of cloth on trestles, a map of the Sword Coast on the wall, and two merchants who look as if they've been in Pellmoor for a week and would like to leave tomorrow.\"","- **Says (Aubric):** \"We're here for the long road, not the quick coin.\" / **(Marigold):** \"You'll want wool for the north. Real wool. Not that Corvanese stuff.\"","- **Stock:** fine clothes 15 gp, traveler's clothes 2 gp, costume 5 gp, a fur-lined cloak 10 gp (worth it for Act III), boots, gloves, maps of the Sword Coast 1 gp. Letters of credit, honored in Hallowmere.","- **Good find (5):** a **Cloak of Many Fashions** (common, 100 gp). Marigold wears it to the counter.","- **Shouldn't be here (6):** a **Cloak of Elvenkind** (uncommon, 400 gp), bought from a half-elf who needed passage home.","- **Buys:** Corvanese cloth, carvings and old coin (half again its value). No keeps: \"We're from Waterdeep. We like our memories where they are.\"","","### Osgood Fennick, clockmaker","> **SAY:** \"A shop full of ticking. Clocks on the walls, clocks on the floor, clocks in pieces on every surface. A gnome with three pairs of spectacles pushed up his forehead doesn't look up. 'One moment. One moment. There.'\"","- **Says:** \"Everything works if you love it enough and take it apart often.\" / \"Venn's clocks don't tick, you know. I made them that way. He asked.\"","- **Stock:** tinker's tools 50 gp, a pocket clock 25 gp, locks 10 gp, clockwork toys 5 gp, lock and clock repairs. Magnifying glass 100 gp.","- **Good find (5):** an **Orb of Time** (common, 100 gp), a brass ball that tells the time of day when you ask it.","- **Shouldn't be here (6):** a **Decanter of Endless Water** (uncommon) in pieces on his bench. He took it apart to see how it works and can't put it back together. Help him (Arcana or tinker's tools DC 13) and he sells it for 300 gp, or gives it to them for a week's work.","- **Buys:** clockwork of any kind, and Clockwork Amulets at full price (\"Mine. I made those.\").","","### Sister Aurelie Dawnmantle, the Dawn Mission","> **SAY:** \"A whitewashed hall with a sun painted over the door, cots along the walls, and the smell of soap and barley soup. A priestess in white with her sleeves rolled up nods to a cot without asking what you need.\"","- **Says:** \"Sit. You can tell me after.\" / \"We don't charge. We do accept.\"","- **Stock:** Potions of Healing (50 gp; she has 1d4 a week), healer's kit 5 gp, holy water 25 gp, antitoxin 50 gp. Spells cast for a donation: a cantrip 30 gp, a level 1 spell 50 gp, *Lesser Restoration* 200 gp, *Remove Curse* or *Revivify* 300 gp (plus the diamond).","- **Good find (5):** a **Potion of Healing** for nothing, pressed into the hand of whoever's worst hurt.","- **Shouldn't be here (6):** a **Periapt of Wound Closure** (uncommon). It isn't for sale. It belonged to a knight who died in her care, and she gives it to whichever of them has done the Mission a kindness.","- **Buys:** nothing. Gifts of food or coin to the Mission, of 25 gp or more, earn a bed for life.","","### Dorra Pell, the Shuttered Bell","> **SAY:** \"A low inn with shutters painted the blue of old bells. The landlady has a bun of iron-grey hair and an apron she's never once taken off in front of a customer.\"","- **Says:** \"Rooms are upstairs. Rumors are extra.\" / \"Writs have a way of arriving for interesting people.\"","- **Stock:** a modest room 5 sp a night, a comfortable one 8 sp, a meal 3 sp, ale 4 cp, wine 2 sp a jug, stabling 5 sp a night. Packed rations 5 sp a day.","- **Good find (5):** **Heward's Handy Spice Pouch** (common, 100 gp), left by a cook who went to sea.","- **Shouldn't be here (6):** a **Bag of Tricks** (grey, uncommon, 400 gp), left by a lodger who never came back for it. She'd take it off the bill.","- **Buys:** news. A good rumor pays for a night's room.","","### The Old Shore: Mother Sallow and the ferry-folk","> **SAY:** \"Net-racks, smoke-houses and boats drawn up on the shingle. Nobody here sells anything, exactly. But everybody trades.\"","- **Trades:** smoked fish for a week's rations (1 gp of anything), boat passage anywhere on the Mere (a favor, or 1 gp), net-mending, oilskins (5 gp, or a good knife).","- **Good find (5):** a **Potion of Water Breathing** (uncommon), traded for a real kindness to the ferry-folk.","- **Shouldn't be here (6):** a **Driftglobe** (uncommon) found in a net. Mother Sallow's grandson thinks it's a fish egg. He'll trade it for something that makes him laugh.","- **Doesn't trade in:** keeps. Offer one and the whole beach goes quiet."],"Location"],
 ["v7-place-shops-hallowmere","SHOPS OF HALLOWMERE","Hallowmere shops, Grey City shops, Tithe market, Grael and Sons, Pale Ledger",["**Shops of Hallowmere (7.22): the Grey City's licensed shops, and the ones that aren't.** In Hallowmere every trader needs a Court licence. Most have one. See Shops of Pellmoor for how shops work (the d6 special roll, selling, keeps and haggling).","","### Oswin Crake, the Pale Ledger (pawnbroker)","> **SAY:** \"A pawnshop on a canal corner, its window so crowded you can't see in: lutes, swords, wedding dresses, spectacles, a stuffed owl. A pale man with ink on his cuffs writes something in a ledger before he says hello.\"","- **Says:** \"Everything here belonged to somebody once. Now it belongs to the Ledger.\" / \"I don't ask. I write it down.\"","- **Stock:** a little of everything at the usual price: weapons, instruments (lute 35 gp, flute 2 gp), tools, clothes, books. Roll a d6 for an odd item on every visit, too.","- **Good find (5):** a **Mystery Key** (common, 100 gp), pawned by a woman who said it \"opens the door I'm not brave enough for\".","- **Shouldn't be here (6):** a **Stone of Good Luck** (uncommon, 400 gp), pawned by a gambler who never came back.","- **Buys:** anything at a third of its price, magic at half, keeps at half value, and he writes your name in the Ledger. The Court reads it every week.","","### Widow Hesp, apothecary","> **SAY:** \"A green shop down three steps, hung with herbs, dark and cool. An old woman with a mortar in her lap says, 'Mind the cat,' and there isn't a cat.\"","- **Says:** \"Bring me willow bark and I'll bring you back from the dead. Nearly.\" / \"Remembering tea? One copper. Works one time in six. That's better than the Tithe.\"","- **Stock:** Potions of Healing (she brews them, 50 gp; 1d6 on the shelf), antitoxin 50 gp, healer's kit 5 gp, herbalism kit 5 gp, alchemist's fire 50 gp, acid 25 gp. *Remembering tea* (1 cp): a Blank who drinks it remembers their own name, on a 6 on a d6.","- **Good find (5):** a **Potion of Resistance** (uncommon, 200 gp), against whatever the next danger is.","- **Shouldn't be here (6):** **Oil of Slipperiness** (uncommon, 200 gp). She made it by mistake.","- **Buys:** herbs, roots, rare plants, monster parts (a Glass-Wolf's eye is worth 25 gp to her). Not keeps: \"Poor things.\"","- **Haggling:** Medicine DC 13 instead of Persuasion, if they talk herbs with her.","","### Grael and Sons, Court armourers","> **SAY:** \"A grand shop on the Hall of Tithes square, with a Court licence framed beside the door and two Hushmen leaning in the doorway. Inside, three identical brothers in leather aprons look up together.\"","- **Says:** \"Licence?\" / \"No licence, no blades. That's the law.\" / (Quietly) \"...But the law's expensive to keep, isn't it?\"","- **Stock:** every weapon and armor in the rules, at a tenth above the usual price: half plate 825 gp, breastplate 440 gp, plate 1,650 gp to order (two weeks), longsword 17 gp, longbow 55 gp. To buy a weapon or armor, you need a Court licence, or a bribe of 20 gp to the youngest brother (Influence DC 12 to find out which one).","- **Good find (5):** **Armor of Gleaming** (common, 100 gp plus the armor), a breastplate that never needs polishing.","- **Shouldn't be here (6):** an **Adamantine Breastplate** (uncommon, 400 gp plus the armor), made for a Court captain who died before he collected it.","- **Buys:** good weapons at half price, and asks where they came from.","","### Absalom Dray, bookseller on Vellum Lane","> **SAY:** \"A shop so full of books you have to turn sideways to get in. A bent old man with ink-stained sleeves comes out of the stacks, holding a candle well away from everything.\"","- **Says:** \"Licensed books are at the front. History is at the back.\" / \"They burned forty of mine last month. I remembered them. I'm writing them out again.\"","- **Stock:** books 25 gp, maps 1 gp, ink 10 gp, paper 2 sp a sheet, a calligrapher's kit 25 gp. Spell scrolls he copies himself: a cantrip 30 gp, a level 1 spell 50 gp, a level 2 spell 200 gp (one of each a week).","- **Good find (5):** an **Enduring Spellbook** (common, 100 gp).","- **Shouldn't be here (6):** a **Spell Scroll of Remove Curse** (uncommon, 200 gp), from a dead priest's library.","- **Buys:** old books at half price, unlicensed histories for more than they're worth.","- **Note:** after the book-burning (Hallowmere's streets, entry 3), he gives the party a fifth off for life.","","### The Tithe market","> **SAY:** \"In the yard behind the Tithe-house, clerks sell the belongings of the Blanks off trestle tables, by the box. Shoes. Toys. A clock still ticking. A crowd is picking through it quietly, not meeting each other's eyes.\"","- **Stock:** boxes of whatever a Blank was carrying, 5 gp a box, sight unseen. Roll a d6 for each box: on a 6, there's one roll on the Random magic table in it.","- **Something special:** once in Act II, a box with a name inside the lid that one of the party knows.","- **Remember:** the coin goes to the Court. Buying here feels terrible, and it should. Taking a box back to the person it belonged to is worth Heroic Inspiration.","","### The Tithe-house counter","> **SAY:** \"A long counter of black wood with brass grilles, and behind each grille a clerk with a little silver bowl and a pen. Over it: THE COURT IS GRATEFUL.\"","- **Buys:** keeps at full value (25 to 100 gp), and memories straight from the head: a clerk takes one with a touch, and pays 10 to 50 gp. The player chooses the memory, and writes it in the Memory ledger. Every sale is recorded, with a name.","- **Sells:** nothing. Ever."],"Location"],
 ["v7-place-shops-north","SHOPS OF THE NORTH ROAD","North Road shops, Empty Sheaf, Haddy Corn, waystation shop",["**Shops of the North Road (7.22): the waystation, Kell's Crossing and the edge of the glass.** There are fewer shops up here, and they sell what keeps people alive. See Shops of Pellmoor for how shops work (the d6 special roll, selling, keeps and haggling).","","### Orrin Lisk, the waystation","> **SAY:** \"A stone waystation with a turf roof and a stable, the last lit window for twenty miles. The keeper, a big slow man with a shepherd's crook, has a dog on each side of him.\"","- **Says:** \"Pay for the bed, the fire's free.\" / \"Riders came through yesterday. Grey coats. They paid. You don't have to.\"","- **Stock:** a bed 5 sp, a meal 3 sp, stabling 5 sp, rations 5 sp a day, oil, rope, blankets, a riding horse 75 gp (he has one), a mule 8 gp, feed.","- **Good find (5):** a **Bead of Nourishment** (common, 50 gp), \"found in a ditch\".","- **Shouldn't be here (6):** **Boots of Elvenkind** (uncommon, 400 gp), left by a traveler who walked out one night and never came back. Orrin keeps them by the door, in case.","- **Buys:** horses, news, and nothing else. He'd rather have the news.","","### Haddy Corn, the Empty Sheaf","> **SAY:** \"The inn at Kell's Crossing is crowded with people who've run from somewhere. The innkeeper has six children under her feet and one coat on her back, and she still makes room.\"","- **Says:** \"Sit where there's a gap.\" / \"Pay what you can. If you can pay more, pay for somebody who can't.\"","- **Stock:** a bed 5 sp (or a share of the hayloft, free), a meal 3 sp, ale 4 cp, rations, warm cloaks 10 gp (patched, and they matter on the glass).","- **Good find (5):** a **Potion of Healing**, from the Dawn Mission's last cart north.","- **Shouldn't be here (6):** a **Ring of Warmth** (uncommon). Not for sale: a runaway left it as payment. She'll give it to whoever helps the Crossing most.","- **Buys:** food at full price, and seed-corn at twice that.","","### Dob Sallis, carter","> **SAY:** \"A carter with a cart full of everything, and a pony called Radish who's seen it all.\"","- **Says:** \"I go north with goods and south with people. Both pay.\" / \"Radish knows the road better than I do.\"","- **Stock:** cart hire with Dob driving, 2 gp a day; ordinary gear at a quarter above the price; lamp oil, rope, nails, a tent, a saddle.","- **Good find (5):** a **Rope of Mending** (common, 100 gp).","- **Shouldn't be here (6):** **Slippers of Spider Climbing** (uncommon, 400 gp), in a crate marked *Hallowmere, the Chancellor's household*. Dob has no idea, and doesn't want one.","- **Buys:** anything he can sell further down the road, at half price.","","### Finch, the pedlar","> **SAY:** \"A young pedlar with a pack taller than she is, pots clanking. 'Ribbons, needles, news!'\"","- **Stock:** needles, thread, ribbons, soap, a mirror 5 gp, a whistle 2 cp, playing cards 5 sp, a lute string, dried apples.","- **Good find (5):** a **Talking Doll** (common, 100 gp). It says, \"Where's Mama?\", which is creepy.","- **Shouldn't be here (6):** **Sending Stones** (uncommon, 400 gp), one stone. The other is with her brother in Hallowmere. She won't sell it unless they promise to give it to him.","- **Buys:** small things. She trades better than she sells: Persuasion DC 12 to trade an item for one of equal value.","","### Yara's camp, at the edge of the glass","> **SAY:** \"A tent of hides at the edge of the glass, with a fire inside it that's kept going day and night. The woman who keeps it has frost in her eyebrows and a map she won't let you touch.\"","- **Says:** \"Everything for the glass is for sale. The map isn't.\" / \"Gold or a keep. Keeps are lighter.\"","- **Stock:** a warm cloak 10 gp or a keep, glass-cutting tools 5 gp, a bed 5 gp or a keep, crampons 2 gp, snow goggles 1 gp, fuel for a night 5 sp, rations 1 gp a day.","- **Good find (5):** a **Potion of Resistance (Cold)** (uncommon, 200 gp).","- **Shouldn't be here (6):** a **Necklace of Adaptation** (uncommon, 400 gp), taken off a Stilled diver at the edge of the glass. She'll say so.","- **Buys:** keeps, at full value, and Glass-Wolf pelts at 25 gp."],"Location"],
 ["v7-place-shops-brass","SHOPS OF THE BRASS ROAD","Brass Road shops, Dry Thunder, Mother Ash, storm-smith, Tavi Ondrel, horse-traders",["**Shops of the Brass Road (7.22): the Dry Thunder, Brassfall and the steppe.** Acts IV and V. Coin is still good here, but the Ironhorn would rather have metal. See Shops of Pellmoor for how shops work (the d6 special roll, selling, keeps and haggling).","","### Mother Ash, the Dry Thunder","> **SAY:** \"The last tavern before the Shafts. Low, stone, and dark inside, and on every table the cups hum, very faintly, as if there's a song in them.\"","- **Says:** \"Sit. Eat. Don't touch the cups.\" / \"I've heard everything once. Say it slower.\"","- **Stock:** a bed 8 sp, a meal 3 sp, beer 4 cp, rations 5 sp a day, lamp oil, rope, a mule 8 gp.","- **Good find (5):** a **Tankard of Sobriety** (common, 100 gp). \"Somebody needed it more than you.\"","- **Shouldn't be here (6):** a **Potion of Greater Healing** (uncommon, 200 gp), behind the bar. She says it was her husband's, and she doesn't need it now.","- **Buys:** food and news. She knows what the party are. She'll ask who they are.","","### Tavi Ondrel, storm-smith of Brassfall","> **SAY:** \"A forge with copper rods on its roof, and blue fire in the hearth instead of red. A young woman in a leather apron, her hair standing straight up, is hammering something that crackles.\"","- **Says:** \"Storms aren't dangerous. They're just impatient.\" / \"Bring me a storm-stone and I'll make you something that'll make the sky jealous.\"","- **Stock:** bronze weapons and armor at the usual price (they don't rust), lightning rods 5 gp, smith's tools 20 gp, insulated gloves 2 gp.","- **Good find (5):** a **Wand of Conducting** (common, 100 gp), with a spark at its tip.","- **Shouldn't be here (6):** a **Javelin of Lightning** (uncommon, 400 gp), finished, hanging on the wall. Or bring her a storm-stone and 100 gp, and she binds one in a week.","- **Buys:** storm-stones (100 gp), star-iron (150 gp), bronze at its weight in silver.","","### The Ironhorn horse-traders","> **SAY:** \"Corrals of rope on the steppe, and horses everywhere, more than you've ever seen. The traders are tall and loud and very cheerful, and every one of them is wearing more iron than a knight.\"","- **Says:** \"Coin? Coin is flat iron. Show me real metal.\" / \"That horse? That horse is a poem.\"","- **Stock:** a riding horse 75 gp, a warhorse 400 gp, a pony 30 gp, a riding saddle 10 gp, a military saddle 20 gp, a felt tent 5 gp, mare's milk 1 sp a skin.","- **Paying:** they take metal by weight, not coin. A weapon or armor counts for its full price, if it's iron or steel. Coin counts too, but they sniff at it.","- **Good find (5):** a quiver of **Walloping Ammunition** (common, 10 arrows, 50 gp).","- **Shouldn't be here (6):** **Bracers of Archery** (uncommon, 400 gp of metal), won in a race by a rider who can't draw a bow.","- **Haggling:** never with Persuasion. Win a contest (a race, a wrestle or a drinking match, DC 15) and they take a fifth off.","","### Sallow Kett, the bronze carts' quartermaster","> **SAY:** \"A bronze cart parked off the road, and a woman sitting on its tail with a slate and a pencil. 'You've the look of people who need things,' she says. 'Good. I've got things.'\"","- **Says:** \"Everything on this cart's counted twice.\" / \"Storms coming? Then we're not standing next to the bronze.\"","- **Stock:** road stores at a tenth above the usual price: rations, rope, tents, oil, cold-weather gear, waterskins, a cart wheel, oxen 15 gp each. Healer's kits 5 gp. Potions of Healing 50 gp (two).","- **Good find (5):** a **Bead of Refreshment** (common, 50 gp).","- **Shouldn't be here (6):** a **Wind Fan** (uncommon, 400 gp), which the carters use to keep the dust off the oxen, not knowing what it is.","- **Buys:** anything that fits on the cart, at half price. If the party helped earth the carts in a storm (The Brass Road and the steppe, entry 2), she takes a tenth off everything.","","### The Heart-Hall's fires","> **SAY:** \"Round the Heart-Hall forty fires burn, and at every fire someone is mending, smithing, carving or cooking, and all of them will trade.\"","- **Trades:** horn cups, bone-handled knives (5 gp), felt cloaks (5 gp), dried meat, saddlebags. Metal by weight.","- **Good find (5):** a **Horn of Silent Alarm** (common, 100 gp).","- **Shouldn't be here (6):** a **Gem of Brightness** (uncommon, 400 gp), set into an old chieftain's belt-buckle, offered by her grandson for a good iron sword."],"Location"],
 ["v7-term-campaign-shapes","SHAPES OF THE CAMPAIGN","campaign length, short campaign, shorter campaign, skip, skipping, cut, pacing, one evening, merge sessions, shapes",["**The Seventh Bell is 28 sessions as written, but it doesn't have to be (7.23).** Every cut below is a card in its session. Waypoint tracks the flags, so the Forecast and the endings keep up, and nothing later breaks.","","| Shape | Evenings | How |","|---|---|---|","| The whole road | 28 | Every session as written, with the second Act IV road compressed into Sessions 20 and 21. |","| Brisk Glassreach | 26 | Run Sessions 10 and 11 as one evening (s10-one-evening), and 12 and 13 (s12-one-evening). |","| One road | 26 | Skip the second Act IV road and march on the Tor short-handed (s20-march-short-handed). |","| Both | 24 | Brisk Glassreach and one road. |","| The south road | 22 | Turn south before Glassreach (s10-leave-the-north): no Act III, and the Court holds the Frost Tongue and the Sexton. |","| The short campaign | 20 | The south road and one road. Two bells unrung; the Concord needs both back. |","","**What each cut costs.**","- **Only the Concord needs every bell.** The other five endings survive every cut. A bell left behind can still be rung: Session 22's detour (s22-detour-for-a-missed-bell) or, for Hieme, going back north (any-go-back-north).","- **The world notices.** Skip Glassreach and the Long Cold creeps south (any-the-cold-comes-south). March short-handed and the Court isn't ready (s22-short-handed-strike).","- **Levels catch up.** Each card says when to level, so the party arrives at the next act at the level it was written for.","","**Choosing.**","- **Cut travel and talk before dungeons.** The big dungeons (the Tithe-works, the Frost Spire, the Quiet Quarry) are where the campaign is most a game. Keep them if you can.","- **Ask the table.** \"Do we go into the glass?\" is a real choice, not a DM's shortcut. Put it to them in the fiction and let them pick.","- **Plan the shape at session zero** if you know how many evenings you have, and decide again at the end of each act."],"Lore"],
 ["v7-place-tithe-works","THE TITHE-WORKS, AREA BY AREA","Tithe-works, tithe works, service passage, back shelves, First Tallyman, Nell Quell",["**The Tithe-works as a dungeon (7.23): under the palace's service wing.** Before the Hall of Tithes had its vault, tithes were drawn and bottled down here, and the vault's service passage still runs through the old works to its back shelves. **This is Session 8's big dungeon:** the way to bring the jars out before the party leaves Hallowmere. Run it at dusk, between Scene 2 and the goodbyes, so the jars can be handed over in Scene 3. The play is *The Tithe-works: the dungeon under the palace*.","","- **Level 4.** About 1 hour 15 minutes the long way, 45 minutes the short way (areas 1, 2, the porters' lift, 8 and 9). The long way adds the patrol corridor, the bothy, the drawing-cistern, the bottling room and the cold store.","- **Where to break:** in the porters' bothy (area 4).","- **What doesn't change:** the Tithe Clock (tonight is still a night in the city), the hum (every spell hums within 30 feet, and the listening-pipes carry it), and the vault itself: no spells on the back shelves, and the HARVEST, WITHHELD shelf is still weighted.","- **Getting in:** Ilam's key and the Hushman roster (no roll), Ansel Quay if he's alive and Friendly, Thieves' Tools, or the coal chute.","","### 1. The service door (the kitchen yard)","> **SAY:** \"Behind the palace kitchens, past the bins and a sleeping cat, a low iron door is set into the wall under the service wing. Cut into the lintel above it, nearly worn away: TITHE-WORKS. RECEIVING.\"","- **Getting in:** Ilam's key opens it without a roll, and the roster says when the patrol passes. Ansel Quay, if he's alive and on their side, lets them in himself, with a lamp and a finger to his lips. Otherwise, Thieves' Tools DC 17 on the lock, or the coal chute: a group Stealth DC 14 across the yard, then a DC 12 Strength (Athletics) or Dexterity (Acrobatics) check to squeeze down it (on a failure, 1d4 Bludgeoning damage and a clatter Nell hears).","","### 2. The tally-room","> **SAY:** \"A long room lit by one lamp. Ledgers to the ceiling, a high desk, and at the desk a thin young woman in grey sleeves, writing so slowly you can hear the nib. Beside her hangs a bell-pull.\"","- **Nell Quell, night tallyman** (Commoner). Indifferent, frightened of the Court and more frightened of the First Tallyman. Influence DC 13 keeps her hand off the bell-pull (Advantage if Ilam vouches for them, for the roster, or for a small Gift); Friendly, she tells them about the funnel, the eels and the RETURNS crate. On a failure she pulls it, and the patrol comes in 4 rounds: *The Tithe-works patrol* in the Combat tab.","- **The day-books.** Investigation DC 12: the shelf numbers of every jar they want and, on the first page in brown ink, *Wystan Pellow, First Tallyman. Every memory weighed true.* The name matters in area 8.","- **The porters' lift:** a rope-and-pulley cage in the corner, down to the weighing room (area 8). It creaks: Nell works it for them, or a DC 12 Strength (Athletics) check lowers it quietly. It skips areas 3 to 7.","","### 3. The patrol corridor","> **SAY:** \"A brick corridor runs the length of the works, with brass pipes along the ceiling, each ending in a flared mouth like a speaking-trumpet. Far off: boots, and a voice counting.\"","- **Hushmen pass every ten minutes:** Stealth DC 15 to wait in the side-arches (the roster gives Advantage). A fight is *The Tithe-works patrol*.","- **Hazard: the listening-pipes.** They carry sound up to the guardroom. A spell's hum, a fight or a shout is heard: a group Stealth DC 13 passes quietly, and on a failure the patrol comes in 4 rounds. Cloth stuffed in a mouth, or Silence, stops one pipe.","","### 4. The porters' bothy","> **SAY:** \"A cramped room with a cold stove, four bunks and a kettle. Someone has chalked a tally on the wall, hundreds of strokes, and stopped. Under it, in the same hand: DON'T DRINK FROM THE CISTERN.\"","- **Rest:** a Short Rest here is safe; the patrol never looks in. Break here.","","### 5. The drawing-cistern","> **SAY:** \"Black water fills a round brick cistern, and a ledge a foot wide runs round it to the far arch. Something long and pale moves under the surface, and the air smells of rain on a day you can almost remember.\"","- **Memory-eels:** six of them, fed on the dregs of old tithes. They come up for anyone touching the water or in it: *The drawing-cistern* in the Combat tab. A bite means a DC 10 Wisdom saving throw or losing a minor memory until a Long Rest.","- **The ledge:** walking it is fine. Running, fighting or being hit on it means a DC 12 Dexterity saving throw or falling in, and the eels have Advantage against anyone in the water.","","### 6. The bottling room","> **SAY:** \"A low room full of empty jars on racks, thousands of them. In the middle, a ring of worn flagstones, and above it a great brass funnel hanging from the ceiling with its mouth pointing down.\"","- **Trap: the tithe-funnel.** It still draws. Perception DC 13 spots the worn ring and the scratches round it where people stood. Anyone who steps into the ring makes a DC 13 Wisdom saving throw or takes 2d6 Psychic damage and loses a minor memory until a Long Rest (you pick: a name, a tune, a smell). Stuffing its mouth, or turning its wheel shut (Investigation DC 12 to find the wheel), disarms it.","- **Treasure: the RETURNS crate,** behind the racks (Investigation DC 14, or Nell tells them). It's meant for jars nobody wanted, and holds the porters' stash instead: Gloves of Thievery, 50 gp and two Potions of Healing.","","### 7. The cold store (optional)","> **SAY:** \"A vaulted cellar, cold as a well. On slate shelves, jars stand in frost, each labelled in red: HELD.\"","- **The held jars** are memories the Court wouldn't sell or return: a Bellwright's lullaby, a knight's oath, a road that isn't on any map. Nobody guards them. Opening one is witnessing it, and it fades.","- **A personal beat:** if a character is due one (Prep names them), put a jar here that belongs to someone they love.","","### 8. The weighing room (the First Tallyman)","> **SAY:** \"A tall hall with a great brass scale in the middle, its pans as wide as cartwheels. Half the hall is lined with grey stone that stops in a ragged edge, as if the masons walked off mid-wall. By the scale stands a man in an old-fashioned tallyman's coat, pale as candle smoke, with a ledger open in his hands. Two shapes without faces stand at his elbows.\"","- **The First Tallyman,** Wystan Pellow, weighed the first tithes and never stopped. Use the Ghost; his two **Hollowed** are Specters, people tithed down to nothing. He asks each of them what they're carrying out, and attacks anyone who carries a jar past the scale unweighed: *The First Tallyman* in the Combat tab.","- **He stands down for his own name.** Read it back to him from the day-book in area 2, and he closes the ledger, says \"Weighed true,\" and stands aside, and the Hollowed with him. He never leaves the works.","- **The half-finished wall:** the half of the hall by the shelf door is silence-stone, so no spells can be cast there, by either side. The porters' lift comes down in the other half.","","### 9. The back shelves","> **SAY:** \"A narrow door opens onto the back of the vault: the same long shelves, the same jars, seen from behind. A single lamp burns on the newest shelf.\"","- **The jars:** Mara Bray's (BRAY, M. 408 SS), Ilam's (BRAY, I.: the day he named his son), Bet's, Mother Sallow's, and any others left behind in Session 5. Only the owner can open a jar; witnessing another's fades it. With the day-book's shelf numbers they're found at once; without them it takes 30 minutes and a roll on the table below.","- **Calla's Heart,** if it's still on the HARVEST, WITHHELD shelf, is twenty feet away. The shelf is still weighted: lifting it rings the alarm as in Session 5 (record it with s05-take-calla), and Hushmen come down the front stair in 3 rounds. The way out is back through the works.","- **Getting out:** the way they came, or up the lift. Ansel's morning tally finds the gaps.","","**Below the palace.** Roll a d6 when they rest, or when the table goes quiet.","","| d6 | What happens |","|---|---|","| 1 | The patrol passes overhead: boots and a laugh through a grating. |","| 2 | A jar on a shelf rattles. Whoever is nearest catches a stranger's memory (a wedding, a fire) and keeps it until morning. |","| 3 | Upstairs, the shift bell rings once: for ten minutes, the patrol comes by twice as often. |","| 4 | Two memory-eels in a drain, hungry. |","| 5 | A pipe nearby starts to hum. Somebody, somewhere, cast a spell, and the guardroom is listening. |","| 6 | Ansel's lamp comes along the shelves, and his voice, counting under his breath (a Hushman Sergeant on his rounds, if Ansel is dead). |","","**Rewards inside.** Gloves of Thievery, 50 gp and two Potions of Healing (area 6); the jars (area 9); Nell's goodwill; Calla's Heart, if they dare."],"Location"],
 ["v7-place-quiet-quarry","THE QUIET QUARRY, AREA BY AREA","Quiet Quarry, silence-stone quarry, Court quarry, Old Patient, Mother Seam, Dagny Thurl",["**The Quiet Quarry as a dungeon (7.23): where the Wardens' stones are cut.** Every silence-stone the Court carries comes out of one hill on the Tor road, a day north of the ridge, and the column always stops there so the Wardens can take on fresh stones: a stone goes dull after a season on the road. **This is Session 22's big dungeon:** get ahead of the column by Ansel's goat-path, arrive by noon, and spoil or steal the fresh stock before the column comes in at dusk. It's the ambush or the quarry, not both. The play is *The Quiet Quarry: spoil the Wardens' stones*.","","- **Level 9.** About 1 hour 15 to 1 hour 30 the long way, 45 minutes the short way (areas 1, 4, 7 and 9). The long way adds the cutters' terraces, the overseers' house, the dead galleries, the pump-room and the Mother Seam.","- **Where to break:** in the pump-room (area 6).","- **What doesn't change:** silence-stone drinks sound and stops spells. Raw stone does it everywhere in the dead galleries, and each Warden still carries a Warden's Stone (a 10-foot Emanation where spells can't be cast). **Only dry stone works:** soaked silence-stone is just stone for a month, and that's the quarry's weak point.","- **The clock:** the column comes in at dusk, about six hours after they arrive. If they're still inside, the quarry guard doubles and the Wardens come looking.","","### 1. The rim","> **SAY:** \"The goat-path comes out on the lip of a great grey bowl cut into the hill. Terraces step down to a floor far below, where cut blocks sit in rows like graves. There's no sound. Not a hammer, not a bird. A crane's arm leans out over the drop with a bucket hanging from it.\"","- **Getting here:** Ansel's goat-path (or his route-book, if he's dead) brings them to the rim by noon, unseen, with no roll. By the road gate instead: a Court agent checks writs (Deception DC 16), or there's a fight at the gate that the overseers' house hears.","- **From the rim:** the bucket-crane goes straight down to the cutting floor (area 4); the cutters' stair winds down the terraces (area 2).","","### 2. The cutters' terraces","> **SAY:** \"Men and women in grey smocks work the stone with wooden wedges and water, in perfect silence. Nobody looks up. One older woman with arms like hawsers watches you the whole way down, and lifts one hand, flat, palm down.\"","- **The cutters are Blanks,** Tithed down to their trade and sent where nothing they hear matters. They talk in hand-signs. If the Blanks are the party's allies (s22-ally-blanks), some of these faces know them.","- **Dagny Thurl, foreman** (Commoner), isn't a Blank: she's cut silence-stone for thirty years and hates where it goes. Friendly if they're kind to her cutters, Influence DC 15 otherwise. She knows the guard's shifts, the chalk marks in the dead galleries, the sluice and the Mother Seam, and she teaches them the sign for \"rest\" (palm down, then a closed fist). It matters in area 7.","","### 3. The overseers' house","> **SAY:** \"A squat stone house at the foot of the terraces, with smoke from the chimney and boots on the porch. Through the window, a row of grey stones hangs on pegs like keys, each on a leather thong.\"","- **The quarry guard:** two Hushman Wardens, a Sergeant, six Hushmen and a Court agent, off duty until the column comes. A fight here is *The quarry guard* in the Combat tab; they'd rather bar the house and send a runner to the column than die. Sneaking past: group Stealth DC 15.","- **The stones on the pegs** are the Wardens' spares. Lifted through the window (Sleight of Hand DC 15), they count as stolen stock.","","### 4. The bucket-crane (the shortcut)","> **SAY:** \"The bucket is big enough for four, and its chain runs two hundred feet down to the cutting floor. On the rim, a winch with a brake lever.\"","- **Going down:** one character works the winch from the rim, or they let it down by the brake from inside the bucket (a DC 14 Strength (Athletics) check, or it drops the last 30 feet: 3d6 Bludgeoning damage to everyone in it). It skips areas 2, 3, 5 and 6.","- **It's in plain sight of the overseers' house:** a group Stealth DC 15 (Advantage if Dagny's cutters raise dust for them), or the quarry guard reaches the cutting floor 5 rounds after they do.","","### 5. The dead galleries","> **SAY:** \"The old workings run back into the hill, black tunnels through raw silence-stone. Step inside and the world goes deaf: you can see your friend's mouth moving a few feet away, and hear nothing at all.\"","- **Raw stone:** no spells can be cast in the galleries, and no sound carries more than 10 feet. Talk is by touch, sign or chalk.","- **The way through:** follow the old chalk marks (Dagny explains them) or make a DC 15 Wisdom (Survival) check. On a failure they lose 30 minutes and roll on the table below.","- **Trap: the deadfall.** A propped roof-slab over a narrowing. Perception DC 15 spots the chalk warning (a crossed circle) scratched beside it; disarming it is a DC 15 Dexterity check with Thieves' Tools, or they go round (30 minutes). Anyone under it when it falls makes a DC 15 Dexterity saving throw, taking 4d10 Bludgeoning damage on a failure, or half as much on a success.","- **Two Xorns** graze the seams. They're hungry, not cruel: 25 gp in silver or a gem each, and they sink into the stone and leave the party alone. Otherwise, or if anyone draws steel near them, *The Xorns* in the Combat tab.","","### 6. The pump-room","> **SAY:** \"A dry chamber at the end of the galleries, with a cold brazier, coils of rope, and a great iron wheel on the wall, rusted half-shut. Through a grating beside it you can hear water. A lot of water.\"","- **Rest:** a Short Rest here is safe; the guard never comes this deep. Break here.","- **The sluice.** Turning the wheel (a DC 15 Strength (Athletics) check, or two people and ten minutes) empties the old drainage cistern onto the cutting floor. It floods knee-deep in 2 rounds: Difficult Terrain, and every silence-stone in the water goes dull for a month. That spoils the fresh stock in its open cases; any Warden knocked Prone in it soaks his own stone. The guard hears the water and comes in 5 rounds.","","### 7. The cutting floor (Old Patient)","> **SAY:** \"The floor of the bowl, open to the sky. Rows of cut blocks, and against the back wall twelve open lead cases, each holding a grey stone the size of a fist. Beside them, sitting with its hands on its knees like a tired labourer, is a giant of the same grey stone. Two Hushman Wardens stand over the cases.\"","- **Old Patient** is the quarry's golem, carved by the first cutters to haul their blocks and kept by the Court as a guard. Use the Stone Golem. With it, two Hushman Wardens, each with a Warden's Stone: *Old Patient* in the Combat tab.","- **It stands down for the cutters' sign.** Show it \"rest\" (palm down, then a closed fist), which Dagny teaches or a character works out by watching the cutters (Insight DC 15), and it sits back down. The Wardens don't.","- **The fresh stock:** twelve Warden's Stones in lead cases, waiting for the column. Spoil them: flood the floor from the pump-room, soak them at the cutters' troughs (a minute each), or smash them (AC 12, 10 HP each). Or steal them: the cases weigh 20 pounds each. Either way, at the Strike the Wardens march on stones gone dull: their Emanations reach only 5 feet.","","### 8. The Mother Seam (hidden)","> **SAY:** \"Behind a slab at the back of the floor, a crack opens into a little chamber where the stone is black and glassy, so pure it hurts your ears. Someone has left a stool here, a candle stub, and a tin box.\"","- **Finding it:** Dagny tells them, or Investigation DC 16 at the back wall finds the cutters' mark beside the slab: an open hand.","- **Treasure: the quarry-master's tin.** He ran the quarry before the Court took it, and hid here from them for a year. Inside: an Amulet of Proof against Detection and Location, three garnets (100 gp each) and two Potions of Greater Healing.","","### 9. The spoil chute","> **SAY:** \"A long stone chute runs from the cutting floor down the hillside to the road, slick with grey dust, where the cutters send down the broken stone.\"","- **Out:** slide it (a DC 12 Dexterity (Acrobatics) check, or 2d6 Bludgeoning damage at the bottom) and they're on the Tor road below the quarry, a mile ahead of the column, or right in front of it if they're late.","","**In the quiet.** Roll a d6 when they rest, or when the table goes quiet.","","| d6 | What happens |","|---|---|","| 1 | Somewhere a block drops. Nobody hears it; everyone feels it through their boots. |","| 2 | A cutter stops work, looks straight at the nearest character, and signs \"go back\". |","| 3 | Two Hushmen push a barrow of fresh stones across the floor, grumbling about the column. |","| 4 | A Xorn's head rises out of the floor, sniffs at the nearest purse, and sinks again. |","| 5 | The overseers' horn: the column's outriders are early. It arrives an hour sooner. |","| 6 | A cloud of silence-stone dust drifts out of the galleries. For a minute, nobody in it can hear a thing or cast a spell. |","","**Rewards inside.** An Amulet of Proof against Detection and Location, three garnets and two Potions of Greater Healing (area 8); the Wardens' spare stones (area 3); Dagny's sign; and a column that marches on dull stones."],"Location"],
]) if (kind==='NPC') pages.push({id,title,kind,status:'Confirmed',visibility:'DM only',aliases,body:lines.join('\n')}); else lorePage(id,title,aliases,lines.join('\n'),kind);
module.exports={pages,pageEdits,cardEdits,sessions,campaign,planner,pellmoorBody,remove};
